INSERT INTO `juegos` (`idJuego`, `idApi`, `nombreJuego`, `desarrolladorJuego`, `editorJuego`, `anoJuego`, `franquiciaJuego`, `generoJuego`, `plataformasJuego`, `dlcJuego`, `expansionJuego`, `duracionJuego`, `ratingAvgJuego`, `posterJuego`, `sinopsisJuego`) VALUES
(13, 1221, 'Kingdom Hearts II', 'Square Enix Product Development Division 1', 'Square Enix', 2005, 'Kingdom Hearts', 'Role-playing (RPG), Adventure', 'PlayStation 2', NULL, NULL, '32.7 h', 4.4, 'https://images.igdb.com/igdb/image/upload/t_cover_big_2x/co30t1.jpg', 'Kingdom Hearts II is an action role-playing game, and the primary entry to the series since the 2002 Disney Interactive and Square collaboration. The game\'s setting is a collection of various levels (referred to in-game as \"worlds\") that the player progresses through. As in the first game, it II allows the player to travel to locales from various Disney works, along with original worlds specifically created for the series.'),
(15, 11737, 'Outer Wilds', 'Mobius Digital', 'Annapurna Interactive, Limited Run Games', 2019, NULL, 'Puzzle, Simulator, Adventure, Indie', 'Xbox Series X|S, PlayStation 4, PC, PlayStation 5, Xbox One, Nintendo Switch', NULL, 'Outer Wilds: Echoes of the Eye', '19 h', 4.5, 'https://images.igdb.com/igdb/image/upload/t_cover_big_2x/co65ac.jpg', 'Outer Wilds is a critically-acclaimed and award-winning open world mystery about a solar system trapped in an endless time loop. The newest member of the space program in a small village on the planet Timber Hearth, the player navigates a space shuttle and travels across their solar system to get to the bottom of its mysteries by exploring the cosmos and gathering the knowledge hidden within each of the system\'s planets, left behind by another civilization in the distant past.'),
(18, 340349, 'Final Fantasy IX', 'Square, Guild Studio Inc., Silicon Studio', 'Square Enix', 2016, 'Final Fantasy', 'Role-playing (RPG), Adventure', 'PC', NULL, NULL, NULL, 4.0, 'https://images.igdb.com/igdb/image/upload/t_cover_big_2x/cob2dk.jpg', 'The PC version of Final Fantasy IX features high-resolution character models, improved FMVs and modern enhancements such as auto-save, fast-forward and battle boosters. It supports both controller and keyboard/mouse input. The Steam release also includes achievements and allows for community-created mods, including the popular Moguri Mod, which restores original-style backgrounds and audio.'),
(19, 306141, 'Mio: Memories in Orbit', 'Douze Dixièmes', 'Focus Entertainment', 2026, NULL, 'Platform, Adventure, Indie, Arcade', 'Xbox Series X|S, PlayStation 4, Nintendo Switch 2, PC, PlayStation 5, Xbox One, Nintendo Switch', NULL, NULL, '23 h', 3.7, 'https://images.igdb.com/igdb/image/upload/t_cover_big_2x/co8tkh.jpg', 'MIO: Memories in Orbit is a 2.5D side-scrolling metroidvania platformer. Players control a robot named Mio who explores a vast spaceship called the Vessel, gaining new abilities such as wall climbing, dodging, grappling, and gliding while fighting machines that have gone rogue. Combat emphasizes aerial fighting, and players can equip modifiers that adjust their abilities at the cost of modifier slots. Currency called Nacre is used to purchase upgrades and is lost on death, and fast-travel devices serve as save points across the ship.'),
(20, 305152, 'Clair Obscur: Expedition 33', 'Sandfall Interactive', 'Kepler Interactive', 2025, NULL, 'Role-playing (RPG), Turn-based strategy (TBS), Adventure, Indie', 'Xbox Series X|S, PC, PlayStation 5', NULL, NULL, '41.1 h', 4.6, 'https://images.igdb.com/igdb/image/upload/t_cover_big_2x/co9gam.jpg', 'Lead the members of Expedition 33 on their quest to destroy the Paintress so that she can never paint death again. Explore a world of wonders inspired by Belle Époque France and battle unique enemies in this turn-based RPG with real-time mechanics.');
INSERT INTO `libros` (`idLibro`, `idApi`, `nombreLibro`, `autorLibro`, `anoLibro`, `generoLibro`, `temaLibro`, `paginasLibro`, `edicionesLibro`, `idiomaLibro`, `ratingAvgLibro`, `posterLibro`, `sinopsisLibro`) VALUES
(1, '/works/OL82563W', 'Harry Potter and the Philosopher\'s Stone', 'J. K. Rowling', 1997, 'school stories, Juvenile fiction, Fiction, fantasy fiction, Juvenile literature, Fantasy, Mystery, Adventure, Young Adult, Middle Grade, Classics', 'Ghosts, Monsters, Vampires, Magic, Friendship, Mystery, Adventure, Supernatural', 302, 399, 'hin, lav, heb, eng, por, swe, rus, gla, tib, hrv, vie, grc, nor, spa, cat, tur, yid, ice, dut, chi, bul, ltz, urd, jpn, ita, hun, alb, fre, cze, ger, rum, kal, fin, dan, gle, lit, ukr, kor, lat, mar, tha, gre, ben, wel, nep, ara, pol, afr, per', 4.2, 'images/libros/15155833.jpg', 'Turning the envelope over, his hand trembling, Harry saw a purple wax seal bearing a coat of arms; a lion, an eagle, a badger and a snake surrounding a large letter \'H\'.\r\n\r\nHARRY POTTER has never even heard of Hogwarts when the LETTERS start dropping on the doormat at number four, Privet Drive. Addressed in GREEN INK on yellowish parchment with a PURPLE SEAL, they are swiftly confiscated by his GRISLY aunt and uncle. Then, on Harry\'s eleventh birthday, a great beetle-eyed giant of a man called RUBEUS HAGRID bursts in with some ASTONISHING news: Harry Potter is a wizard, and he has a place at Hogwarts School of Witchcraft and Wizardry. An incredible adventure is about to begin!');
INSERT INTO `peliculas` (`idPelicula`, `idApi`, `nombrePelicula`, `directorPelicula`, `actorPelicula`, `guionistaPelicula`, `generoPelicula`, `anoPelicula`, `companiaPelicula`, `duracionPelicula`, `ratingAvgPelicula`, `paisPelicula`, `idiomaPelicula`, `posterPelicula`, `sinopsisPelicula`) VALUES
(1, 157353, 'Transcendence', 'Wally Pfister', 'Johnny Depp, Rebecca Hall, Paul Bettany, Cillian Murphy, Kate Mara, Cole Hauser', 'Wally Pfister', 'Thriller, Science Fiction, Drama, Mystery', 2014, 'Alcon Entertainment, DMG Entertainment, Straight Up Films', '119', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/i3JqPtiJWnidaif3UA2K2Eng0hp.jpg', 'Two leading computer scientists work toward their goal of Technological Singularity,  as a radical anti-technology organization fights to prevent them from creating a world where computers can transcend the abilities of the human brain.'),
(2, 82700, 'After Earth', 'M. Night Shyamalan', 'Jaden Smith, Will Smith, Sophie Okonedo, Zoë Kravitz, Glenn Morshower, Kristofer Hivju', 'M. Night Shyamalan, Gary Whitta', 'Science Fiction, Action, Adventure', 2013, 'Columbia Pictures, Overbrook Entertainment, Blinding Edge Pictures', '100', 2.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/iXMvYIlzzJBs352CfeiQcBvovZt.jpg', 'One thousand years after cataclysmic events forced humanity\'s escape from Earth, Nova Prime has become mankind\'s new home. Legendary General Cypher Raige returns from an extended tour of duty to his estranged family, ready to be a father to his 13-year-old son, Kitai. When an asteroid storm damages Cypher and Kitai\'s craft, they crash-land on a now unfamiliar and dangerous Earth. As his father lies dying in the cockpit, Kitai must trek across the hostile terrain to recover their rescue beacon. His whole life, Kitai has wanted nothing more than to be a soldier like his father. Today, he gets his chance.'),
(3, 76338, 'Thor: The Dark World', 'Alan Taylor', 'Chris Hemsworth, Natalie Portman, Tom Hiddleston, Christopher Eccleston, Anthony Hopkins, Jaimie Alexander', 'Stephen McFeely, Christopher Markus, Christopher L. Yost', 'Action, Adventure, Fantasy', 2013, 'Marvel Studios', '112', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/wp6OxE4poJ4G7c0U2ZIXasTSMR7.jpg', 'Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.'),
(4, 37686, 'Super 8', 'J.J. Abrams', 'Joel Courtney, Elle Fanning, Riley Griffiths, Kyle Chandler, Noah Emmerich, AJ Michalka', 'J.J. Abrams', 'Thriller, Science Fiction, Mystery', 2011, 'Paramount Pictures, Amblin Entertainment, Bad Robot', '112', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/pUWIjaMMYJjeBm5bJyE3mIXdQ62.jpg', 'In late 1970s Ohio, a group of friends filming a homemade zombie movie witness a devastating train derailment. Soon after, their quiet town is gripped by unexplained disappearances, strange phenomena, and a growing sense of fear, as they uncover that something terrifying has been set loose.'),
(5, 169, 'Predator 2', 'Stephen Hopkins', 'Danny Glover, Gary Busey, Rubén Blades, María Conchita Alonso, Bill Paxton, Robert Davi', 'Stephen Hopkins', 'Science Fiction, Action, Thriller', 1990, 'Davis Entertainment, Lawrence Gordon Productions, Silver Pictures, 20th Century Fox', '108', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/83X4VwY9sdSJykskmsplIVG0a4h.jpg', 'A police chief in the war-torn streets of Los Angeles discovers that an extraterrestrial creature is hunting down residents - and that he is the next target.'),
(6, 43431, 'The Longest Penalty Shot in the World', 'Roberto Santiago', 'Fernando Tejero, María Botto, Marta Larralde, Carlos Kaniowsky, Javier Gutiérrez, Enrique Villén', 'Roberto Santiago', 'Comedy', 2005, 'Tornasol Media, Ensueño Films', '100', 2.7, 'ES', 'Español', 'https://image.tmdb.org/t/p/w500/hCHM8G50TUOpAf7CIdxKcKZo9Nu.jpg', 'Fernando (Fernando Tejero) is a loser. A gray type, without ambition, that works like bookcases distributor in a supermarket of the quarter. In his free short whiles, he is a substitute keeper of a football team, a third regional one. In all the season he has not played a single minute. But the last Sunday of the league the referee indicates penalty and the regular keeper injures itself. Fernando must occupy the goal for the first time. If penalty scores, the team of the district will proclaim champion. If no, all the effort of a year will not have been worth for anything. When the penalty is just about to be kicked, a group of indignant fans with the referee invades the field and prevents the kick. The competition committee decides that the penalty must play the following Sunday, in the same goal, with same players and the field closed to the public. El Penalti más largo del mundo, (The Longest Penalty Shot in the World) is exactly the history of that week of delay.'),
(7, 3594, 'The Number 23', 'Joel Schumacher', 'Jim Carrey, Virginia Madsen, Logan Lerman, Danny Huston, Lynn Collins, Rhona Mitra', 'Fernley Phillips', 'Thriller, Mystery, Crime, Drama', 2007, 'Firm Films, New Line Cinema, Contrafilm', '97', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/iPJwdvgX3I5dEw9QhDOG3hxUvMp.jpg', 'Animal control officer Walter Sparrow becomes obsessed with a novel that he believes was written about him, as more and more similarities between himself and his literary alter ego seem to arise.'),
(8, 12536, 'Home Alone 4', 'Rod Daniel', 'Mike Weinberg, French Stewart, Missi Pyle, Erick Avari, Barbara Babcock, Jason Beghe', 'Debra Frank, Steve L. Hayes', 'Comedy, Family, TV Movie', 2002, 'Fox Television Studios', '84', 2.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/qRktvMOO2QaCL7gvNyvZDoxPOZj.jpg', 'Kevin McCallister\'s parents have split up. Now living with his mom, he decides to spend Christmas with his dad at the mansion of his father\'s rich girlfriend, Natalie. Meanwhile robber Marv Merchants, one of the villains from the first two movies, partners up with a new criminal named Vera to hit Natalie\'s mansion.'),
(9, 2268, 'The Golden Compass', 'Chris Weitz', 'Dakota Blue Richards, Nicole Kidman, Daniel Craig, Ben Walker, Freddie Highmore, Ian McKellen', 'Chris Weitz', 'Adventure, Fantasy', 2007, 'Depth of Field, New Line Cinema, Scholastic Productions, Ingenious Media', '113', 3.0, 'GB, US', 'Íslenska, English, Pусский, Français', 'https://image.tmdb.org/t/p/w500/6DTH9poR8RAw859L6OuokT7z993.jpg', 'In a parallel universe, after overhearing a shocking secret, precocious orphan Lyra Belacqua trades her carefree existence roaming the halls of Jordan College for an otherworldly adventure in the far North, unaware that it\'s part of her destiny.'),
(10, 338952, 'Fantastic Beasts: The Crimes of Grindelwald', 'David Yates', 'Eddie Redmayne, Katherine Waterston, Dan Fogler, Alison Sudol, Johnny Depp, Jude Law', 'J.K. Rowling', 'Fantasy, Adventure', 2018, 'Warner Bros. Pictures, Heyday Films', '134', 3.4, 'US, GB', 'English, Français', 'https://image.tmdb.org/t/p/w500/fMMrl8fD9gRCFJvsx0SuFwkEOop.jpg', 'Gellert Grindelwald has escaped imprisonment and has begun gathering followers to his cause—elevating wizards above all non-magical beings. The only one capable of putting a stop to him is the wizard he once called his closest friend, Albus Dumbledore. However, Dumbledore will need to seek help from the wizard who had thwarted Grindelwald once before, his former student Newt Scamander, who agrees to help, unaware of the dangers that lie ahead. Lines are drawn as love and loyalty are tested, even among the truest friends and family, in an increasingly divided wizarding world.'),
(11, 76493, 'The Dictator', 'Larry Charles', 'Sacha Baron Cohen, Ben Kingsley, Anna Faris, Jason Mantzoukas, Sayed Badreya, Adeel Akhtar', 'Alec Berg, Sacha Baron Cohen, David Mandel', 'Comedy', 2012, 'Paramount Pictures, Berg Mandel Schaffer Productions, Scott Rudin Productions, Four by Two Films', '83', 3.1, 'US', 'English, עִבְרִית', 'https://image.tmdb.org/t/p/w500/n0W7kajF4GFMRk2c0wWwMQqTaDM.jpg', 'The heroic story of a dictator who risks his life to ensure that democracy would never come to the country he so lovingly oppressed.'),
(12, 49519, 'The Croods', 'Kirk DeMicco', 'Nicolas Cage, Emma Stone, Ryan Reynolds, Catherine Keener, Cloris Leachman, Clark Duke', 'Chris Sanders, Kirk DeMicco', 'Animation, Adventure, Family, Comedy', 2013, 'DreamWorks Animation', '99', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/27zvjVOtOi5ped1HSlJKNsKXkFH.jpg', 'The prehistoric Croods family live in a particularly dangerous moment in time. Patriarch Grug, his mate Ugga, teenage daughter Eep, son Thunk, and feisty Gran gather food by day and huddle together in a cave at night. When a more evolved caveman named Guy arrives on the scene, Grug is distrustful, but it soon becomes apparent that Guy is correct about the impending destruction of their world.'),
(13, 423108, 'The Conjuring: The Devil Made Me Do It', 'Michael Chaves', 'Vera Farmiga, Patrick Wilson, Sterling Jerins, Sarah Catherine Hook, Ruairí O\'Connor, Julian Hilliard', 'David Leslie Johnson-McGoldrick', 'Horror, Mystery, Thriller', 2021, 'New Line Cinema, The Safran Company, Atomic Monster', '111', 3.7, 'US', 'English, Português', 'https://image.tmdb.org/t/p/w500/xbSuFiJbbBWCkyCCKIMfuDCA4yV.jpg', 'Paranormal investigators Ed and Lorraine Warren encounter what would become one of the most sensational cases from their files. The fight for the soul of a young boy takes them beyond anything they\'d ever seen before, to mark the first time in U.S. history that a murder suspect would claim demonic possession as a defense.'),
(14, 9982, 'Chicken Little', 'Mark Dindal', 'Zach Braff, Garry Marshall, Don Knotts, Amy Sedaris, Steve Zahn, Joan Cusack', 'Ron Anderson, Steve Bencich, Ron J. Friedman', 'Animation, Family, Comedy', 2005, 'Walt Disney Pictures, Walt Disney Feature Animation', '81', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/87FpA4b90eTaw3U6zmCNikoPLir.jpg', 'When the sky really is falling and sanity has flown the coop, who will rise to save the day? Together with his hysterical band of misfit friends, Chicken Little must hatch a plan to save the planet from alien invasion and prove that the world\'s biggest hero is a little chicken.'),
(15, 49013, 'Cars 2', 'John Lasseter', 'Larry the Cable Guy, Owen Wilson, Michael Caine, Emily Mortimer, Suzy Eddie Izzard, John Turturro', 'Ben Queen', 'Animation, Family, Adventure, Comedy', 2011, 'Pixar, Walt Disney Pictures', '106', 3.1, 'US', 'English, Français, Deutsch, Italiano, 日本語', 'https://image.tmdb.org/t/p/w500/okIz1HyxeVOMzYwwHUjH2pHi74I.jpg', 'Star race car Lightning McQueen and his pal Mater head overseas to compete in the World Grand Prix race. But the road to the championship becomes rocky as Mater gets caught up in an intriguing adventure of his own: international espionage.'),
(16, 172457, 'Afterparty', 'Miguel Larraya', 'Úrsula Corberó, Alicia Sanz, David Seijo, Andrea Dueso, Eva Ugarte, Rocío León', 'Miguel Larraya', 'Horror', 2013, 'Álvaro Agustín', '80', 2.1, 'ES', 'Español', 'https://image.tmdb.org/t/p/w500/gSy0kRoVIM9EYjMl1UuGZBXZ5Lo.jpg', 'Martin is the star of \"Camp Blood\", a hit TV show and one of the biggest teen idols of the time. One morning wake up locked in a huge house after a wild party with three girls I met last night. Through a mobile from which can´t call, start receiving videos showing the deaths of younger locked in the house, run by a mysterious figure dressed as the murderer who appears in the series starring Martin.'),
(17, 27022, 'The Sorcerer\'s Apprentice', 'Jon Turteltaub', 'Nicolas Cage, Jay Baruchel, Alfred Molina, Teresa Palmer, Toby Kebbell, Omar Benson Miller', 'Doug Miro, Carlo Bernard', 'Fantasy, Adventure, Action', 2010, 'Walt Disney Pictures, Jerry Bruckheimer Films, Saturn Films, Broken Road Productions, Junction Entertainment', '109', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/b5pIUsGll0418NyfNA5eYCI9aoK.jpg', 'Balthazar Blake is a master sorcerer in modern-day Manhattan trying to defend the city from his arch-nemesis, Maxim Horvath. Balthazar can\'t do it alone, so he recruits Dave Stutler, a seemingly average guy who demonstrates hidden potential, as his reluctant protégé. The sorcerer gives his unwilling accomplice a crash course in the art and science of magic, and together, these unlikely partners work to stop the forces of darkness.'),
(18, 76649, 'Pompeii', 'Paul W. S. Anderson', 'Kit Harington, Emily Browning, Adewale Akinnuoye-Agbaje, Kiefer Sutherland, Carrie-Anne Moss, Jared Harris', 'Lee Batchler, Janet Scott Batchler, Michael Robert Johnson', 'Action, Adventure, History, Romance, Drama', 2014, 'Constantin Film, Impact Pictures, Don Carmody Productions, FilmDistrict, TriStar Pictures', '105', 2.8, 'CA, DE', 'English', 'https://image.tmdb.org/t/p/w500/dxxM3lLDjGRC50i5rhvfQziskAN.jpg', 'In 79 A.D., Milo, a slave turned gladiator, finds himself in a race against time to save his true love Cassia, the beautiful daughter of a wealthy merchant who has been unwillingly betrothed to a corrupt Roman Senator. As Mount Vesuvius erupts in a torrent of blazing lava, Milo must fight his way out of the arena in order to save his beloved as the once magnificent Pompeii crumbles around him.'),
(19, 254470, 'Pitch Perfect 2', 'Elizabeth Banks', 'Anna Kendrick, Brittany Snow, Hailee Steinfeld, Rebel Wilson, Ester Dean, Adam Devine', 'Elizabeth Banks', 'Comedy, Music', 2015, 'Brownstone Productions, Gold Circle Films, Universal Pictures', '115', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/fQaEGzFmvTYu3G641WV0Tg9auAt.jpg', 'The Bellas are back, and they are better than ever. After being humiliated in front of none other than the President of the United States of America, the Bellas are taken out of the Aca-Circuit. In order to clear their name, and regain their status, the Bellas take on a seemingly impossible task: winning an international competition no American team has ever won. In order to accomplish this monumental task, they need to strengthen the bonds of friendship and sisterhood and blow away the competition with their amazing aca-magic! With all new friends and old rivals tagging along for the trip, the Bellas can hopefully accomplish their dreams.'),
(20, 166426, 'Pirates of the Caribbean: Dead Men Tell No Tales', 'Espen Sandberg', 'Johnny Depp, Javier Bardem, Geoffrey Rush, Brenton Thwaites, Kaya Scodelario, Golshifteh Farahani', 'Jeff Nathanson', 'Adventure, Action, Fantasy', 2017, 'Walt Disney Pictures, Jerry Bruckheimer Films, Infinitum Nihil', '129', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg', 'Thrust into an all-new adventure, a down-on-his-luck Capt. Jack Sparrow feels the winds of ill-fortune blowing even more strongly when deadly ghost sailors led by his old nemesis, the evil Capt. Salazar, escape from the Devil\'s Triangle. Jack\'s only hope of survival lies in seeking out the legendary Trident of Poseidon, but to find it, he must forge an uneasy alliance with a brilliant and beautiful astronomer and a headstrong young man in the British navy.'),
(22, 240832, 'Lucy', 'Luc Besson', 'Scarlett Johansson, Morgan Freeman, Choi Min-sik, Amr Waked, Julian Rhind-Tutt, Pilou Asbæk', 'Luc Besson', 'Action, Science Fiction', 2014, 'EuropaCorp, Canal+, Ciné+, TF1 Films Production', '89', 3.2, 'FR', '普通话, English, Français, Español, 한국어/조선말', 'https://image.tmdb.org/t/p/w500/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg', 'A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.'),
(23, 11430, 'The Lion King 1½', 'Bradley Raymond', 'Nathan Lane, Ernie Sabella, Julie Kavner, Jerry Stiller, Matthew Broderick, Robert Guillaume', 'Tom Rogers', 'Adventure, Animation, Comedy, Family', 2004, 'DisneyToon Studios', '77', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/u2hN0WT7Dz46HfhQbr6uzSYfVW4.jpg', 'Timon the meerkat and Pumbaa the warthog are best pals and the unsung heroes of the African savanna. This prequel to the smash Disney animated adventure takes you back -- way back -- before Simba\'s adventure began. You\'ll find out all about Timon and Pumbaa and tag along as they search for the perfect home and attempt to raise a rambunctious lion cub.'),
(24, 474350, 'It Chapter Two', 'Andy Muschietti', 'Jessica Chastain, James McAvoy, Bill Hader, Isaiah Mustafa, Jay Ryan, James Ransone', 'Gary Dauberman, Jason Fuchs', 'Horror, Thriller, Drama', 2019, 'Vertigo Entertainment, Double Dream, Rideback, New Line Cinema', '169', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/zfE0R94v1E8cuKAerbskfD3VfUt.jpg', '27 years after overcoming the malevolent supernatural entity Pennywise, the former members of the Losers\' Club, who have grown up and moved away from Derry, are brought back together by a devastating phone call.'),
(25, 13700, 'Home on the Range', 'Will Finn', 'Roseanne Barr, Judi Dench, Jennifer Tilly, Steve Buscemi, G.W. Bailey, Cuba Gooding Jr.', 'Will Finn, John Sanford', 'Animation, Family', 2004, 'Walt Disney Pictures, Walt Disney Feature Animation', '76', 3.0, 'US', '普通话, English', 'https://image.tmdb.org/t/p/w500/cgKnkbO3fNWwKc9qLyLYdeZQ9Vj.jpg', 'When a greedy outlaw schemes to take possession of the \"Patch Of Heaven\" dairy farm, three determined cows, a karate-kicking stallion and a colorful corral of critters join forces to save their home. The stakes are sky-high as this unlikely animal alliance risk their hides and match wits with a mysterious band of bad guys.'),
(26, 767, 'Harry Potter and the Half-Blood Prince', 'David Yates', 'Daniel Radcliffe, Rupert Grint, Emma Watson, Jim Broadbent, Michael Gambon, Tom Felton', 'Steve Kloves', 'Adventure, Fantasy', 2009, 'Warner Bros. Pictures, Heyday Films', '153', 3.8, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/z7uo9zmQdQwU5ZJHFpv2Upl30i1.jpg', 'Dumbledore tries to prepare Harry for the final battle with Voldemort while Death Eaters wreak havoc in both Muggle and Wizard worlds.'),
(27, 62046, 'Flypaper', 'Rob Minkoff', 'Patrick Dempsey, Ashley Judd, Tim Blake Nelson, Mekhi Phifer, Matt Ryan, Jeffrey Tambor', 'Rob Minkoff', 'Mystery, Comedy, Crime', 2011, 'The Safran Company, Rising Star Productions, Foresight Unlimited, Shifting Gears Entertainment', '87', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/uJcxUKIy2GXDODT2pDl0q9XvByq.jpg', 'A man caught in the middle of two simultaneous robberies at a bank desperately tries to protect the teller with whom he\'s secretly in love.'),
(28, 11619, 'Flushed Away', 'David Bowers', 'Hugh Jackman, Kate Winslet, Ian McKellen, Jean Reno, Bill Nighy, Andy Serkis', 'William Davies, Dick Clement, Christopher Lloyd', 'Adventure, Animation, Comedy, Family', 2006, 'DreamWorks Animation, Aardman', '85', 3.2, 'GB, US', 'English', 'https://image.tmdb.org/t/p/w500/kgoZI4xh38RrEYEPVib6a12UPLn.jpg', 'London high-society mouse, Roddy is flushed down the toilet by Sid, a common sewer rat. Hang on for a madcap adventure deep in the sewer bowels of Ratropolis, where Roddy meets the resourceful Rita, the rodent-hating Toad and his faithful thugs, Spike and Whitey.'),
(29, 9574, 'Flubber', 'Les Mayfield', 'Robin Williams, Marcia Gay Harden, Christopher McDonald, Raymond J. Barry, Clancy Brown, Nancy Olson', 'Bill Walsh, John Hughes', 'Comedy, Family, Science Fiction', 1997, 'Walt Disney Pictures, Great Oaks Entertainment', '93', 2.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/bnKvk04icAyCO1KjqhsaEXBO9aJ.jpg', 'Professor Phillip Brainard, an absent minded professor, works with his assistant Weebo, trying to create a substance that\'s a new source of energy and that will save Medfield College where his sweetheart Sara is the president. He has missed his wedding twice, and on the afternoon of his third wedding, Professor Brainard creates flubber, which allows objects to fly through the air.'),
(30, 274167, 'Daddy\'s Home', 'Sean Anders', 'Will Ferrell, Mark Wahlberg, Linda Cardellini, Thomas Haden Church, Scarlett Estevez, Owen Vaccaro', 'Adam McKay, Brian Burns, Chris Henchy', 'Comedy', 2015, 'Paramount Pictures, Gary Sanchez Productions, Red Granite Pictures', '96', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/fB9lALk9zKsMYWvf0bJSkJN219Z.jpg', 'The story of a mild-mannered radio executive who strives to become the best stepdad ever to his wife\'s two children, but complications ensue when their freewheeling, freeloading real father arrives, forcing stepdad to compete for the affection of the kids.'),
(31, 49849, 'Cowboys & Aliens', 'Jon Favreau', 'Daniel Craig, Harrison Ford, Olivia Wilde, Sam Rockwell, Adam Beach, Paul Dano', 'Roberto Orci, Alex Kurtzman, Damon Lindelof', 'Action, Science Fiction, Thriller, Western', 2011, 'DreamWorks Pictures, Universal Pictures, Reliance Entertainment, Relativity Media, Imagine Entertainment, K/O Paper Products, Fairview Entertainment, Platinum Studios', '119', 2.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/9uZsGCP4rvOHVGCpMpYq5gNCuNI.jpg', 'A stranger stumbles into the desert town of Absolution with no memory of his past and a futuristic shackle around his wrist. With the help of mysterious beauty Ella and the iron-fisted Colonel Dolarhyde, he finds himself leading an unlikely posse of cowboys, outlaws, and Apache warriors against a common enemy from beyond this world in an epic showdown for survival.'),
(32, 9339, 'Click', 'Frank Coraci', 'Adam Sandler, Kate Beckinsale, Christopher Walken, David Hasselhoff, Henry Winkler, Julie Kavner', 'Frank Coraci', 'Comedy, Drama, Fantasy', 2006, 'Original Film, Revolution Studios, Columbia Pictures, Happy Madison Productions', '107', 3.2, 'US', 'English, Português, 日本語', 'https://image.tmdb.org/t/p/w500/oL0k5JA53PyoHSZqKb3cNkhwBCE.jpg', 'A married workaholic, Michael Newman doesn\'t have time for his wife and children, not if he\'s to impress his ungrateful boss and earn a well-deserved promotion. So when he meets Morty, a loopy sales clerk, he gets the answer to his prayers: a magical remote that allows him to bypass life\'s little distractions with increasingly hysterical results.'),
(33, 9029, 'What Happens in Vegas', 'Tom Vaughan', 'Cameron Diaz, Ashton Kutcher, Rob Corddry, Lake Bell, Jason Sudeikis, Treat Williams', 'Dana Fox', 'Comedy, Romance', 2008, 'Penn Station Entertainment, Regency Enterprises, 21 Laps Entertainment, Dune Entertainment III, Mosaic Media Group, 20th Century Fox, Monarchy Enterprises B.V.', '99', 3.1, 'US', 'English, ', 'https://image.tmdb.org/t/p/w500/n7bQ7Lj6UhArgnx49wmkaTxM4iU.jpg', 'During a wild vacation in Las Vegas, career woman Joy McNally and playboy Jack Fuller come to the sober realization that they have married each other after a night of drunken abandon. They are then compelled, for legal reasons, to live life as a couple for a limited period of time. At stake is a large amount of money.'),
(34, 14160, 'Up', 'Pete Docter', 'Ed Asner, Christopher Plummer, Jordan Nagai, Bob Peterson, Delroy Lindo, Jerome Ranft', 'Bob Peterson, Pete Docter', 'Animation, Comedy, Family, Adventure', 2009, 'Pixar', '96', 4.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg', 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.'),
(35, 41513, 'The Smurfs', 'Raja Gosnell', 'Hank Azaria, Neil Patrick Harris, Jayma Mays, Jonathan Winters, Katy Perry, Anton Yelchin', 'J. David Stem, Jay Scherick, David Ronn', 'Animation, Family, Adventure, Comedy, Fantasy', 2011, 'Columbia Pictures, Sony Pictures Animation, The Kerner Entertainment Company', '103', 2.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/vRhnslP2gW0QDym7BsMeSuioUfK.jpg', 'When the evil wizard Gargamel chases the tiny blue Smurfs out of their village, they tumble from their magical world and into ours -- in fact, smack dab in the middle of Central Park. Just three apples high and stuck in the Big Apple, the Smurfs must find a way to get back to their village before Gargamel tracks them down.'),
(36, 10882, 'Sleeping Beauty', 'Clyde Geronimi', 'Mary Costa, Bill Shirley, Eleanor Audley, Verna Felton, Barbara Luddy, Barbara Jo Allen', 'Erdman Penner', 'Fantasy, Animation, Romance, Family', 1959, 'Walt Disney Productions', '75', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/n3pxoMDDxp10c1smgbDzW4bwlzq.jpg', 'Cursed to die by the evil fairy Maleficent when she was a baby, Princess Aurora is sent into hiding under protection from three good fairies. As she grows up far away, Maleficent becomes increasingly determined to seal the princess\'s fate.'),
(37, 527261, 'The Silence', 'John R. Leonetti', 'Stanley Tucci, Kiernan Shipka, Miranda Otto, Kate Trotter, John Corbett, Kyle Breitkopf', 'Carey van Dyke, Shane van Dyke', 'Horror, Drama, Thriller, Fantasy', 2019, 'Constantin Film, EMJAG Productions, Mister Smith Entertainment', '91', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/lTVOquzxw2DPF3MKuYd1ynz9F6H.jpg', 'With the world under attack by deadly creatures who hunt by sound, a teen and her family seek refuge outside the city and encounter a mysterious cult.'),
(38, 46195, 'Rio', 'Carlos Saldanha', 'Jesse Eisenberg, Anne Hathaway, Leslie Mann, Jane Lynch, will.i.am, George López', 'Don Rhymer, Joshua Sternin, Sam Harper', 'Animation, Adventure, Comedy, Family', 2011, 'Blue Sky Studios, 20th Century Fox Animation', '96', 3.4, 'US', 'English, Português', 'https://image.tmdb.org/t/p/w500/4nJxhUknKV8Gqdhov8pU1YWDYfb.jpg', 'Captured by smugglers when he was just a hatchling, a macaw named Blu never learned to fly and lives a happily domesticated life in Minnesota with his human friend, Linda. Blu is thought to be the last of his kind, but when word comes that Jewel, a lone female, lives in Rio de Janeiro, Blu and Linda go to meet her. Animal smugglers kidnap Blu and Jewel, but the pair soon escape and begin a perilous adventure back to freedom -- and Linda.'),
(39, 13836, 'Race to Witch Mountain', 'Andy Fickman', 'Dwayne Johnson, AnnaSophia Robb, Alexander Ludwig, Carla Gugino, Ciarán Hinds, Tom Everett Scott', 'Matt Lopez, Mark Bomback', 'Adventure, Family, Fantasy, Science Fiction, Thriller, Action', 2009, 'Walt Disney Pictures, Gunn Films', '98', 2.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/5RBZsOKMMxnp8L6UmOiylKOw4yo.jpg', 'A taxi driver gets more than he bargained for when he picks up two teen runaways. Not only does the pair possess supernatural powers, but they\'re also trying desperately to escape people who have made them their targets.'),
(40, 1199869, 'Eye for an Eye', 'Colin Tilley', 'Whitney Peak, Golda Rosheuvel, Finn Bennett, Laken Giles, S. Epatha Merkerson, Carson Minniear', 'Colin Tilley', 'Horror', 2025, 'Ley Line Entertainment, glassEyeballs, WME Independent, HanWay Films', '101', 2.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/lpepbfVziHJLhVoxTEKs8ok00iu.jpg', 'Anna, grieving the sudden death of her parents, relocates from New York to a small Florida town to live with the grandmother she has never met. Isolated, vulnerable, and in need of friends, she finds brief solace in the company of two local teens. But when she becomes complicit to their unforgivable act of violence, she finds herself ensnared by Mr. Sandman – the twisted soul of a tormented child who haunts bullies’ dreams before feasting on their eyeballs when they finally wake - Anna must right her wrong before becoming a victim of this gruesome curse.'),
(41, 9479, 'The Nightmare Before Christmas', 'Henry Selick', 'Danny Elfman, Chris Sarandon, Catherine O\'Hara, William Hickey, Glenn Shadix, Paul Reubens', 'Caroline Thompson', 'Fantasy, Animation, Family', 1993, 'Touchstone Pictures, Skellington Productions', '76', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack\'s rag-doll girlfriend, Sally, tries to foil his misguided plans.'),
(42, 211672, 'Minions', 'Kyle Balda', 'Sandra Bullock, Jon Hamm, Michael Keaton, Allison Janney, Steve Coogan, Jennifer Saunders', 'Kyle Balda, Pierre Coffin', 'Family, Animation, Adventure, Comedy', 2015, 'Illumination, Universal Pictures', '91', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/dr02BdCNAUPVU07aOodwPYv6HCf.jpg', 'Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.'),
(43, 608, 'Men in Black II', 'Barry Sonnenfeld', 'Tommy Lee Jones, Will Smith, Rip Torn, Lara Flynn Boyle, Johnny Knoxville, Rosario Dawson', 'Robert Gordon, Barry Fanaro', 'Action, Comedy, Science Fiction', 2002, 'Columbia Pictures, Amblin Entertainment, Parkes+MacDonald Production', '88', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/enA22EPyzc2WQ1VVyY7zxresQQr.jpg', 'Kay and Jay reunite to provide our best, last and only line of defense against a sinister seductress who levels the toughest challenge yet to the MIB\'s untarnished mission statement – protecting Earth from the scum of the universe. It\'s been four years since the alien-seeking agents averted an intergalactic disaster of epic proportions. Now it\'s a race against the clock as Jay must convince Kay – who not only has absolutely no memory of his time spent with the MIB, but is also the only living person left with the expertise to save the galaxy – to reunite with the MIB before the earth submits to ultimate destruction.'),
(44, 65931, 'Manuelita', 'Manuel García Ferré', 'Rosario Sánchez Almada, Cecilia Gispert, Enrique Conlazo, Pelusa Suero, Ariel Abadi, Néstor D\'Alessandro', 'Manuel García Ferré', 'Animation, Family, Comedy, Adventure', 1999, 'Columbia Pictures of Argentina, García Ferré Entertainment, Producciones García Ferré, INCAA, Telefe', '86', 3.3, 'AR', 'Español', 'https://image.tmdb.org/t/p/w500/w67V5qcB3yUVrq3W49NMFNL8H12.jpg', 'Animated Argentine film about a young girl turtle who gets lost on a balloon trip.'),
(45, 10138, 'Iron Man 2', 'Jon Favreau', 'Robert Downey Jr., Gwyneth Paltrow, Don Cheadle, Scarlett Johansson, Sam Rockwell, Mickey Rourke', 'Justin Theroux', 'Adventure, Action, Science Fiction', 2010, 'Marvel Studios, Fairview Entertainment, Marvel Entertainment', '124', 3.4, 'US', 'English, Pусский, Français', 'https://image.tmdb.org/t/p/w500/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James \'Rhodey\' Rhodes at his side, must forge new alliances – and confront powerful enemies.'),
(46, 11360, 'Dumbo', 'Ben Sharpsteen', 'Edward Brophy, Margaret Wright, Verna Felton, Sarah Selby, Noreen Gammill, Dorothy Scott', 'Joe Grant, Dick Huemer', 'Animation, Family', 1941, 'Walt Disney Productions', '64', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/hKDdllslMtsU9JixAv5HR9biXlp.jpg', 'Dumbo is a baby elephant born with over-sized ears and a supreme lack of confidence. But thanks to his even more diminutive buddy Timothy the Mouse,  the pint-sized pachyderm learns to surmount all obstacles.'),
(47, 9449, 'The Borrowers', 'Peter Hewitt', 'John Goodman, Mark Williams, Jim Broadbent, Celia Imrie, Flora Newbigin, Tom Felton', 'Gavin Scott, John Kamps', 'Adventure, Fantasy, Action, Comedy, Family', 1997, 'Working Title Films, PolyGram Filmed Entertainment', '87', 3.0, 'US, GB', 'English', 'https://image.tmdb.org/t/p/w500/kgaocWyuxihDe5aNqok6fORIHnY.jpg', 'The four-inch-tall Clock family secretly share a house with the normal-sized Lender family, \"borrowing\" such items as thread, safety pins, batteries and scraps of food. However, their peaceful co-existence is disturbed when evil lawyer Ocious P. Potter steals the will granting title to the house, which he plans to demolish in order to build apartments. The Lenders are forced to move, and the Clocks face the risk of being exposed to the normal-sized world.'),
(48, 177572, 'Big Hero 6', 'Chris Williams', 'Scott Adsit, Ryan Potter, Daniel Henney, T.J. Miller, Jamie Chung, Damon Wayans Jr.', 'Robert L. Baird, Jordan Roberts, Daniel Gerson', 'Adventure, Family, Animation, Action, Comedy', 2014, 'Walt Disney Animation Studios', '102', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/2mxS4wUimwlLmI1xp6QW6NSU361.jpg', 'A special bond develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.'),
(49, 44115, '127 Hours', 'Danny Boyle', 'James Franco, Kate Mara, Amber Tamblyn, Clémence Poésy, Lizzy Caplan, Kate Burton', 'Danny Boyle, Simon Beaufoy', 'Adventure, Drama, Thriller', 2010, 'Fox Searchlight Pictures, Pathé, Everest Entertainment, Cloud Eight Films, Decibel Films, DSP, Film4 Productions, Dune Entertainment, Big Screen Productions, Down Productions', '94', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/h0RMdn0rfl9l5hWXz3tUh6QVkhi.jpg', 'The true story of mountain climber Aron Ralston\'s remarkable adventure to save himself after a fallen boulder crashes on his arm and traps him in an isolated canyon in Utah.'),
(50, 72105, 'Ted', 'Seth MacFarlane', 'Mark Wahlberg, Mila Kunis, Seth MacFarlane, Joel McHale, Giovanni Ribisi, Patrick Warburton', 'Seth MacFarlane, Alec Sulkin, Wellesley Wild', 'Comedy, Fantasy', 2012, 'Universal Pictures, MRC, Fuzzy Door Productions, Bluegrass Films, Smart Entertainment', '107', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/1QVZXQQHCEIj8lyUhdBYd2qOYtq.jpg', 'John Bennett, a man whose childhood wish of bringing his teddy bear to life came true, now must decide between keeping the relationship with the bear or his girlfriend, Lori.'),
(51, 529962, 'The Perfection', 'Richard Shepard', 'Allison Williams, Logan Browning, Steven Weber, Alaina Huffman, Molly Grace, Milah Thompson', 'Richard Shepard', 'Horror, Thriller, Drama', 2018, 'Miramax, Capstone Pictures', '90', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/tPDe68PDsgIGMs6wdJLtcwVVxA7.jpg', 'When troubled musical prodigy Charlotte seeks out Elizabeth, the new star pupil of her former school, the encounter sends both musicians down a sinister path with shocking consequences.'),
(52, 163, 'Ocean\'s Twelve', 'Steven Soderbergh', 'George Clooney, Julia Roberts, Brad Pitt, Matt Damon, Catherine Zeta-Jones, Andy Garcia', 'Steven Soderbergh', 'Thriller, Crime', 2004, 'Warner Bros. Pictures, Jerry Weintraub Productions, Section Eight, Village Roadshow Pictures', '125', 3.3, 'US', 'Français, Italiano, Nederlands, 普通话, English', 'https://image.tmdb.org/t/p/w500/pE5anFf7nf6ah7V3VRezQ1KSovi.jpg', 'Despite pulling off one of the biggest heists in Las Vegas history and splitting the $160 million take, each of the infamous Ocean\'s crew have tried to go straight, lay low and live a legit life... but that\'s proven to be a challenge. Casino owner Terry Benedict demands that Danny Ocean return the money, plus millions more in interest. Unable to come up the cash, the crew is forced to come together to pull off another series of heists, this time in Rome, Paris, and Amsterdam – but a Europol agent is hot on their heels.'),
(53, 614911, 'The Midnight Sky', 'George Clooney', 'George Clooney, Felicity Jones, David Oyelowo, Caoilinn Springall, Kyle Chandler, Demián Bichir', 'Mark L. Smith', 'Science Fiction, Drama', 2020, 'Smokehouse Pictures, Syndicate Films, Anonymous Content, Truenorth Productions', '118', 2.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/l8lXesOLXKS0VYjzWNZN6gDxv2F.jpg', 'A lone scientist in the Arctic races to contact a crew of astronauts returning home to a mysterious global catastrophe.'),
(54, 10340, 'Lady and the Tramp', 'Hamilton Luske', 'Barbara Luddy, Larry Roberts, Peggy Lee, Bill Thompson, Bill Baucom, Stan Freberg', 'Clyde Geronimi, Wilfred Jackson', 'Animation, Family, Romance, Adventure, Comedy', 1955, 'Walt Disney Productions', '76', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/340NcWz9SQXWQyf4oicMxjbrLOb.jpg', 'Lady, a golden cocker spaniel, meets up with a mongrel dog who calls himself the Tramp. He is obviously from the wrong side of town, but happenings at Lady\'s home make her decide to travel with him for a while.'),
(55, 293167, 'Kong: Skull Island', 'Jordan Vogt-Roberts', 'Tom Hiddleston, Samuel L. Jackson, John Goodman, Brie Larson, Jing Tian, Toby Kebbell', 'Max Borenstein, Dan Gilroy, Derek Connolly', 'Action, Adventure, Fantasy', 2017, 'Legendary Pictures, Tencent Pictures', '118', 3.3, 'US', 'English, Tiếng Việt', 'https://image.tmdb.org/t/p/w500/r2517Vz9EhDhj88qwbDVj8DCRZN.jpg', 'Explore the mysterious and dangerous home of the king of the apes as a team of explorers ventures deep inside the treacherous, primordial island.'),
(56, 88751, 'Journey to the Center of the Earth', 'Eric Brevig', 'Brendan Fraser, Josh Hutcherson, Anita Briem, Seth Meyers, Jean Michel Paré, Jane Wheeler', 'Michael D. Weiss, Jennifer Flackett, Mark Levin', 'Action, Science Fiction, Adventure, Comedy, Family', 2008, 'New Line Cinema, Walden Media, Journey Films', '93', 3.0, 'US', 'English, Íslenska, Italiano', 'https://image.tmdb.org/t/p/w500/kL55wY0s2H9JdwfjoWIp9plvYnl.jpg', 'On a quest to find out what happened to his missing brother, a scientist, his nephew and their mountain guide discover a fantastic and dangerous lost world in the center of the earth.'),
(57, 10545, 'The Hunchback of Notre Dame', 'Gary Trousdale', 'Tom Hulce, Demi Moore, Kevin Kline, Tony Jay, Charles Kimbrough, Mary Wickes', 'Irene Mecchi, Tab Murphy, Jonathan Roberts', 'Drama, Animation, Family', 1996, 'Walt Disney Pictures, Walt Disney Feature Animation', '91', 3.6, 'US', 'Latin, English', 'https://image.tmdb.org/t/p/w500/dmMBtXuFzZzLYgeQXkOkg98w2Ak.jpg', 'Isolated bell-ringer Quasimodo wishes to leave Notre Dame tower against the wishes of Judge Claude Frollo, his stern guardian and Paris\' strait-laced Minister of Justice. His first venture to the outside world finds him Esmeralda, a kind-hearted and fearless Romani woman who openly stands up to Frollo\'s tyranny.'),
(58, 105864, 'The Good Dinosaur', 'Peter Sohn', 'Raymond Ochoa, Frances McDormand, Jeffrey Wright, Steve Zahn, Sam Elliott, Anna Paquin', 'Meg LeFauve', 'Adventure, Animation, Family', 2015, 'Pixar', '93', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8RSkxOO80btfKjyiC5ZiTaCHIT8.jpg', 'An epic journey into the world of dinosaurs where an Apatosaurus named Arlo makes an unlikely human friend.'),
(59, 27578, 'The Expendables', 'Sylvester Stallone', 'Sylvester Stallone, Jason Statham, Jet Li, Dolph Lundgren, Eric Roberts, Randy Couture', 'David Callaham, Sylvester Stallone', 'Thriller, Adventure, Action', 2010, 'Nimar Studios, Rogue Marble, Millennium Media, Lionsgate, Nu Image Entertainment', '103', 3.1, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/j09ZkH6R4JWVylBcDai1laCmGw7.jpg', 'Barney Ross leads a band of highly skilled mercenaries including knife enthusiast Lee Christmas, a martial arts expert Yin Yang, heavy weapons specialist Hale Caesar, demolitionist Toll Road, and a loose-cannon sniper Gunner Jensen. When the group is commissioned by the mysterious Mr. Church to assassinate the dictator of a small South American island, Barney and Lee visit the remote locale to scout out their opposition and discover the true nature of the conflict engulfing the city.'),
(60, 18823, 'Clash of the Titans', 'Louis Leterrier', 'Sam Worthington, Gemma Arterton, Mads Mikkelsen, Alexa Davalos, Jason Flemyng, Ralph Fiennes', 'Travis Beacham, Matt Manfredi, Phil Hay', 'Adventure, Fantasy, Action', 2010, 'The Zanuck Company, Legendary Pictures, Thunder Road, Moving Picture Company, Warner Bros. Pictures', '106', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6iHYLipwEyZUPNO8MM3l1yHDaFE.jpg', 'Born of a god but raised as a man, Perseus is helpless to save his family from Hades, vengeful god of the underworld. With nothing to lose, Perseus volunteers to lead a dangerous mission to defeat Hades before he can seize power from Zeus and unleash hell on earth. Battling unholy demons and fearsome beasts, Perseus and his warriors will only survive if Perseus accepts his power as a god, defies fate and creates his own destiny.'),
(61, 150689, 'Cinderella', 'Kenneth Branagh', 'Lily James, Cate Blanchett, Richard Madden, Stellan Skarsgård, Holliday Grainger, Sophie McShera', 'Chris Weitz', 'Romance, Fantasy, Family, Drama', 2015, 'Walt Disney Pictures, Genre Films, Beagle Pug Films, Allison Shearmur Productions', '105', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/j91LJmcWo16CArFOoapsz84bwxb.jpg', 'When her father unexpectedly passes away, young Ella finds herself at the mercy of her cruel stepmother and her daughters. Never one to give up hope, Ella\'s fortunes begin to change after meeting a dashing stranger in the woods.'),
(62, 118, 'Charlie and the Chocolate Factory', 'Tim Burton', 'Johnny Depp, Freddie Highmore, David Kelly, Helena Bonham Carter, Noah Taylor, Missi Pyle', 'John August', 'Adventure, Comedy, Family, Fantasy', 2005, 'Warner Bros. Pictures, Village Roadshow Pictures, The Zanuck Company, Plan B Entertainment, Theobald Film Productions', '115', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/iKP6wg3c6COUe8gYutoGG7qcPnO.jpg', 'A young boy wins a tour through the most magnificent chocolate factory in the world, led by the world\'s most unusual candy maker.'),
(63, 297762, 'Wonder Woman', 'Patty Jenkins', 'Gal Gadot, Chris Pine, Connie Nielsen, Robin Wright, Danny Huston, David Thewlis', 'Allan Heinberg', 'Action, Adventure, Fantasy', 2017, 'Atlas Entertainment, Cruel & Unusual Films, DC Films, Warner Bros. Pictures, RatPac-Dune Entertainment', '141', 3.6, 'US', 'Deutsch, English', 'https://image.tmdb.org/t/p/w500/v4ncgZjG2Zu8ZW5al1vIZTsSjqX.jpg', 'An Amazon princess comes to the world of Man in the grips of the First World War to confront the forces of evil and bring an end to human conflict.'),
(64, 423949, 'Unicorn Store', 'Brie Larson', 'Brie Larson, Samuel L. Jackson, Joan Cusack, Bradley Whitford, Mamoudou Athie, Hamish Linklater', 'Brie Larson', 'Fantasy, Drama, Comedy', 2017, 'The District, Rhea Films, 51 Entertainment, Rip Cord Productions', '91', 2.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/rGe3eWy3F3qggDZMc86bASN4I7C.jpg', 'A woman named Kit moves back to her parent\'s house, where she receives a mysterious invitation that would fulfill her childhood dreams.'),
(65, 10195, 'Thor', 'Kenneth Branagh', 'Chris Hemsworth, Natalie Portman, Tom Hiddleston, Anthony Hopkins, Stellan Skarsgård, Kat Dennings', 'Don Payne, Ashley Miller, Zack Stentz', 'Adventure, Fantasy, Action', 2011, 'Marvel Studios, Marvel Entertainment', '115', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg', 'Against his father Odin\'s will, The Mighty Thor - a powerful but arrogant warrior god - recklessly reignites an ancient war. Thor is cast down to Earth and forced to live among humans as punishment. Once here, Thor learns what it takes to be a true hero when the most dangerous villain of his world sends the darkest forces of Asgard to invade Earth.'),
(66, 296, 'Terminator 3: Rise of the Machines', 'Jonathan Mostow', 'Arnold Schwarzenegger, Nick Stahl, Claire Danes, Kristanna Loken, Earl Boen, David Andrews', 'John Brancato, Michael Ferris', 'Action, Thriller, Science Fiction', 2003, 'Intermedia Films, IMF Internationale Medien und Film 3 & Produktions, C2 Pictures, Mostow/Lieberman Productions', '109', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/vvevzdYIrk2636maNW4qeWmlPFG.jpg', 'It\'s been 10 years since John Connor saved Earth from Judgment Day, and he\'s now living under the radar, steering clear of using anything Skynet can trace. That is, until he encounters T-X, a robotic assassin ordered to finish what T-1000 started. Good thing Connor\'s former nemesis, the Terminator, is back to aid the now-adult Connor … just like he promised.'),
(67, 9078, 'The Sword in the Stone', 'Wolfgang Reitherman', 'Sebastian Cabot, Karl Swenson, Junius Matthews, Martha Wentworth, Norman Alden, Rickie Sorensen', 'Bill Peet', 'Animation, Family, Fantasy', 1963, 'Walt Disney Productions', '79', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/7lyeeuhGAJSNXYEW34S8mJ1bwI8.jpg', 'Wart is a young boy who aspires to be a knight\'s squire. On a hunting trip he falls in on Merlin, a powerful but amnesiac wizard who has plans for him beyond mere squiredom. He starts by trying to give him an education, believing that once one has an education, one can go anywhere. Needless to say, it doesn\'t quite work out that way.'),
(68, 9334, 'The Scorpion King', 'Chuck Russell', 'Dwayne Johnson, Steven Brand, Michael Clarke Duncan, Kelly Hu, Bernard Hill, Grant Heslov', 'Stephen Sommers, David Hayter, William Osborne', 'Action, Adventure, Fantasy', 2002, 'Universal Pictures, Alphaville Films, Kalima Productions, WWE Studios, Alliance Films', '92', 2.8, 'US', 'English, Deutsch, Italiano, ภาษาไทย', 'https://image.tmdb.org/t/p/w500/aITIsX20tACn6jgtyDcCYpRT216.jpg', 'In ancient Egypt, peasant Mathayus is hired to exact revenge on the powerful Memnon and the sorceress Cassandra, who are ready to overtake Balthazar\'s village. Amid betrayals, thieves, abductions and more, Mathayus strives to bring justice to his complicated world.'),
(69, 13486, 'The Scorpion King 2: Rise of a Warrior', 'Russell Mulcahy', 'Michael Copon, Randy Couture, Karen David, Simon Quarterman, Tom Wu, Andreas Wisniewski', 'Russell Mulcahy', 'Action, Adventure, Fantasy', 2008, 'Universal Pictures, ApolloMovie Beteiligungs, The Sommers Company, Film Afrika', '109', 2.4, 'US', 'English, Italiano', 'https://image.tmdb.org/t/p/w500/osZ6HJJBPwptZLTXFYbGQ0Jc7WB.jpg', 'The heroic tale of young Mathayus and his relentless quest for justice against an evil and powerful villain, King Sargon. Mathayus faces heart-stopping tribulations during his adventurous, odds-defying trajectory toward his ultimate destiny: becoming the formidable warrior king of an ancient desert empire.'),
(70, 75656, 'Now You See Me', 'Louis Leterrier', 'Jesse Eisenberg, Woody Harrelson, Isla Fisher, Dave Franco, Mark Ruffalo, Mélanie Laurent', 'Edward Ricourt, Boaz Yakin, Ed Solomon', 'Thriller, Crime', 2013, 'Summit Entertainment, K/O Paper Products, SOIXAN7E QUIN5E, See Me Louisiana', '116', 3.7, 'US', 'Français, English', 'https://image.tmdb.org/t/p/w500/tWsNYbrqy1p1w6K9zRk0mSchztT.jpg', 'An FBI agent and an Interpol detective track a team of illusionists who pull off bank heists during their performances and reward their audiences with the money.'),
(71, 10539, 'James and the Giant Peach', 'Henry Selick', 'Paul Terry, Miriam Margolyes, Joanna Lumley, Pete Postlethwaite, Simon Callow, Richard Dreyfuss', 'Karey Kirkpatrick, Jonathan Roberts, Steve Bloom', 'Family, Animation, Adventure, Fantasy', 1996, 'Allied Filmmakers, Walt Disney Pictures', '79', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/vNEGobe23vW43mSPYVaVaBLP6qV.jpg', 'When the young orphan boy James spills a magic bag of crocodile tongues, he finds himself in possession of a giant peach that flies him away to strange lands.'),
(72, 49530, 'In Time', 'Andrew Niccol', 'Amanda Seyfried, Justin Timberlake, Cillian Murphy, Vincent Kartheiser, Olivia Wilde, Matt Bomer', 'Andrew Niccol', 'Action, Thriller, Science Fiction', 2011, 'New Regency Pictures, Strike Entertainment', '109', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg', 'In the not-too-distant future, the aging gene has been switched off. To avoid overpopulation, time has become the currency and the way people pay for luxuries and necessities. The rich can live forever, while the rest struggle to negotiate for their immortality. A poor young man who suddenly comes into a fortune of time finds himself on the run from a corrupt police force known as the \"time keepers\".'),
(73, 8355, 'Ice Age: Dawn of the Dinosaurs', 'Carlos Saldanha', 'Ray Romano, John Leguizamo, Denis Leary, Simon Pegg, Seann William Scott, Josh Peck', 'Michael Berg, Peter Ackerman, Yoni Brenner', 'Animation, Comedy, Family, Adventure', 2009, 'Blue Sky Studios, 20th Century Fox Animation, 20th Century Fox', '94', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/cXOLaxcNjNAYmEx1trZxOTKhK3Q.jpg', 'Times are changing for Manny the moody mammoth, Sid the motor mouthed sloth and Diego the crafty saber-toothed tiger. Life heats up for our heroes when they meet some new and none-too-friendly neighbors – the mighty dinosaurs.'),
(74, 49051, 'The Hobbit: An Unexpected Journey', 'Peter Jackson', 'Martin Freeman, Ian McKellen, Richard Armitage, James Nesbitt, Ken Stott, Sylvester McCoy', 'Fran Walsh, Philippa Boyens, Peter Jackson', 'Adventure, Fantasy, Action', 2012, 'New Line Cinema, Metro-Goldwyn-Mayer, WingNut Films', '169', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg', 'Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.');
INSERT INTO `peliculas` (`idPelicula`, `idApi`, `nombrePelicula`, `directorPelicula`, `actorPelicula`, `guionistaPelicula`, `generoPelicula`, `anoPelicula`, `companiaPelicula`, `duracionPelicula`, `ratingAvgPelicula`, `paisPelicula`, `idiomaPelicula`, `posterPelicula`, `sinopsisPelicula`) VALUES
(75, 87502, 'Flight', 'Robert Zemeckis', 'Denzel Washington, Don Cheadle, Kelly Reilly, John Goodman, Bruce Greenwood, Brian Geraghty', 'Robert Zemeckis', 'Drama', 2012, 'Paramount Pictures, ImageMovers, Parkes+MacDonald Image Nation', '138', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/tFsHDNclXoCKy2xMxskzXXMaFJS.jpg', 'Commercial airline pilot Whip Whitaker has a problem with drugs and alcohol, though so far he\'s managed to complete his flights safely. His luck runs out when a disastrous mechanical malfunction sends his plane hurtling toward the ground. Whip pulls off a miraculous crash-landing that results in only six lives lost. Shaken to the core, Whip vows to get sober -- but when the crash investigation exposes his addiction, he finds himself in an even worse situation.'),
(76, 127380, 'Finding Dory', 'Andrew Stanton', 'Ellen DeGeneres, Albert Brooks, Ed O\'Neill, Hayden Rolence, Diane Keaton, Eugene Levy', 'Andrew Stanton, Victoria Strouse', 'Adventure, Animation, Family', 2016, 'Pixar', '97', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/3UVe8NL1E2ZdUZ9EDlKGJY5UzE.jpg', 'Dory is reunited with her friends Nemo and Marlin in the search for answers about her past. What can she remember? Who are her parents? And where did she learn to speak Whale?'),
(77, 68724, 'Elysium', 'Neill Blomkamp', 'Matt Damon, Jodie Foster, Sharlto Copley, Diego Luna, Wagner Moura, Alice Braga', 'Neill Blomkamp', 'Science Fiction, Action, Drama, Thriller', 2013, 'TriStar Pictures, MRC, QED International, Alphacore, Genre Films', '109', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/aRjuJuPXHtVs6YegfeeQWXGRs1E.jpg', 'In the year 2159, two classes of people exist: the very wealthy who live on a pristine man-made space station called Elysium, and the rest, who live on an overpopulated, ruined Earth. Secretary Rhodes, a hard line government official, will stop at nothing to enforce anti-immigration laws and preserve the luxurious lifestyle of the citizens of Elysium. That doesn’t stop the people of Earth from trying to get in, by any means they can. When unlucky Max is backed into a corner, he agrees to take on a daunting mission that, if successful, will not only save his life, but could bring equality to these polarized worlds.'),
(78, 310, 'Bruce Almighty', 'Tom Shadyac', 'Jim Carrey, Morgan Freeman, Jennifer Aniston, Philip Baker Hall, Catherine Bell, Lisa Ann Walter', 'Steve Oedekerk, Steve Koren, Mark O\'Keefe', 'Fantasy, Comedy', 2003, 'Pit Bull Productions, Spyglass Entertainment, Universal Pictures, Shady Acres Entertainment', '101', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/wqkWrOFtYnZSvIMu8Lsmz7WIvKC.jpg', 'Bruce Nolan toils as a \"human interest\" television reporter in Buffalo, NY, but despite his high ratings and the love of his beautiful girlfriend, Bruce remains unfulfilled. At the end of the worst day in his life, he angrily ridicules God — and the Almighty responds, endowing Bruce with all of His divine powers.'),
(79, 10112, 'The Aristocats', 'Wolfgang Reitherman', 'Phil Harris, Eva Gabor, Sterling Holloway, Scatman Crothers, Paul Winchell, Lord Tim Hudson', 'Larry Clemmons, Vance Gerry, Ken Anderson', 'Animation, Comedy, Family, Adventure', 1970, 'Walt Disney Productions', '78', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/aOWs5XMJEABN6SKCTJBCoeD1kCA.jpg', 'When Madame Adelaide Bonfamille leaves her fortune to Duchess and her children—Bonfamille’s beloved family of cats—the butler plots to steal the money and kidnaps the legatees, leaving them out on a country road. All seems lost until the wily Thomas O’Malley Cat and his jazz-playing alley cats come to the aristocats’ rescue.'),
(80, 8273, 'American Wedding', 'Jesse Dylan', 'Jason Biggs, Molly Cheek, Alyson Hannigan, January Jones, Thomas Ian Nicholas, Seann William Scott', 'Adam Herz', 'Comedy, Romance', 2003, 'Loumolo & Co., Universal Pictures, LivePlanet, Zide-Perry Productions', '103', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/pCO3lJv2PzPkJty29APxCVSjyoE.jpg', 'With high school a distant memory, Jim and Michelle are getting married — and in a hurry, since Jim\'s grandmother is sick and wants to see him walk down the aisle — prompting Stifler to throw the ultimate bachelor party. And Jim\'s dad is reliable as ever, doling out advice no one wants to hear.'),
(81, 71552, 'American Reunion', 'Jon Hurwitz', 'Jason Biggs, Alyson Hannigan, Seann William Scott, Chris Klein, Thomas Ian Nicholas, Tara Reid', 'Hayden Schlossberg, Jon Hurwitz', 'Comedy', 2012, 'Universal Pictures, Practical Pictures, Relativity Media, Zide Pictures', '114', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/de5QBIdVR4dnkBZ4a0zjkS4lTg.jpg', 'The characters we met a little more than a decade ago return to East Great Falls for their high school reunion. In one long-overdue weekend, they will discover what has changed, who hasn’t, and that time and distance can’t break the bonds of friendship.'),
(82, 15969, 'The Return of Jafar', 'Tad Stones', 'Scott Weinger, Linda Larkin, Jonathan Freeman, Gilbert Gottfried, Dan Castellaneta, Frank Welker', 'Tad Stones, Alan Zaslove', 'Family, Adventure, Animation, Romance', 1994, 'Disney Television Animation', '69', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/7SC793qtORB6YL4mu0F5o3hfjDQ.jpg', 'The evil Jafar escapes from the magic lamp as an all-powerful genie, ready to plot his revenge against Aladdin. From battling elusive villains atop winged horses, to dodging flames inside an exploding lava pit, it\'s up to Aladdin - with Princess Jasmine and the outrageously funny Genie by his side - to save the kingdom once and for all.'),
(83, 58595, 'Snow White and the Huntsman', 'Rupert Sanders', 'Kristen Stewart, Chris Hemsworth, Charlize Theron, Sam Claflin, Ian McShane, Ray Winstone', 'Evan Daugherty, John Lee Hancock, Hossein Amini', 'Adventure, Fantasy, Drama', 2012, 'Universal Pictures, Roth Films', '127', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8HUa5kRubYbnAD5UVpnhTGGgMTW.jpg', 'After the Evil Queen marries the King, she performs a violent coup in which the King is murdered and his daughter, Snow White, is taken captive. Almost a decade later, a grown Snow White is still in the clutches of the Queen. In order to obtain immortality, The Evil Queen needs the heart of Snow White. After Snow escapes the castle, the Queen sends the Huntsman to find her in the Dark Forest.'),
(84, 565, 'The Ring', 'Gore Verbinski', 'Naomi Watts, Martin Henderson, David Dorfman, Brian Cox, Jane Alexander, Lindsay Frost', 'Ehren Kruger, Hiroshi Takahashi', 'Horror, Mystery', 2002, 'DreamWorks Pictures, BenderSpink, Parkes+MacDonald Production', '115', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/AeRpUynJKDpJveklBJipOYrVxCS.jpg', 'Journalist Rachel Keller investigates a strange videotape that may be behind the untimely deaths of four teenagers. There is an urban legend about this tape: the viewer will die seven days after watching it. Rachel tracks down the video... and watches it. Now she has just seven days to unravel the mystery of the Ring in order to save herself and her son.'),
(85, 392044, 'Murder on the Orient Express', 'Kenneth Branagh', 'Kenneth Branagh, Tom Bateman, Michelle Pfeiffer, Johnny Depp, Josh Gad, Willem Dafoe', 'Michael Green', 'Mystery, Drama, Crime', 2017, 'The Mark Gordon Company, Genre Films, 20th Century Fox, Scott Free Productions', '114', 3.4, 'US', 'العربية, English, Français, Deutsch, Türkçe', 'https://image.tmdb.org/t/p/w500/7GtdJU6iAg6fjQu3E3zta3bIAQh.jpg', 'Genius Belgian detective Hercule Poirot investigates the murder of an American tycoon aboard the Orient Express train.'),
(86, 9732, 'The Lion King II: Simba\'s Pride', 'Darrell Rooney', 'Matthew Broderick, Neve Campbell, Jason Marsden, Nathan Lane, Ernie Sabella, Andy Dick', 'Cindy Marcus, Flip Kobler', 'Adventure, Animation, Drama, Family, Romance', 1998, 'Disney Television Animation', '81', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/sWR1x6UCMCGN9xEf8RGhPS934X0.jpg', 'The circle of life continues for Simba, now fully grown and in his rightful place as the king of Pride Rock. Simba and Nala have given birth to a daughter, Kiara who\'s as rebellious as her father was. But Kiara drives her parents to distraction when she catches the eye of Kovu, the son of the evil lioness, Zira. Will Kovu steal Kiara\'s heart?'),
(87, 15997, 'The Land Before Time II: The Great Valley Adventure', 'Roy Allen Smith', 'Scott McAfee, Candace Hutson, Heather Hogan, Jeff Bennett, Rob Paulsen, Linda Gary', 'John Loy, Dev Ross, John Ludin', 'Animation, Adventure, Family', 1994, 'Universal Cartoon Studios, AKOM Production Company', '73', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/1lIkU6gbqMx4oRDGegawLdQdLJD.jpg', 'Littlefoot and his friends find life in the Great Valley a bit too restrictive under the watchful eyes of their overprotective parents. Wishing to not be treated like babies anymore, the group chase after a pair of dangerous dinosaurs stealing an egg from Ducky\'s nest. When the egg they bring back hatches in the valley, the friends are surprised to find a baby Sharptooth. Rather than abandoning him, they name him Chomper and attempt to raise him as one of their own.'),
(88, 11359, 'The Indian in the Cupboard', 'Frank Oz', 'Hal Scardino, Litefoot, Lindsay Crouse, Richard Jenkins, Rishi Bhat, Steve Coogan', 'Melissa Mathison', 'Adventure, Family, Fantasy', 1995, 'Paramount Pictures, The Kennedy/Marshall Company, Columbia Pictures', '96', 3.2, 'US', 'Italiano, English', 'https://image.tmdb.org/t/p/w500/ozQAmW85tTJu2dhRe3evzyY03Nb.jpg', 'A nine-year-old boy gets a plastic Indian and a cupboard for his birthday and finds himself involved in adventure when the Indian comes to life and befriends him.'),
(89, 9714, 'Home Alone 3', 'Raja Gosnell', 'Alex D. Linz, Olek Krupa, Rya Kihlstedt, Lenny Von Dohlen, David Thornton, Haviland Morris', 'Raja Gosnell', 'Comedy, Family', 1997, '20th Century Fox, Hughes Entertainment', '102', 2.6, 'US', 'Polski, English', 'https://image.tmdb.org/t/p/w500/6uOadrCfle0n2LOOxHbgWEdnrm2.jpg', '9-year-old Alex Pruitt is home alone with the chicken pox. Turns out, due to a mix-up among nefarious spies, Alex was given a toy car concealing a top-secret microchip. Now Alex must fend off the spies as they try to break into his house to get it back.'),
(90, 138843, 'The Conjuring', 'James Wan', 'Vera Farmiga, Patrick Wilson, Lili Taylor, Ron Livingston, Hayley McFarland, Sterling Jerins', 'Carey Hayes, Chad Hayes', 'Horror, Thriller', 2013, 'Evergreen Media Group, The Safran Company, New Line Cinema', '112', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/wVYREutTvI2tmxr6ujrHT704wGF.jpg', 'Paranormal investigators Ed and Lorraine Warren work to help a family terrorized by a dark presence in their farmhouse. Forced to confront a powerful entity, the Warrens find themselves caught in the most terrifying case of their lives.'),
(91, 10140, 'The Chronicles of Narnia: The Voyage of the Dawn Treader', 'Michael Apted', 'Georgie Henley, Skandar Keynes, Ben Barnes, Will Poulter, Anna Popplewell, Tilda Swinton', 'Christopher Markus, Stephen McFeely, Michael Petroni', 'Adventure, Family, Fantasy', 2010, 'Fox 2000 Pictures, Walden Media, C.S. Lewis Company', '113', 3.2, 'GB, US', 'English', 'https://image.tmdb.org/t/p/w500/pP27zlm9yeKrCeDZLFLP2HKELot.jpg', 'This time around Edmund and Lucy Pevensie, along with their pesky cousin Eustace Scrubb find themselves swallowed into a painting and on to a fantastic Narnian ship headed for the very edges of the world.'),
(92, 10020, 'Beauty and the Beast', 'Gary Trousdale', 'Paige O\'Hara, Robby Benson, Richard White, Jerry Orbach, David Ogden Stiers, Angela Lansbury', 'Linda Woolverton', 'Romance, Family, Animation, Fantasy', 1991, 'Silver Screen Partners IV, Walt Disney Pictures', '84', 3.9, 'US', 'Français, English', 'https://image.tmdb.org/t/p/w500/hUJ0UvQ5tgE2Z9WpfuduVSdiCiU.jpg', 'Follow the adventures of Belle, a bright young woman who finds herself in the castle of a prince who\'s been turned into a mysterious beast. With the help of the castle\'s enchanted staff, Belle soon learns the most important lesson of all -- that true beauty comes from within.'),
(93, 2770, 'American Pie 2', 'J.B. Rogers', 'Jason Biggs, Thomas Ian Nicholas, Chris Klein, Seann William Scott, Eddie Kaye Thomas, Alyson Hannigan', 'Adam Herz', 'Comedy, Romance', 2001, 'Universal Pictures, Zide-Perry Productions, LivePlanet', '111', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/854ZZxXdeabAs90mrV72NqShJqR.jpg', 'After a year apart - attending different schools, meeting different people - the guys rent a beach house and vow to make this the best summer ever. As it turns out, whether that will happen or not has a lot to do with the girls. Between the wild parties, outrageous revelations and yes, a trip to band camp, they discover that times change and people change, but in the end, it\'s all about sticking together.'),
(94, 2105, 'American Pie', 'Paul Weitz', 'Jason Biggs, Chris Klein, Thomas Ian Nicholas, Alyson Hannigan, Shannon Elizabeth, Tara Reid', 'Adam Herz', 'Comedy, Romance', 1999, 'Zide-Perry Productions, Universal Pictures', '95', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/5P68by2Thn8wHAziyWGEw2O7hco.jpg', 'At a high-school party, four friends find that losing their collective virginity isn\'t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all \"score\" by their senior prom.'),
(95, 12155, 'Alice in Wonderland', 'Tim Burton', 'Mia Wasikowska, Johnny Depp, Anne Hathaway, Helena Bonham Carter, Crispin Glover, Matt Lucas', 'Linda Woolverton', 'Family, Fantasy, Adventure', 2010, 'Walt Disney Pictures, Roth Films, Team Todd, Tim Burton Productions, The Zanuck Company', '108', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/o0kre9wRCZz3jjSjaru7QU0UtFz.jpg', 'Alice, now 19 years old, returns to the whimsical world she first entered as a child and embarks on a journey to discover her true destiny.'),
(96, 8452, 'The 6th Day', 'Roger Spottiswoode', 'Arnold Schwarzenegger, Michael Rapaport, Tony Goldwyn, Michael Rooker, Robert Duvall, Sarah Wynter', 'Marianne Wibberley, Cormac Wibberley', 'Action, Science Fiction, Thriller', 2000, 'Phoenix Pictures, Jon Davison Productions, Columbia Pictures', '123', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/nlbB47qp1oxEtts9Ik3UYAwKWHM.jpg', 'A world of the very near future in which cattle, fish, and even the family pet can be cloned. But cloning humans is illegal - that is until family man Adam Gibson comes home from work one day to find a clone has replaced him. Taken from his family and plunged into a sinister world he doesn\'t understand, Gibson must not only save himself from the assassins who must destroy him to protect their secret, but uncover who and what is behind the horrible things happening to him.'),
(97, 372058, 'Your Name.', 'Makoto Shinkai', 'Ryunosuke Kamiki, Mone Kamishiraishi, Ryo Narita, Aoi Yuuki, Nobunaga Shimazaki, Kaito Ishikawa', 'Makoto Shinkai', 'Animation, Romance, Drama', 2016, 'CoMix Wave Films, TOHO, KADOKAWA, jeki, AMUSE, voque ting, Lawson Entertainment', '106', 4.2, 'JP', '日本語', 'https://image.tmdb.org/t/p/w500/q719jXXEzOoYaps6babgKnONONX.jpg', 'High schoolers Mitsuha and Taki are complete strangers living separate lives. But one night, they suddenly switch places. Mitsuha wakes up in Taki’s body, and he in hers. This bizarre occurrence continues to happen randomly, and the two must adjust their lives around each other.'),
(98, 335983, 'Venom', 'Ruben Fleischer', 'Tom Hardy, Michelle Williams, Riz Ahmed, Scott Haze, Reid Scott, Jenny Slate', 'Scott Rosenberg, Jeff Pinkner, Kelly Marcel', 'Science Fiction, Action', 2018, 'Matt Tolmach Productions, Pascal Pictures, Marvel Entertainment, Tencent Pictures, Arad Productions, Columbia Pictures', '112', 3.4, 'US', '普通话, English, Bahasa melayu', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', 'Investigative journalist Eddie Brock attempts a comeback following a scandal, but accidentally becomes the host of Venom, a violent, super powerful alien symbiote. Soon, he must rely on his newfound powers to protect the world from a shadowy organization looking for a symbiote of their own.'),
(99, 339964, 'Valerian and the City of a Thousand Planets', 'Luc Besson', 'Dane DeHaan, Cara Delevingne, Clive Owen, Rihanna, Ethan Hawke, Herbie Hancock', 'Luc Besson', 'Adventure, Science Fiction, Action', 2017, 'Belga Films, River Road Entertainment, Grive Productions, EuropaCorp, UFA, Fundamental Films, Gulf Film, Novo Pictures, TF1 Films Production, Orange Studio, BNP Paribas Fortis', '137', 3.3, 'FR, US', 'Français, English', 'https://image.tmdb.org/t/p/w500/vlc95gl3PtrjxSEuM8RhTtSm2xU.jpg', 'In the 28th century, Valerian and Laureline are special operatives charged with keeping order throughout the human territories. On assignment from the Minister of Defense, the two undertake a mission to Alpha, an ever-expanding metropolis where species from across the universe have converged over centuries to share knowledge, intelligence, and cultures. At the center of Alpha is a mysterious dark force which threatens the peaceful existence of the City of a Thousand Planets, and Valerian and Laureline must race to identify the menace and safeguard not just Alpha, but the future of the universe.'),
(100, 37135, 'Tarzan', 'Chris Buck', 'Tony Goldwyn, Minnie Driver, Glenn Close, Alex D. Linz, Rosie O\'Donnell, Brian Blessed', 'Tab Murphy, Bob Tzudiker, Noni White', 'Animation, Family, Adventure', 1999, 'Walt Disney Pictures, Edgar Rice Burroughs, Walt Disney Feature Animation', '88', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/bTvHlcqiOjGa3lFtbrTLTM3zasY.jpg', 'Tarzan was a small orphan who was raised by an ape named Kala since he was a child. He believed that this was his family, but on an expedition Jane Porter is rescued by Tarzan. He then finds out that he\'s human. Now Tarzan must make the decision as to which family he should belong to...'),
(101, 16690, 'Return to Never Land', 'Robin Budd', 'Harriet Owen, Blayne Weaver, Jeff Bennett, Kath Soucie, Corey Burton, Andrew McDonough', 'Temple Mathews', 'Adventure, Fantasy, Animation, Family', 2002, 'Disney Television Animation, Walt Disney Pictures, DisneyToon Studios', '72', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/wB3r2b8sxUZspqNyr8copMlt7se.jpg', 'In 1940, the world is besieged by World War II. Wendy, all grown up, has two children; including Jane, who does not believe Wendy\'s stories about Peter Pan.'),
(102, 21385, 'Mickey, Donald, Goofy: The Three Musketeers', 'Donovan Cook', 'Wayne Allwine, Tony Anselmo, Bill Farmer, Russi Taylor, Tress MacNeille, Jim Cummings', 'David Mickey Evans, Evan Spiliotopoulos', 'Adventure, Animation, Comedy, Family', 2004, 'DisneyToon Studios', '68', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/23bvOwfOS9fw347Yc68yPpkmd8i.jpg', 'In Disney\'s take on the Alexander Dumas tale, Mickey Mouse, Donald Duck and Goofy want nothing more than to perform brave deeds on behalf of their queen (Minnie Mouse), but they\'re stymied by the head Musketeer, Pete. Pete secretly wants to get rid of the queen, so he appoints Mickey and his bumbling friends as guardians to Minnie, thinking such a maneuver will ensure his scheme\'s success. The score features songs based on familiar classical melodies.'),
(103, 236735, 'Marshland', 'Alberto Rodríguez', 'Javier Gutiérrez, Raúl Arévalo, María Varod, Perico Cervantes, Jesús Ortiz, Jesús Carroza', 'Rafael Cobos, Alberto Rodríguez', 'Crime, Mystery, Thriller', 2014, 'Sacromonte Films, Atípica Films, Atresmedia Cine', '104', 3.5, 'ES', 'Español, Türkçe', 'https://image.tmdb.org/t/p/w500/vaXobQ6Y1o5sOH9twNz1oUFFRU8.jpg', 'The Spanish Deep South, 1980. A series of brutal murders of adolescent girls in a remote and forgotten town bring together two disparate characters – both detectives in the homicide division – to investigate the cases.'),
(104, 950, 'Ice Age: The Meltdown', 'Carlos Saldanha', 'Ray Romano, John Leguizamo, Denis Leary, Queen Latifah, Seann William Scott, Josh Peck', 'Peter Gaulke, Gerry Swallow, Jim Hecht', 'Animation, Family, Comedy, Adventure', 2006, '20th Century Fox Animation, Blue Sky Studios, 20th Century Fox', '91', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8vNkkk4erLGDg3UfbmSHsTdSNcY.jpg', 'Diego, Manny and Sid return in this sequel to the hit animated movie Ice Age. This time around, the deep freeze is over, and the ice-covered earth is starting to melt, which will destroy the trio\'s cherished valley. The impending disaster prompts them to reunite and warn all the other beasts about the desperate situation.'),
(105, 425, 'Ice Age', 'Chris Wedge', 'Ray Romano, John Leguizamo, Denis Leary, Goran Višnjić, Jack Black, Cedric the Entertainer', 'Michael J. Wilson, Peter Ackerman, Michael Berg', 'Animation, Comedy, Family, Adventure', 2002, 'Blue Sky Studios, 20th Century Fox', '81', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/gLhHHZUzeseRXShoDyC4VqLgsNv.jpg', 'Manny the mammoth, Sid the loquacious sloth, and Diego the sabre-toothed tiger go on a comical quest to return a human baby back to his father, across a world on the brink of an ice age.'),
(106, 12444, 'Harry Potter and the Deathly Hallows: Part 1', 'David Yates', 'Daniel Radcliffe, Emma Watson, Rupert Grint, Toby Jones, Helena Bonham Carter, Alan Rickman', 'Steve Kloves', 'Adventure, Fantasy', 2010, 'Warner Bros. Pictures, Heyday Films', '146', 3.9, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/iGoXIpQb7Pot00EEdwpwPajheZ5.jpg', 'Harry, Ron and Hermione walk away from their last year at Hogwarts to find and destroy the remaining Horcruxes, putting an end to Voldemort\'s bid for immortality. But with Harry\'s beloved Dumbledore dead and Voldemort\'s unscrupulous Death Eaters on the loose, the world is more dangerous than ever.'),
(107, 18785, 'The Hangover', 'Todd Phillips', 'Bradley Cooper, Ed Helms, Zach Galifianakis, Justin Bartha, Heather Graham, Sasha Barrese', 'Todd Phillips', 'Comedy', 2009, 'Legendary Pictures, Green Hat Films, Warner Bros. Pictures', '100', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/A0uS9rHR56FeBtpjVki16M5xxSW.jpg', 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can\'t seem to locate their best friend, Doug – who\'s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.'),
(108, 10948, 'The Fox and the Hound', 'Richard Rich', 'Mickey Rooney, Kurt Russell, Pearl Bailey, Jack Albertson, Sandy Duncan, Jeanette Nolan', 'Ted Berman, Art Stevens', 'Adventure, Animation, Drama, Family', 1981, 'Walt Disney Productions', '82', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/aC3k6XBaYnulGSkK8263ABjU3Md.jpg', 'When a feisty little fox named Tod is adopted into a farm family, he quickly becomes friends with a fun and adorable hound puppy named Copper. Life is full of hilarious adventures until Copper is expected to take on his role as a hunting dog -- and the object of his search is his best friend!'),
(109, 65057, 'The Descendants', 'Alexander Payne', 'George Clooney, Shailene Woodley, Amara Miller, Nick Krause, Patricia Hastie, Grace A. Cruz', 'Alexander Payne, Nat Faxon, Jim Rash', 'Comedy, Drama', 2011, 'Dune Entertainment, Fox Searchlight Pictures, Ad Hominem Enterprises', '115', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8cDq5UlOPYeKm39okALCEOsZPxk.jpg', 'With his wife Elizabeth on life support after a boating accident, Hawaiian land baron Matt King takes his daughters on a trip from Oahu to Kauai to confront a young real estate broker, who was having an affair with Elizabeth before her misfortune.'),
(110, 259693, 'The Conjuring 2', 'James Wan', 'Vera Farmiga, Patrick Wilson, Madison Wolfe, Frances O\'Connor, Lauren Esposito, Benjamin Haigh', 'David Leslie Johnson-McGoldrick, Carey Hayes, James Wan', 'Horror', 2016, 'New Line Cinema, The Safran Company, Atomic Monster, RatPac Entertainment', '134', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg', 'Lorraine and Ed Warren travel to north London to help a single mother raising four children alone in a house plagued by malicious spirits.'),
(111, 299537, 'Captain Marvel', 'Ryan Fleck', 'Brie Larson, Samuel L. Jackson, Ben Mendelsohn, Jude Law, Annette Bening, Djimon Hounsou', 'Geneva Robertson-Dworet, Ryan Fleck, Anna Boden', 'Action, Adventure, Science Fiction', 2019, 'Marvel Studios', '124', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/AtsgWhDnHTq68L0lLsUrCnM7TjG.jpg', 'The story follows Carol Danvers as she becomes one of the universe’s most powerful heroes when Earth is caught in the middle of a galactic war between two alien races. Set in the 1990s, Captain Marvel is an all-new adventure from a previously unseen period in the history of the Marvel Cinematic Universe.'),
(112, 497698, 'Black Widow', 'Cate Shortland', 'Scarlett Johansson, Florence Pugh, Rachel Weisz, David Harbour, Ray Winstone, Ever Anderson', 'Eric Pearson', 'Action, Adventure, Science Fiction', 2021, 'Marvel Studios', '134', 3.6, 'US', 'English, Pусский', 'https://image.tmdb.org/t/p/w500/qAZ0pzat24kLdO3o8ejmbLxyOac.jpg', 'Natasha Romanoff, also known as Black Widow, confronts the darker parts of her ledger when a dangerous conspiracy with ties to her past arises. Pursued by a force that will stop at nothing to bring her down, Natasha must deal with her history as a spy and the broken relationships left in her wake long before she became an Avenger.'),
(113, 339403, 'Baby Driver', 'Edgar Wright', 'Ansel Elgort, Kevin Spacey, Lily James, Jon Hamm, Jamie Foxx, Jon Bernthal', 'Edgar Wright', 'Action, Crime', 2017, 'Big Talk Studios, Working Title Films, MRC', '113', 3.7, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/tYzFuYXmT8LOYASlFCkaPiAFAl0.jpg', 'After being coerced into working for a crime boss, a young getaway driver finds himself taking part in a heist doomed to fail.'),
(114, 99861, 'Avengers: Age of Ultron', 'Joss Whedon', 'Robert Downey Jr., Chris Hemsworth, Mark Ruffalo, Chris Evans, Scarlett Johansson, Jeremy Renner', 'Joss Whedon', 'Action, Adventure, Science Fiction', 2015, 'Marvel Studios', '141', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg', 'When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.'),
(115, 580175, 'Another Round', 'Thomas Vinterberg', 'Mads Mikkelsen, Thomas Bo Larsen, Magnus Millang, Lars Ranthe, Maria Bonnevie, Helene Reingaard Neumann', 'Thomas Vinterberg', 'Comedy, Drama', 2020, 'Zentropa Entertainments, Film i Väst, Topkapi Films, Zentropa International Sweden, Zentropa International Netherlands', '117', 3.8, 'DK', 'Dansk, svenska', 'https://image.tmdb.org/t/p/w500/aDcIt4NHURLKnAEu7gow51Yd00Q.jpg', 'Four stagnant high school teachers decide to test out a theory that maintaining a constant level of intoxication will improve their overall lives.'),
(116, 812, 'Aladdin', 'John Musker', 'Scott Weinger, Robin Williams, Linda Larkin, Jonathan Freeman, Gilbert Gottfried, Douglas Seale', 'Ron Clements, Ted Elliott, Terry Rossio', 'Animation, Family, Adventure, Fantasy, Romance', 1992, 'Walt Disney Feature Animation', '91', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/eLFfl7vS8dkeG1hKp5mwbm37V83.jpg', 'In the boorish city of Agrabah, kind-hearted street urchin Aladdin and Princess Jasmine fall in love, although she can only marry a prince. He and power-hungry Grand Vizier Jafar vie for a magic lamp that can fulfill their wishes.'),
(117, 338967, 'Zombieland: Double Tap', 'Ruben Fleischer', 'Jesse Eisenberg, Woody Harrelson, Emma Stone, Abigail Breslin, Zoey Deutch, Avan Jogia', 'David Callaham, Rhett Reese, Paul Wernick', 'Horror, Comedy', 2019, 'Columbia Pictures, 2.0 Entertainment, Pariah', '99', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/dtRbVsUb5O12WWO54SRpiMtHKC0.jpg', 'Columbus, Tallahassee, Wichita, and Little Rock move to the American heartland as they face off against evolved zombies, fellow survivors, and the growing pains of the snarky makeshift family.'),
(118, 10895, 'Pinocchio', 'Hamilton Luske', 'Dickie Jones, Cliff Edwards, Christian Rub, Evelyn Venable, Walter Catlett, Mel Blanc', 'Hamilton Luske, Ben Sharpsteen', 'Animation, Family, Fantasy', 1940, 'Walt Disney Productions', '88', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/bnZJrLRnoQHpzEJdka1KYfsAF3N.jpg', 'When the gentle woodcarver Geppetto builds a marionette to be his substitute son, a benevolent fairy brings the toy to life. The puppet, named Pinocchio, is not yet a human boy. He must earn the right to be real by proving that he is brave, truthful, and unselfish.'),
(120, 12144, 'The Land Before Time', 'Don Bluth', 'Gabriel Damon, Candace Hutson, Will Ryan, Judith Barsi, Helen Shaver, Pat Hingle', 'Stu Krieger', 'Family, Animation, Adventure, Drama', 1988, 'Universal Pictures, Amblin Entertainment, Don Bluth Entertainment, Don Bluth Ireland', '69', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/vP2cDLZyj8mlu97m1N3q9nxNrRS.jpg', 'An orphaned brontosaurus named Littlefoot sets off in search of the legendary Great Valley. A land of lush vegetation where the dinosaurs can thrive and live in peace. Along the way he meets four other young dinosaurs, each one a different species, and they encounter several obstacles as they learn to work together in order to survive.'),
(121, 81005, 'Jack the Giant Slayer', 'Bryan Singer', 'Nicholas Hoult, Eleanor Tomlinson, Ewan McGregor, Stanley Tucci, Ian McShane, Bill Nighy', 'Darren Lemke, Christopher McQuarrie, Dan Studney', 'Fantasy, Action, Adventure', 2013, 'New Line Cinema, Legendary Pictures, Original Film, Big Kid Pictures, Bad Hat Harry Productions, Warner Bros. Pictures', '114', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/9jSI7saUX9Qz0JLh19jX2ulEwL7.jpg', 'The story of an ancient war that is reignited when a young farmhand unwittingly opens a gateway between our world and a fearsome race of giants. Unleashed on the Earth for the first time in centuries, the giants strive to reclaim the land they once lost, forcing the young man, Jack into the battle of his life to stop them. Fighting for a kingdom, its people, and the love of a brave princess, he comes face to face with the unstoppable warriors he thought only existed in legend–and gets the chance to become a legend himself.'),
(122, 152601, 'Her', 'Spike Jonze', 'Joaquin Phoenix, Scarlett Johansson, Lynn Adrianna, Lisa Renee Pitts, Gabe Gomez, Chris Pratt', 'Spike Jonze', 'Romance, Science Fiction, Drama', 2013, 'Annapurna Pictures', '126', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg', 'In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user\'s every need. To Theodore\'s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.'),
(123, 64682, 'The Great Gatsby', 'Baz Luhrmann', 'Leonardo DiCaprio, Tobey Maguire, Carey Mulligan, Joel Edgerton, Elizabeth Debicki, Isla Fisher', 'Baz Luhrmann, Craig Pearce', 'Drama, Romance', 2013, 'Warner Bros. Pictures, Village Roadshow Pictures, Bazmark, Red Wagon Entertainment, A+E Global Media', '143', 3.7, 'US, AU', 'English', 'https://image.tmdb.org/t/p/w500/nimh1rrDDLhgpG8XAYoUZXHYwb6.jpg', 'An adaptation of F. Scott Fitzgerald\'s Long Island-set novel, where Midwesterner Nick Carraway is lured into the lavish world of his neighbor, Jay Gatsby. Soon enough, however, Carraway will see through the cracks of Gatsby\'s nouveau riche existence, where obsession, madness, and tragedy await.'),
(124, 2454, 'The Chronicles of Narnia: Prince Caspian', 'Andrew Adamson', 'William Moseley, Anna Popplewell, Skandar Keynes, Georgie Henley, Ben Barnes, Tilda Swinton', 'Andrew Adamson, Christopher Markus, Stephen McFeely', 'Adventure, Family, Fantasy', 2008, 'Walt Disney Pictures, Walden Media, Silverbell Films, Mark Johnson Productions, C.S. Lewis Company', '150', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/qxz3WIyjZiSKUhaTIEJ3c1GcC9z.jpg', 'One year after their incredible adventures in the Lion, the Witch and the Wardrobe, Peter, Edmund, Lucy and Susan Pevensie return to Narnia to aid a young prince whose life has been threatened by the evil King Miraz. Now, with the help of a colorful cast of new characters, including Trufflehunter the badger and Nikabrik the dwarf, the Pevensie clan embarks on an incredible quest to ensure that Narnia is returned to its rightful heir.'),
(125, 559969, 'El Camino: A Breaking Bad Movie', 'Vince Gilligan', 'Aaron Paul, Jesse Plemons, Charles Baker, Matt Jones, Scott MacArthur, Larry Hankin', 'Vince Gilligan', 'Crime, Drama, Thriller', 2019, 'Sony Pictures Television, Gran Via Productions, High Bridge Productions', '123', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/ePXuKdXZuJx8hHMNr2yM4jY2L7Z.jpg', 'In the wake of his dramatic escape from captivity, Jesse Pinkman must come to terms with his past in order to forge some kind of future.'),
(126, 363088, 'Ant-Man and the Wasp', 'Peyton Reed', 'Paul Rudd, Evangeline Lilly, Michael Douglas, Hannah John-Kamen, Randall Park, Michelle Pfeiffer', 'Chris McKenna, Paul Rudd, Erik Sommers', 'Action, Adventure, Science Fiction', 2018, 'Marvel Studios', '119', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/cFQEO687n1K6umXbInzocxcnAQz.jpg', 'Just when his time under house arrest is about to end, Scott Lang once again puts his freedom at risk to help Hope van Dyne and Dr. Hank Pym dive into the quantum realm and try to accomplish, against time and any chance of success, a very dangerous rescue mission.'),
(127, 505948, 'I Am Mother', 'Grant Sputore', 'Clara Rugaard, Rose Byrne, Hilary Swank, Luke Hawker, Tahlia Sturzaker, Maddie Lenton', 'Michael Lloyd Green', 'Science Fiction, Thriller', 2019, 'Mother Film Holdings, Rhea Films, Southern Light Films, The Penguin Empire, Fin Design & Effects, Hercules Film Fund', '113', 3.4, 'US, AU', 'English', 'https://image.tmdb.org/t/p/w500/ayPSqlpYIbeq1RiDekx6W9WUqrL.jpg', 'A teenage girl is raised underground by a robot \"Mother\", designed to repopulate the earth following an extinction event. But their unique bond is threatened when an inexplicable stranger arrives with alarming news.'),
(128, 10681, 'WALL·E', 'Andrew Stanton', 'Ben Burtt, Elissa Knight, Jeff Garlin, Fred Willard, John Ratzenberger, Kathy Najimy', 'Jim Reardon, Andrew Stanton', 'Animation, Family, Science Fiction', 2008, 'Pixar', '98', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/hbhFnRzzg6ZDmm8YAmxBnQpQIPh.jpg', 'After hundreds of years doing what he was built for, WALL•E— a robot designed to clean up the earth—discovers a new purpose in life when he meets a sleek search robot named EVE. EVE comes to realize that WALL•E has inadvertently stumbled upon the key to the planet\'s future, and races back to space to report to the humans. Meanwhile, WALL•E chases EVE across the galaxy and sets into motion one of the most imaginative adventures ever brought to the big screen.'),
(129, 2300, 'Space Jam', 'Joe Pytka', 'Michael Jordan, Wayne Knight, Theresa Randle, Manner Washington, Eric Gordon, Penny Bae Bridges', 'Joe Pytka', 'Family, Animation, Science Fiction, Fantasy, Comedy', 1996, 'Warner Bros. Family Entertainment, Ivan Reitman Productions', '87', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/4RN5El3Pj2W4gpwgiAGLVfSJv2g.jpg', 'With their freedom on the line, the Looney Tunes seek the help of NBA superstar Michael Jordan to win a basketball game against a team of moronic aliens.'),
(130, 107, 'Snatch', 'Guy Ritchie', 'Jason Statham, Alan Ford, Stephen Graham, Brad Pitt, Dennis Farina, Robbie Gee', 'Guy Ritchie', 'Crime, Comedy', 2000, 'Marv', '103', 3.9, 'GB', 'English, Pусский', 'https://image.tmdb.org/t/p/w500/kJZoAHq1SLDdWjeNGtlHAnGpmFV.jpg', 'Unscrupulous boxing promoters, violent bookies, a Russian gangster, incompetent amateur robbers, and supposedly Jewish jewellers fight to track down a priceless stolen diamond.'),
(131, 566525, 'Shang-Chi and the Legend of the Ten Rings', 'Destin Daniel Cretton', 'Simu Liu, Tony Leung Chiu-wai, Awkwafina, Ben Kingsley, Zhang Meng\'er, Fala Chen', 'Destin Daniel Cretton, David Callaham, Andrew Lanham', 'Action, Adventure, Fantasy', 2021, 'Marvel Studios', '132', 3.8, 'US', 'English, 普通话', 'https://image.tmdb.org/t/p/w500/9f2Q0U3IOsLgrI2HkvldwSABZy5.jpg', 'Shang-Chi must confront the past he thought he left behind when he is drawn into the web of the mysterious Ten Rings organization.'),
(132, 10601, 'Peter Pan', 'P.J. Hogan', 'Jeremy Sumpter, Jason Isaacs, Rachel Hurd-Wood, Ludivine Sagnier, Olivia Williams, Harry Newell', 'Michael Goldenberg, P.J. Hogan', 'Adventure, Fantasy, Family', 2003, 'Universal Pictures, Columbia Pictures, Revolution Studios, Red Wagon Entertainment, Allied Stars', '113', 3.6, 'AU, GB, US', 'English, Français, ελληνικά, , Português', 'https://image.tmdb.org/t/p/w500/6QdU3TZZrIvXFzoHOwafZAynFjB.jpg', 'In stifling Edwardian London, Wendy Darling mesmerizes her brothers every night with bedtime tales of swordplay, swashbuckling and the fearsome Captain Hook. But the children become the heroes of an even greater story, when Peter Pan flies into their nursery one night and leads them over moonlit rooftops through a galaxy of stars and to the lush jungles of Neverland.'),
(133, 343668, 'Kingsman: The Golden Circle', 'Matthew Vaughn', 'Taron Egerton, Colin Firth, Julianne Moore, Mark Strong, Hanna Alström, Halle Berry', 'Matthew Vaughn', 'Action, Adventure, Comedy, Crime, Science Fiction', 2017, '20th Century Fox, Marv, Cloudy Productions, TSG Entertainment', '141', 3.5, 'US, GB', 'svenska, English, Italiano', 'https://image.tmdb.org/t/p/w500/34xBL6BXNYFqtHO9zhcgoakS4aP.jpg', 'When an attack on the Kingsman headquarters takes place and a new villain rises, Eggsy and Merlin are forced to work together with the American agency known as the Statesman to save the world.'),
(134, 16869, 'Inglourious Basterds', 'Quentin Tarantino', 'Brad Pitt, Mélanie Laurent, Christoph Waltz, Eli Roth, Michael Fassbender, Diane Kruger', 'Quentin Tarantino', 'Drama, Thriller, War', 2009, 'Universal Pictures, The Weinstein Company, A Band Apart, Zehnte Babelsberg Film, Visiona Romantica', '153', 4.1, 'US', 'Deutsch, English, Français, Italiano', 'https://image.tmdb.org/t/p/w500/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg', 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as \"The Basterds\" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.'),
(135, 45243, 'The Hangover Part II', 'Todd Phillips', 'Bradley Cooper, Ed Helms, Zach Galifianakis, Justin Bartha, Mason Lee, Ken Jeong', 'Scot Armstrong, Craig Mazin, Todd Phillips', 'Comedy', 2011, 'Legendary Pictures, Green Hat Films, Warner Bros. Pictures', '102', 3.3, 'US', 'English, ภาษาไทย', 'https://image.tmdb.org/t/p/w500/cKZu0Fdkj7dmwbfMpgDqVVCkLJQ.jpg', 'The Hangover crew heads to Thailand for Stu\'s wedding. After the disaster of a bachelor party in Las Vegas last year, Stu is playing it safe with a mellow pre-wedding brunch. However, nothing goes as planned and Bangkok is the perfect setting for another adventure with the rowdy group.'),
(136, 109445, 'Frozen', 'Chris Buck', 'Kristen Bell, Idina Menzel, Jonathan Groff, Josh Gad, Santino Fontana, Alan Tudyk', 'Jennifer Lee', 'Animation, Family, Adventure, Fantasy', 2013, 'Walt Disney Animation Studios', '102', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/itAKcobTYGpYT8Phwjd8c9hleTo.jpg', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She\'s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.'),
(137, 284054, 'Black Panther', 'Ryan Coogler', 'Chadwick Boseman, Michael B. Jordan, Lupita Nyong\'o, Danai Gurira, Martin Freeman, Daniel Kaluuya', 'Ryan Coogler', 'Action, Adventure, Science Fiction', 2018, 'Marvel Studios', '135', 3.7, 'US', 'English, 한국어/조선말, Kiswahili, ', 'https://image.tmdb.org/t/p/w500/uxzzxijgPIY7slzFvMotPv8wjKA.jpg', 'King T\'Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country\'s new leader. However, T\'Challa soon finds that he is challenged for the throne by factions within his own country as well as without. Using powers reserved to Wakandan kings, T\'Challa assumes the Black Panther mantle to join with ex-girlfriend Nakia, the queen-mother, his princess-kid sister, members of the Dora Milaje (the Wakandan \'special forces\') and an American secret agent, to prevent Wakanda from being dragged into a world war.'),
(138, 102382, 'The Amazing Spider-Man 2', 'Marc Webb', 'Andrew Garfield, Emma Stone, Jamie Foxx, Dane DeHaan, Colm Feore, Felicity Jones', 'Alex Kurtzman, Jeff Pinkner, Roberto Orci', 'Action, Adventure, Science Fiction', 2014, 'Columbia Pictures, Matt Tolmach Productions, Arad Productions, Marvel Entertainment', '141', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/dGjoPttcbKR5VWg1jQuNFB247KL.jpg', 'For Peter Parker, life is busy. Between taking out the bad guys as Spider-Man and spending time with the person he loves, Gwen Stacy, high school graduation cannot come quickly enough. Peter has not forgotten about the promise he made to Gwen’s father to protect her by staying away, but that is a promise he cannot keep. Things will change for Peter when a new villain, Electro, emerges, an old friend, Harry Osborn, returns, and Peter uncovers new clues about his past.'),
(139, 466272, 'Once Upon a Time... in Hollywood', 'Quentin Tarantino', 'Leonardo DiCaprio, Brad Pitt, Margot Robbie, Emile Hirsch, Margaret Qualley, Timothy Olyphant', 'Quentin Tarantino', 'Comedy, Drama, Thriller', 2019, 'Heyday Films, Columbia Pictures, Bona Film Group', '162', 3.7, 'US', 'English, Italiano, Español', 'https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', 'Los Angeles, 1969. TV star Rick Dalton, a struggling actor specializing in westerns, and stuntman Cliff Booth, his best friend, try to survive in a constantly changing movie industry. Dalton is the neighbor of the young and promising actress and model Sharon Tate, who has just married the prestigious Polish director Roman Polanski…'),
(140, 10144, 'The Little Mermaid', 'John Musker', 'Jodi Benson, Samuel E. Wright, Pat Carroll, Christopher Daniel Barnes, Kenneth Mars, Buddy Hackett', 'John Musker, Ron Clements', 'Animation, Family, Fantasy', 1989, 'Silver Screen Partners IV, Walt Disney Feature Animation', '83', 3.7, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/plcZXvI310FkbwIptvd6rqk63LP.jpg', 'This colorful adventure tells the story of an impetuous mermaid princess named Ariel who falls in love with the very human Prince Eric and puts everything on the line for the chance to be with him. Memorable songs and characters -- including the villainous sea witch Ursula.'),
(141, 45269, 'The King\'s Speech', 'Tom Hooper', 'Colin Firth, Geoffrey Rush, Helena Bonham Carter, Guy Pearce, Timothy Spall, Michael Gambon', 'David Seidler', 'Drama, History', 2010, 'The Weinstein Company, UK Film Council, Momentum Pictures, Aegis Film Fund, Molinare Investment, FilmNation Entertainment, See-Saw Films, Bedlam Productions', '118', 3.9, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/pVNKXVQFukBaCz6ML7GH3kiPlQP.jpg', 'The King\'s Speech tells the story of the man who became King George VI, the father of Queen Elizabeth II. After his brother abdicates, George (\'Bertie\') reluctantly assumes the throne. Plagued by a dreaded stutter and considered unfit to be king, Bertie engages the help of an unorthodox speech therapist named Lionel Logue. Through a set of unexpected techniques, and as a result of an unlikely friendship, Bertie is able to find his voice and boldly lead the country into war.'),
(142, 10756, 'The Haunted Mansion', 'Rob Minkoff', 'Eddie Murphy, Marsha Thomason, Terence Stamp, Nathaniel Parker, Jennifer Tilly, Dina Spybey-Waters', 'David Berenbaum', 'Thriller, Fantasy, Comedy, Family, Mystery', 2003, 'Doom Buggy Productions, Walt Disney Pictures, Gunn Films', '88', 2.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/lGi5yio4pdDz5PkSeZCbnMQz5vK.jpg', 'Workaholic Jim Evers and his wife/business partner Sara get a call one night from  a mansion owner, Edward Gracey, who wants to sell his house. Once the Evers family arrive at the mansion, a torrential thunderstorm of mysterious origin strands them with the brooding, eccentric Gracey, his mysterious butler, and a variety of residents both seen and unseen.'),
(143, 12445, 'Harry Potter and the Deathly Hallows: Part 2', 'David Yates', 'Daniel Radcliffe, Emma Watson, Rupert Grint, Ralph Fiennes, Alan Rickman, Michael Gambon', 'Steve Kloves', 'Adventure, Fantasy', 2011, 'Warner Bros. Pictures, Heyday Films', '130', 4.0, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/c54HpQmuwXjHq2C9wmoACjxoom3.jpg', 'Harry, Ron and Hermione continue their quest to vanquish the evil Voldemort once and for all. Just as things begin to look hopeless for the young wizards, Harry discovers a trio of magical objects that endow him with powers to rival Voldemort\'s formidable skills.'),
(144, 9487, 'A Bug\'s Life', 'John Lasseter', 'Dave Foley, Kevin Spacey, Julia Louis-Dreyfus, Hayden Panettiere, Phyllis Diller, Richard Kind', 'Don McEnery, Bob Shaw, Andrew Stanton', 'Adventure, Animation, Comedy, Family', 1998, 'Pixar', '95', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/Ah3J9OJVc2CNCuH2zMydXy9fmIC.jpg', 'On behalf of \"oppressed bugs everywhere,\" an inventive ant named Flik hires a troupe of warrior bugs to defend his bustling colony from a horde of freeloading grasshoppers led by the evil-minded Hopper.'),
(145, 10957, 'The Black Cauldron', 'Ted Berman', 'Grant Bardsley, Susan Sheridan, John Byner, Nigel Hawthorne, John Hurt, Freddie Jones', 'Ted Berman, Richard Rich', 'Animation, Adventure, Family, Fantasy', 1985, 'Silver Screen Partners II, Walt Disney Pictures, Walt Disney Productions', '80', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/h64i9e6oJs2jrDZ4QzspXMqZhPF.jpg', 'Taran is an assistant pigkeeper with boyish dreams of becoming a great warrior. However, he has to put the daydreaming aside when his charge, an oracular pig named Hen Wen, is kidnapped by an evil lord known as the Horned King. The villain hopes Hen will show him the way to The Black Cauldron, which has the power to create a giant army of unstoppable soldiers.'),
(146, 12335, 'Bedknobs and Broomsticks', 'Robert Stevenson', 'Angela Lansbury, David Tomlinson, Roddy McDowall, Sam Jaffe, John Ericson, Bruce Forsyth', 'Bill Walsh, Don DaGradi', 'Family, Animation, Fantasy', 1971, 'Walt Disney Productions', '117', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/1BBzsThIZ06UmjZ3rChYGZhJtFQ.jpg', 'Three children evacuated from London during World War II are forced to stay with an eccentric spinster. The children\'s initial fears disappear when they find out she is in fact a trainee witch.'),
(147, 258230, 'A Monster Calls', 'J. A. Bayona', 'Lewis MacDougall, Sigourney Weaver, Felicity Jones, Toby Kebbell, Ben Moor, James Melville', 'Patrick Ness', 'Fantasy, Adventure, Family', 2016, 'River Road Entertainment, Participant, Apaches Films, La Trini, A Monster Calls, Telecinco Cinema', '108', 3.7, 'ES', 'English', 'https://image.tmdb.org/t/p/w500/vNzWJwVqjszWwXrA7ZfsrJmhgV9.jpg', '12-year-old Conor encounters an ancient tree monster who proceeds to help him cope with his mother\'s terminal illness and being bullied in school.'),
(148, 294254, 'Maze Runner: The Scorch Trials', 'Wes Ball', 'Dylan O\'Brien, Kaya Scodelario, Thomas Brodie-Sangster, Giancarlo Esposito, Ki Hong Lee, Dexter Darden', 'T.S. Nowlin', 'Science Fiction, Action, Thriller, Adventure', 2015, 'Temple Hill Entertainment, The Gotham Group, TSG Entertainment, 20th Century Fox', '131', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/mYw7ZyejqSCPFlrT2jHZOESZDU3.jpg', 'Thomas and his fellow Gladers face their greatest challenge yet: searching for clues about the mysterious and powerful organization known as WCKD. Their journey takes them to the Scorch, a desolate landscape filled with unimaginable obstacles. Teaming up with resistance fighters, the Gladers take on WCKD’s vastly superior forces and uncover its shocking plans for them all.');
INSERT INTO `peliculas` (`idPelicula`, `idApi`, `nombrePelicula`, `directorPelicula`, `actorPelicula`, `guionistaPelicula`, `generoPelicula`, `anoPelicula`, `companiaPelicula`, `duracionPelicula`, `ratingAvgPelicula`, `paisPelicula`, `idiomaPelicula`, `posterPelicula`, `sinopsisPelicula`) VALUES
(149, 674, 'Harry Potter and the Goblet of Fire', 'Mike Newell', 'Daniel Radcliffe, Rupert Grint, Emma Watson, Brendan Gleeson, Michael Gambon, Robert Pattinson', 'Steve Kloves', 'Adventure, Fantasy', 2005, 'Warner Bros. Pictures, Heyday Films, Patalex IV Productions', '157', 3.9, 'GB', 'English, Français', 'https://image.tmdb.org/t/p/w500/fECBtHlr0RB3foNHDiCBXeg9Bv9.jpg', 'When his name emerges from the Goblet of Fire, Harry Potter becomes a competitor in a grueling battle for glory among three wizarding schools. Signs of Voldemort\'s return emerge as Harry\'s friends help him prepare for the Triwizard Tournament.'),
(150, 1265, 'Bridge to Terabithia', 'Gábor Csupó', 'Josh Hutcherson, AnnaSophia Robb, Zooey Deschanel, Robert Patrick, Bailee Madison, Kate Butler', 'Jeff Stockwell, David Paterson', 'Adventure, Drama, Family', 2007, 'Lauren Levine Productions Inc., Walden Media, Hal Lieberman Company', '95', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/3xFxGodKPMFLheS8rujFSmLfcq4.jpg', 'Jesse Aarons trained all summer to become the fastest runner in school. So he\'s very upset when newcomer Leslie Burke outruns him and everyone else. Despite this and other differences including that she\'s rich, he\'s poor, she\'s a city girl, and he\'s a country boy the two become fast friends. Together they create Terabithia, a land of monsters, trolls, ogres, and giants where they rule as king and queen.'),
(151, 280, 'Terminator 2: Judgment Day', 'James Cameron', 'Arnold Schwarzenegger, Linda Hamilton, Edward Furlong, Robert Patrick, Earl Boen, Joe Morton', 'James Cameron', 'Action, Thriller, Science Fiction', 1991, 'Carolco Pictures, Pacific Western, Lightstorm Entertainment, Le Studio Canal+', '137', 4.1, 'FR, US', 'English, Español', 'https://image.tmdb.org/t/p/w500/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg', 'Ten years after the events of the original, a reprogrammed T-800 is sent back in time to protect young John Connor from the shape-shifting T-1000. Together with his mother Sarah, he fights to stop Skynet from triggering a nuclear apocalypse.'),
(152, 381288, 'Split', 'M. Night Shyamalan', 'James McAvoy, Anya Taylor-Joy, Haley Lu Richardson, Jessica Sula, Betty Buckley, Izzie Coffey', 'M. Night Shyamalan', 'Horror, Thriller', 2017, 'Blinding Edge Pictures, Blumhouse Productions', '117', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/lli31lYTFpvxVBeFHWoe5PMfW5s.jpg', 'Though Kevin has evidenced 23 personalities to his trusted psychiatrist, Dr. Fletcher, there remains one still submerged who is set to materialize and dominate all the others. Compelled to abduct three teenage girls led by the willful, observant Casey, Kevin reaches a war for survival among all of those contained within him — as well as everyone around him — as the walls between his compartments shatter apart.'),
(153, 11886, 'Robin Hood', 'Wolfgang Reitherman', 'Brian Bedford, Phil Harris, Andy Devine, Monica Evans, Peter Ustinov, Terry-Thomas', 'Wolfgang Reitherman', 'Animation, Family, Adventure', 1973, 'Walt Disney Productions', '83', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/x9AvkYek0bGdxQSZ8W3lAjGrREm.jpg', 'With King Richard off to the Crusades, Prince John and his slithering minion, Sir Hiss, set about taxing Nottingham\'s citizens with support from the corrupt sheriff - and staunch opposition by the wily Robin Hood and his band of merry men.'),
(154, 624860, 'The Matrix Resurrections', 'Lana Wachowski', 'Keanu Reeves, Carrie-Anne Moss, Yahya Abdul-Mateen II, Jonathan Groff, Jessica Henwick, Neil Patrick Harris', 'Lana Wachowski', 'Science Fiction, Action, Adventure', 2021, 'Warner Bros. Pictures, Village Roadshow Pictures, Venus Castina Productions', '148', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg', 'Plagued by strange memories, Neo\'s life takes an unexpected turn when he finds himself back inside the Matrix.'),
(155, 300669, 'Don\'t Breathe', 'Fede Álvarez', 'Stephen Lang, Jane Levy, Dylan Minnette, Daniel Zovatto, Emma Bercovici, Franciska Törőcsik', 'Fede Álvarez', 'Horror, Thriller, Crime', 2016, 'Screen Gems, Stage 6 Films, Ghost House Pictures', '89', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/dSxHyPZ2nipSfvdft4IhQKjk5eZ.jpg', 'A group of teens break into a blind man\'s home thinking they\'ll get away with the perfect crime. They\'re wrong.'),
(156, 10722, 'The Day of the Beast', 'Álex de la Iglesia', 'Álex Angulo, Santiago Segura, Armando De Razza, Terele Pávez, Nathalie Seseña, Maria Grazia Cucinotta', 'Álex de la Iglesia, Jorge Guerricaechevarría', 'Horror, Comedy, Action', 1995, 'Iberoamericana Films Produccion, Sogetel, M.G. S.r.l.', '104', 3.6, 'ES', 'Español, Italiano', 'https://image.tmdb.org/t/p/w500/yEXhgACPIV4PmTgHT2HS3Ko2oS3.jpg', 'When a rogue priest discovers the exact date the Antichrist will be born, he enlists a Death Metal record store clerk and a cheesy TV psychic for an urban spree of gore, sacrilege and twisted humor to prevent the Apocalypse.'),
(157, 271110, 'Captain America: Civil War', 'Joe Russo', 'Chris Evans, Robert Downey Jr., Scarlett Johansson, Sebastian Stan, Anthony Mackie, Don Cheadle', 'Stephen McFeely, Christopher Markus', 'Adventure, Action, Science Fiction', 2016, 'Marvel Studios', '147', 3.7, 'US', 'Română, English, Deutsch, Pусский', 'https://image.tmdb.org/t/p/w500/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', 'Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.'),
(158, 20504, 'The Book of Eli', 'Albert Hughes', 'Denzel Washington, Gary Oldman, Mila Kunis, Ray Stevenson, Jennifer Beals, Michael Gambon', 'Allen Hughes, Albert Hughes', 'Action, Thriller, Science Fiction', 2010, 'Alcon Entertainment, Silver Pictures', '118', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/1H1y9ZiqNFaLgQiRDDZLA55PviW.jpg', 'A post-apocalyptic tale, in which a lone man fights his way across America in order to protect a sacred book that holds the secrets to saving humankind.'),
(159, 336843, 'Maze Runner: The Death Cure', 'Wes Ball', 'Dylan O\'Brien, Kaya Scodelario, Thomas Brodie-Sangster, Ki Hong Lee, Dexter Darden, Rosa Salazar', 'T.S. Nowlin', 'Science Fiction, Action, Adventure, Thriller', 2018, 'The Gotham Group, Temple Hill Entertainment, 20th Century Fox, Oddball Entertainment, TSG Entertainment', '143', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/s8K0US4tUEoOrQ1LDh0eppuwGDx.jpg', 'Thomas leads his group of escaped Gladers on their final and most dangerous mission yet. To save their friends, they must break into the legendary Last City, a WCKD-controlled labyrinth that may turn out to be the deadliest maze of all. Anyone who makes it out alive will get answers to the questions the Gladers have been asking since they first arrived in the maze.'),
(160, 605, 'The Matrix Revolutions', 'Lana Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving, Jada Pinkett Smith, Mary Alice', 'Lana Wachowski, Lilly Wachowski', 'Adventure, Action, Thriller, Science Fiction', 2003, 'Village Roadshow Pictures, NPV Entertainment, Silver Pictures', '129', 3.4, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/bkkS61w94ZVMNVd8KEyyJl2tnY5.jpg', 'The human city of Zion defends itself against the massive invasion of the machines as Neo fights to end the war at another front while also opposing the rogue Agent Smith.'),
(161, 8587, 'The Lion King', 'Roger Allers', 'Matthew Broderick, Moira Kelly, Jeremy Irons, Nathan Lane, Ernie Sabella, James Earl Jones', 'Linda Woolverton, Jonathan Roberts, Irene Mecchi', 'Animation, Family, Drama', 1994, 'Walt Disney Pictures, Walt Disney Feature Animation', '89', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/sKCr78MXSLixwmZ8DyJLrpMsd15.jpg', 'Young lion prince Simba, eager to one day become king of the Pride Lands, grows up under the watchful eye of his father Mufasa; all the while his villainous uncle Scar conspires to take the throne for himself. Amid betrayal and tragedy, Simba must confront his past and find his rightful place in the Circle of Life.'),
(162, 14873, 'The Jungle Book 2', 'Steve Trenbirth', 'Haley Joel Osment, John Goodman, Mae Whitman, Connor Funk, Bob Joles, Tony Jay', 'Karl Geurs', 'Family, Animation, Adventure', 2003, 'DisneyToon Studios', '72', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/21GanxizOIL1CN0HLx7j3je8k87.jpg', 'Mowgli has been living in the man-village with his little stepbrother Ranjan and his best friend Shanti. But the man-cub still has that jungle rhythm in his heart, and he misses his old buddies Baloo and Bagheera. When Mowgli wanders back to the wild for some swingin\' fun, he soon finds the man-eating tiger Shere Khan is lurking in the shadows and planning his revenge.'),
(163, 49529, 'John Carter', 'Andrew Stanton', 'Taylor Kitsch, Lynn Collins, Samantha Morton, Mark Strong, Ciarán Hinds, Dominic West', 'Michael Chabon, Andrew Stanton, Mark Andrews', 'Action, Adventure, Science Fiction', 2012, 'Walt Disney Pictures', '132', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/lCxz1Yus07QCQQCb6I0Dr3Lmqpx.jpg', 'John Carter is a war-weary, former military captain who\'s inexplicably transported to the mysterious and exotic planet of Barsoom (Mars) and reluctantly becomes embroiled in an epic conflict. It\'s a world on the brink of collapse, and Carter rediscovers his humanity when he realizes the survival of Barsoom and its people rests in his hands.'),
(164, 70160, 'The Hunger Games', 'Gary Ross', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Lenny Kravitz', 'Gary Ross, Billy Ray, Suzanne Collins', 'Science Fiction, Adventure, Action, Thriller', 2012, 'Lionsgate, Color Force', '142', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/yXCbOiVDCxO71zI7cuwBRXdftq8.jpg', 'In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance.'),
(165, 330457, 'Frozen II', 'Jennifer Lee', 'Kristen Bell, Idina Menzel, Josh Gad, Evan Rachel Wood, Jonathan Groff, Sterling K. Brown', 'Allison Schroeder, Jennifer Lee', 'Family, Animation, Adventure, Comedy, Fantasy', 2019, 'Walt Disney Animation Studios', '103', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/mINJaa34MtknCYl5AjtNJzWj8cD.jpg', 'Elsa, Anna, Kristoff and Olaf head far into the forest to learn the truth about an ancient mystery of their kingdom.'),
(166, 411, 'The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', 'Andrew Adamson', 'William Moseley, Anna Popplewell, Skandar Keynes, Georgie Henley, Liam Neeson, Tilda Swinton', 'Andrew Adamson, Christopher Markus, Ann Peacock', 'Adventure, Family, Fantasy', 2005, 'Walt Disney Pictures, Walden Media, C.S. Lewis Company', '143', 3.6, 'US, GB', 'English, Deutsch', 'https://image.tmdb.org/t/p/w500/iREd0rNCjYdf5Ar0vfaW32yrkm.jpg', 'Four kids travel through a wardrobe to the land of Narnia and learn of their destiny to free it with the guidance of a mystical lion.'),
(167, 672, 'Harry Potter and the Chamber of Secrets', 'Chris Columbus', 'Daniel Radcliffe, Rupert Grint, Emma Watson, Kenneth Branagh, Toby Jones, Robbie Coltrane', 'Steve Kloves', 'Adventure, Fantasy', 2002, 'Warner Bros. Pictures, Heyday Films, 1492 Pictures, MIRACLE Productions', '161', 3.9, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/sdEOH0992YZ0QSxgXNIGLq1ToUi.jpg', 'Cars fly, trees fight back, and a mysterious house-elf comes to warn Harry Potter at the start of his second year at Hogwarts. Adventure and danger await when bloody writing on a wall announces: The Chamber Of Secrets Has Been Opened. To save Hogwarts will require all of Harry, Ron and Hermione\'s magical abilities and courage.'),
(168, 24428, 'The Avengers', 'Joss Whedon', 'Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth, Scarlett Johansson, Jeremy Renner', 'Joss Whedon', 'Science Fiction, Action, Adventure', 2012, 'Marvel Studios', '143', 4.0, 'US', 'English, हिन्दी, Pусский', 'https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', 'When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!'),
(169, 72190, 'World War Z', 'Marc Forster', 'Brad Pitt, Mireille Enos, Daniella Kertesz, James Badge Dale, Ludi Boeken, Matthew Fox', 'Drew Goddard, Damon Lindelof, Matthew Michael Carnahan', 'Action, Horror, Science Fiction', 2013, 'GK Films, Paramount Pictures, Hemisphere Media Capital, 2DUX², Skydance Media, Plan B Entertainment', '116', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/aCnVdvExw6UWSeQfr0tUH3jr4qG.jpg', 'Life for former United Nations investigator Gerry Lane and his family seems content. Suddenly, the world is plagued by a mysterious infection turning whole human populations into rampaging mindless zombies. After barely escaping the chaos, Lane is persuaded to go on a mission to investigate this disease. What follows is a perilous trek around the world where Lane must brave horrific dangers and long odds to find answers before human civilization falls.'),
(170, 296096, 'Me Before You', 'Thea Sharrock', 'Emilia Clarke, Sam Claflin, Janet McTeer, Charles Dance, Brendan Coyle, Jenna Coleman', 'Scott Neustadter, Jojo Moyes, Michael H. Weber', 'Drama, Romance', 2016, 'New Line Cinema, Sunswept Entertainment, Metro-Goldwyn-Mayer', '110', 4.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/Ia3dzj5LnCj1ZBdlVeJrbKJQxG.jpg', 'Lou Clark, a directionless 26-year-old from the English countryside, takes a job at the local castle as a caregiver and companion to a wealthy young banker, Will Traynor. Wheelchair-bound from an accident two years prior, the once adventurous Will has all but given up — that is until Lou determines to show him that life is worth living.'),
(171, 11688, 'The Emperor\'s New Groove', 'Mark Dindal', 'David Spade, John Goodman, Eartha Kitt, Patrick Warburton, Wendie Malick, Kellyann Kelso', 'David Reynolds', 'Adventure, Animation, Comedy, Family, Fantasy', 2000, 'Walt Disney Feature Animation, Walt Disney Pictures', '78', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/isA0acj3ONKBLp1pKadUNzxEPFv.jpg', 'When the self‑absorbed Emperor Kuzco is accidentally transformed into a llama, he must rely on a humble villager to survive the jungle and reclaim his throne.'),
(172, 22, 'Pirates of the Caribbean: The Curse of the Black Pearl', 'Gore Verbinski', 'Johnny Depp, Geoffrey Rush, Orlando Bloom, Keira Knightley, Jack Davenport, Jonathan Pryce', 'Terry Rossio, Ted Elliott', 'Adventure, Fantasy, Action', 2003, 'Walt Disney Pictures, Jerry Bruckheimer Films', '143', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', 'When wily pirate Captain Barbossa seizes Jack Sparrow’s beloved ship, the Black Pearl, and kidnaps the governor’s daughter, Elizabeth Swann, blacksmith Will Turner reluctantly teams up with the unpredictable pirate Jack to rescue her—only to uncover a terrifying curse that turns Barbossa’s crew into the undead.'),
(173, 260513, 'Incredibles 2', 'Brad Bird', 'Craig T. Nelson, Holly Hunter, Sarah Vowell, Huck Milner, Catherine Keener, Eli Fucile', 'Brad Bird', 'Action, Adventure, Animation, Family', 2018, 'Pixar', '118', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/9lFKBtaVIhP7E2Pk0IY1CwTKTMZ.jpg', 'Elastigirl springs into action to save the day, while Mr. Incredible faces his greatest challenge yet – taking care of the problems of his three children.'),
(174, 634649, 'Spider-Man: No Way Home', 'Jon Watts', 'Tom Holland, Zendaya, Benedict Cumberbatch, Jacob Batalon, Jon Favreau, Jamie Foxx', 'Jon Watts', 'Action, Adventure, Science Fiction', 2021, 'Marvel Studios, Pascal Pictures, Columbia Pictures', '148', 4.0, 'US', 'English, ', 'https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', 'Peter Parker is unmasked and no longer able to separate his normal life from the high-stakes of being a super-hero. When he asks for help from Doctor Strange the stakes become even more dangerous, forcing him to discover what it truly means to be Spider-Man.'),
(175, 285, 'Pirates of the Caribbean: At World\'s End', 'Gore Verbinski', 'Johnny Depp, Geoffrey Rush, Orlando Bloom, Keira Knightley, Jack Davenport, Bill Nighy', 'Ted Elliott, Terry Rossio', 'Adventure, Fantasy, Action', 2007, 'Jerry Bruckheimer Films, Second Mate Productions, Walt Disney Pictures', '169', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg', 'After losing Captain Jack Sparrow to the locker of Davy Jones, Will Turner, Elizabeth Swann, and Captain Barbossa journey to the ends of the earth to rescue him. And as the East India Trading Company tightens its grip on the seas under Lord Cutler Beckett—now in control of Davy Jones—the fate of piracy hangs by a thread. Now, they must unite the pirate lords for one final stand. But as loyalties are tested and alliances shift, each must ultimately choose where they stand in the battle for freedom on the high seas.'),
(176, 354912, 'Coco', 'Lee Unkrich', 'Anthony Gonzalez, Gael García Bernal, Benjamin Bratt, Alanna Ubach, Renée Victor, Jaime Camil', 'Adrian Molina, Matthew Aldrich', 'Family, Animation, Music, Adventure', 2017, 'Pixar', '105', 4.1, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel\'s family history.'),
(177, 82695, 'Les Misérables', 'Tom Hooper', 'Hugh Jackman, Russell Crowe, Amanda Seyfried, Anne Hathaway, Eddie Redmayne, Sacha Baron Cohen', 'William Nicholson', 'History, Drama', 2012, 'Universal Pictures, Working Title Films, Cameron Mackintosh Ltd., Relativity Media, Working Title Films', '158', 3.6, 'GB, US', 'English', 'https://image.tmdb.org/t/p/w500/6CuzBs2Lb8At7qQr64mLXg2RYRb.jpg', 'An adaptation of the successful stage musical based on Victor Hugo\'s classic novel set in 19th-century France. Jean Valjean, a man imprisoned for stealing bread, must flee a relentless policeman named Javert. The pursuit consumes both men\'s lives, and soon Valjean finds himself in the midst of the student revolutions in France.'),
(178, 254, 'King Kong', 'Peter Jackson', 'Naomi Watts, Adrien Brody, Jack Black, Andy Serkis, Colin Hanks, Thomas Kretschmann', 'Peter Jackson', 'Adventure, Drama, Action', 2005, 'Universal Pictures, WingNut Films, Big Primate Pictures, MFPV Film', '188', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg', 'In 1933 New York, an overly ambitious movie producer coerces his cast and hired ship crew to travel to mysterious Skull Island, where they encounter Kong, a giant ape who is immediately smitten with the leading lady.'),
(179, 453395, 'Doctor Strange in the Multiverse of Madness', 'Sam Raimi', 'Benedict Cumberbatch, Xochitl Gomez, Elizabeth Olsen, Chiwetel Ejiofor, Benedict Wong, Rachel McAdams', 'Sam Raimi', 'Fantasy, Action, Adventure', 2022, 'Marvel Studios, Kevin Feige Productions', '126', 3.6, 'US', '广州话 / 廣州話, English, Español', 'https://image.tmdb.org/t/p/w500/ddJcSKbcp4rKZTmuyWaMhuwcfMz.jpg', 'Doctor Strange, with the help of mystical allies both old and new, traverses the mind-bending and dangerous alternate realities of the Multiverse to confront a mysterious new adversary.'),
(180, 40264, 'Vampires Suck', 'Jason Friedberg', 'Jenn Proske, Matt Lanter, Chris Riggi, Diedrich Bader, Anneliese Van Der Pol, Ken Jeong', 'Aaron Seltzer, Jason Friedberg', 'Comedy, Fantasy', 2010, 'Road Rebel, Regency Enterprises, 20th Century Fox, Dune Entertainment, 3 in the Box', '82', 2.2, 'US', 'English, Deutsch', 'https://image.tmdb.org/t/p/w500/ksPKfoXovAiFnBktkCBefsRQ8a1.jpg', 'Becca, an anxious, non-vampire teen is torn between two boys. Before she can choose, Becca must get around her controlling father, who treats her like a child. Meanwhile, Becca\'s friends contend with their own romantic issues – all of which collide at the prom.'),
(181, 568124, 'Encanto', 'Byron Howard', 'Stephanie Beatriz, María Cecilia Botero, John Leguizamo, Diane Guerrero, Jess Darrow, Carolina Gaitán', 'Charise Castro Smith, Jared Bush', 'Animation, Comedy, Family, Fantasy', 2021, 'Walt Disney Animation Studios', '102', 3.8, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/4j0PNHkMr5ax3IA8tjtxcmPU3QT.jpg', 'The tale of an extraordinary family, the Madrigals, who live hidden in the mountains of Colombia, in a magical house, in a vibrant town, in a wondrous, charmed place called an Encanto. The magic of the Encanto has blessed every child in the family—every child except one, Mirabel. But when she discovers that the magic surrounding the Encanto is in danger, Mirabel decides that she, the only ordinary Madrigal, might just be her exceptional family\'s last hope.'),
(182, 810, 'Shrek the Third', 'Chris Miller', 'Mike Myers, Eddie Murphy, Cameron Diaz, Antonio Banderas, Julie Andrews, John Cleese', 'Peter S. Seaman, Jeffrey Price, Chris Miller', 'Fantasy, Adventure, Animation, Comedy, Family', 2007, 'DreamWorks Animation, Pacific Data Images', '93', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/n4SexGGQzI26E269tfpa80MZaGV.jpg', 'After the King of Far Far Away dies, Shrek and Fiona are to succede. However, Shrek wants to return to his cozy swamp and live in peace and quiet, so when he finds out there is another heir to the throne, he and Donkey set off to bring him back to rule the kingdom.'),
(183, 780609, 'Men', 'Alex Garland', 'Jessie Buckley, Rory Kinnear, Paapa Essiedu, Gayle Rankin, Sarah Twomey, Zak Rothera-Oxley', 'Alex Garland', 'Horror, Thriller, Fantasy', 2022, 'A24, DNA Films', '100', 3.0, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/jo1Kv3P3UgDVk7JnUFr2Cl8WWUM.jpg', 'In the aftermath of a personal tragedy, Harper retreats alone to the beautiful English countryside, hoping to find a place to heal. But someone — or something — from the surrounding woods appears to be stalking her, and what begins as simmering dread becomes a fully-formed nightmare, inhabited by her darkest memories and fears.'),
(184, 537116, 'tick, tick... BOOM!', 'Lin-Manuel Miranda', 'Andrew Garfield, Alexandra Shipp, Robin de Jesús, Michaela Jaé Rodriguez, Ben Levi Ross, Jonathan Marc Sherman', 'Steven Levenson', 'Drama, Music', 2021, 'Imagine Entertainment, 5000 Broadway Productions', '120', 3.8, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/DPmfcuR8fh8ROYXgdjrAjSGA0o.jpg', 'On the brink of turning 30, a promising theater composer navigates love, friendship and the pressure to create something great before time runs out.'),
(185, 718789, 'Lightyear', 'Angus MacLane', 'Chris Evans, Keke Palmer, Peter Sohn, Taika Waititi, Dale Soules, James Brolin', 'Jason Headley, Angus MacLane', 'Animation, Science Fiction, Family, Adventure', 2022, 'Pixar', '105', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/ox4goZd956BxqJH6iLwhWPL9ct4.jpg', 'Legendary Space Ranger Buzz Lightyear embarks on an intergalactic adventure alongside a group of ambitious recruits and his robot companion Sox.'),
(186, 527774, 'Raya and the Last Dragon', 'Carlos López Estrada', 'Kelly Marie Tran, Awkwafina, Gemma Chan, Alan Tudyk, Izaac Wang, Benedict Wong', 'Adele Lim, Qui Nguyen', 'Animation, Action, Adventure, Fantasy, Family', 2021, 'Walt Disney Animation Studios', '107', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/5nVhgCzxKbK47OLIKxCR1syulOn.jpg', 'Long ago, in the fantasy world of Kumandra, humans and dragons lived together in harmony. But when an evil force threatened the land, the dragons sacrificed themselves to save humanity. Now, 500 years later, that same evil has returned and it’s up to a lone warrior, Raya, to track down the legendary last dragon to restore the fractured land and its divided people.'),
(187, 508439, 'Onward', 'Dan Scanlon', 'Tom Holland, Chris Pratt, Julia Louis-Dreyfus, Octavia Spencer, Mel Rodriguez, Kyle Bornheimer', 'Dan Scanlon, Jason Headley, Keith Bunin', 'Adventure, Animation, Comedy, Family, Fantasy', 2020, 'Walt Disney Pictures, Pixar', '102', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/f4aul3FyD3jv3v4bul1IrkWZvzq.jpg', 'In a suburban fantasy world, two teenage elf brothers embark on an extraordinary quest to discover if there is still a little magic left out there.'),
(188, 520763, 'A Quiet Place Part II', 'John Krasinski', 'Emily Blunt, John Krasinski, Millicent Simmonds, Noah Jupe, Cillian Murphy, Djimon Hounsou', 'John Krasinski', 'Science Fiction, Thriller, Horror', 2021, 'Paramount Pictures, Platinum Dunes, Sunday Night Productions', '97', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/4q2hz2m8hubgvijz8Ez0T2Os2Yv.jpg', 'Following the events at home, the Abbott family now face the terrors of the outside world. Forced to venture into the unknown, they realize that the creatures that hunt by sound are not the only threats that lurk beyond the sand path.'),
(189, 607, 'Men in Black', 'Barry Sonnenfeld', 'Tommy Lee Jones, Will Smith, Linda Fiorentino, Vincent D\'Onofrio, Rip Torn, Tony Shalhoub', 'Ed Solomon', 'Action, Adventure, Comedy, Science Fiction', 1997, 'Columbia Pictures, Amblin Entertainment, Parkes+MacDonald Production', '98', 3.6, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg', 'After a police chase with an otherworldly being, a New York City cop is recruited as an agent in a top-secret organization established to monitor and police alien activity on Earth: the Men in Black. Agent K and new recruit Agent J find themselves in the middle of a deadly plot by an intergalactic terrorist who has arrived on Earth to assassinate two ambassadors from opposing galaxies.'),
(190, 376867, 'Moonlight', 'Barry Jenkins', 'Trevante Rhodes, André Holland, Janelle Monáe, Ashton Sanders, Jharrel Jerome, Alex R. Hibbert', 'Barry Jenkins', 'Drama', 2016, 'A24, Plan B Entertainment, PASTEL', '111', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/qLnfEmPrDjJfPyyddLJPkXmshkp.jpg', 'The tender, heartbreaking story of a young man’s struggle to find himself, told across three defining chapters in his life as he experiences the ecstasy, pain, and beauty of falling in love, while grappling with his own sexuality.'),
(191, 557, 'Spider-Man', 'Sam Raimi', 'Tobey Maguire, Willem Dafoe, Kirsten Dunst, James Franco, Cliff Robertson, Rosemary Harris', 'David Koepp', 'Action, Science Fiction', 2002, 'Marvel Enterprises, Laura Ziskin Productions, Columbia Pictures', '121', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/nXdAh5vUwERL4WGVMaee8RoDEAS.jpg', 'After being bitten by a genetically altered spider at Oscorp, nerdy but endearing high school student Peter Parker is endowed with amazing powers to become the superhero known as Spider-Man.'),
(192, 508947, 'Turning Red', 'Domee Shi', 'Rosalie Chiang, Sandra Oh, Ava Morse, Hyein Park, Maitreyi Ramakrishnan, Orion Lee', 'Julia Cho, Domee Shi', 'Animation, Family, Comedy, Fantasy', 2022, 'Pixar', '100', 3.7, 'US', '广州话 / 廣州話, 普通话, 한국어/조선말, Français, English', 'https://image.tmdb.org/t/p/w500/qsdjk9oAKSQMWs0Vt5Pyfh6O4GZ.jpg', 'Thirteen-year-old Mei is experiencing the awkwardness of being a teenager with a twist – when she gets too excited, she transforms into a giant red panda.'),
(193, 1894, 'Star Wars: Episode II - Attack of the Clones', 'George Lucas', 'Hayden Christensen, Ewan McGregor, Natalie Portman, Christopher Lee, Samuel L. Jackson, Frank Oz', 'Jonathan Hales, George Lucas', 'Adventure, Action, Science Fiction', 2002, 'Lucasfilm Ltd.', '142', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/oZNPzxqM2s5DyVWab09NTQScDQt.jpg', 'Following an assassination attempt on Senator Padmé Amidala, Jedi Knights Anakin Skywalker and Obi-Wan Kenobi investigate a mysterious plot into the heart of the Separatist movement and the beginning of the Clone Wars.'),
(194, 581734, 'Nomadland', 'Chloé Zhao', 'Frances McDormand, David Strathairn, Linda May, Swankie, Gay DeForest, Patricia Grier', 'Chloé Zhao', 'Drama', 2021, 'Cor Cordium Productions, Hear/Say Productions, Highwayman Films', '108', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8Vc5EOUEIF1EUXuX9eLFf7BvN3P.jpg', 'A woman in her sixties embarks on a journey through the western United States after losing everything in the Great Recession, living as a van-dwelling modern-day nomad.'),
(195, 1734, 'The Mummy Returns', 'Stephen Sommers', 'Brendan Fraser, Rachel Weisz, John Hannah, Oded Fehr, Arnold Vosloo, Patricia Velásquez', 'Stephen Sommers', 'Adventure, Action, Fantasy', 2001, 'Universal Pictures, Alphaville Films, Imhotep Productions', '130', 3.2, 'US', 'English, العربية', 'https://image.tmdb.org/t/p/w500/kdJsW7hcy1lrj7tdMPycTAQPAiR.jpg', 'Rick and Evelyn O’Connell, along with their 8-year-old son Alex, discover the key to the legendary Scorpion King’s might: the fabled Bracelet of Anubis. Unfortunately, a newly resurrected Imhotep has designs on the bracelet as well, and isn’t above kidnapping its new bearer, Alex, to gain control of Anubis’s otherworldly army.'),
(196, 181808, 'Star Wars: The Last Jedi', 'Rian Johnson', 'Mark Hamill, Carrie Fisher, Adam Driver, Daisy Ridley, John Boyega, Oscar Isaac', 'Rian Johnson', 'Adventure, Action, Science Fiction', 2017, 'Lucasfilm Ltd.', '152', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg', 'Rey develops her newly discovered abilities with the guidance of Luke Skywalker, who is unsettled by the strength of her powers. Meanwhile, the Resistance prepares to do battle with the First Order.'),
(197, 330459, 'Rogue One: A Star Wars Story', 'Gareth Edwards', 'Felicity Jones, Diego Luna, Alan Tudyk, Donnie Yen, Jiang Wen, Ben Mendelsohn', 'Chris Weitz, Tony Gilroy', 'Action, Adventure, Science Fiction', 2016, 'Lucasfilm Ltd.', '133', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/i0yw1mFbB7sNGHCs7EXZPzFkdA1.jpg', 'A rogue band of resistance fighters unite for a mission to steal the Death Star plans and bring a new hope to the galaxy.'),
(198, 1891, 'The Empire Strikes Back', 'Irvin Kershner', 'Mark Hamill, Harrison Ford, Carrie Fisher, Billy Dee Williams, Anthony Daniels, David Prowse', 'Lawrence Kasdan, Leigh Brackett', 'Adventure, Action, Science Fiction', 1980, 'Lucasfilm Ltd.', '124', 4.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', 'The epic saga continues as Luke Skywalker, in hopes of defeating the evil Galactic Empire, learns the ways of the Jedi from aging master Yoda. But Darth Vader is more determined than ever to capture Luke. Meanwhile, rebel leader Princess Leia, cocky Han Solo, Chewbacca, and droids C-3PO and R2-D2 are thrown into various stages of capture, betrayal and despair.'),
(199, 282035, 'The Mummy', 'Alex Kurtzman', 'Tom Cruise, Annabelle Wallis, Sofia Boutella, Jake Johnson, Courtney B. Vance, Russell Crowe', 'David Koepp, Christopher McQuarrie, Dylan Kussman', 'Fantasy, Thriller, Action, Adventure, Horror', 2017, 'Secret Hideout, Universal Pictures, Conspiracy Factory, Sean Daniel Company', '110', 2.8, 'US', 'English, العربية', 'https://image.tmdb.org/t/p/w500/zxkY8byBnCsXodEYpK8tmwEGXBI.jpg', 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient queen whose destiny was unjustly taken from her is awakened in our current day, bringing with her malevolence grown over millennia, and terrors that defy human comprehension.'),
(200, 324857, 'Spider-Man: Into the Spider-Verse', 'Bob Persichetti', 'Shameik Moore, Jake Johnson, Hailee Steinfeld, Mahershala Ali, Brian Tyree Henry, Lily Tomlin', 'Phil Lord, Rodney Rothman', 'Animation, Action, Adventure, Science Fiction', 2018, 'Columbia Pictures, Lord Miller, Pascal Pictures, Sony Pictures Animation, Arad Productions, Marvel Entertainment', '117', 4.2, 'US', 'English, 日本語, Español', 'https://image.tmdb.org/t/p/w500/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson \"Kingpin\" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.'),
(201, 82690, 'Wreck-It Ralph', 'Rich Moore', 'John C. Reilly, Sarah Silverman, Jack McBrayer, Jane Lynch, Alan Tudyk, Rich Moore', 'Jennifer Lee, Phil Johnston', 'Family, Animation, Comedy, Adventure', 2012, 'Walt Disney Animation Studios', '101', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/nrEupcBwf4O1zihCM34NoXusZDq.jpg', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game\'s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero\'s Duty, a first-person shooter where he helps the game\'s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.'),
(202, 2062, 'Ratatouille', 'Brad Bird', 'Patton Oswalt, Ian Holm, Lou Romano, Brian Dennehy, Peter Sohn, Peter O\'Toole', 'Brad Bird', 'Animation, Comedy, Family, Fantasy', 2007, 'Pixar', '111', 3.9, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg', 'Remy, a rat, possesses a palate far more refined than that of his fellow comrades. He aspires to become a chef, one who creates rather than scavenges. When fate leads him beneath one of Paris\'s finest restaurants, he forms an unusual alliance with a young kitchen worker to pursue his culinary ambitions. As his double life unfolds, Remy must navigate the suspicions of the calculating Head Chef Skinner, the disapproval of Remy’s own colony, and the foreboding presence of renowned food critic Anton Ego, whose judgment can make or break a chef\'s legacy.'),
(203, 619730, 'Don\'t Worry Darling', 'Olivia Wilde', 'Florence Pugh, Harry Styles, Chris Pine, Olivia Wilde, KiKi Layne, Gemma Chan', 'Katie Silberman', 'Thriller, Science Fiction, Horror', 2022, 'Vertigo Entertainment, New Line Cinema', '123', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/jOqxKIOC92BVyinYO1Fm73XY7Tc.jpg', 'Alice and Jack are lucky to be living in the idealized community of Victory, the experimental company town housing the men who work for the top-secret Victory Project and their families. But when cracks in their idyllic life begin to appear, exposing flashes of something much more sinister lurking beneath the attractive façade, Alice can’t help questioning exactly what they’re doing in Victory, and why.'),
(204, 1892, 'Return of the Jedi', 'Richard Marquand', 'Mark Hamill, Harrison Ford, Carrie Fisher, Billy Dee Williams, Anthony Daniels, Peter Mayhew', 'Lawrence Kasdan, George Lucas', 'Adventure, Action, Science Fiction', 1983, 'Lucasfilm Ltd.', '132', 4.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/jQYlydvHm3kUix1f8prMucrplhm.jpg', 'Luke Skywalker leads a mission to rescue his friend Han Solo from the clutches of Jabba the Hutt, the Emperor prepares to crush the Rebellion with a more powerful Death Star, and the Rebel fleet mounts a massive attack on the space station. Luke Skywalker confronts Darth Vader in a final climactic duel before the evil Emperor.'),
(205, 120, 'The Lord of the Rings: The Fellowship of the Ring', 'Peter Jackson', 'Elijah Wood, Ian McKellen, Viggo Mortensen, Sean Astin, Ian Holm, Liv Tyler', 'Fran Walsh, Philippa Boyens, Peter Jackson', 'Adventure, Fantasy, Action', 2001, 'New Line Cinema, WingNut Films, The Saul Zaentz Company', '179', 4.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.'),
(206, 458737, 'First Reformed', 'Paul Schrader', 'Ethan Hawke, Amanda Seyfried, Cedric the Entertainer, Victoria Hill, Philip Ettinger, Michael Gaston', 'Paul Schrader', 'Drama', 2018, 'Arclight Films, Omeira Studio Partners, Killer Films, Fibonacci Films, Big Indie Pictures', '113', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8HKA3Hwf8jQWy8TCYWr7C8Wft23.jpg', 'A pastor of a small church in upstate New York starts to spiral out of control after a soul-shaking encounter with an unstable environmental activist and his pregnant wife.'),
(207, 550, 'Fight Club', 'David Fincher', 'Edward Norton, Brad Pitt, Helena Bonham Carter, Meat Loaf, Jared Leto, Zach Grenier', 'Jim Uhls', 'Drama, Thriller', 1999, 'Fox 2000 Pictures, Regency Enterprises, Linson Entertainment, 20th Century Fox, Taurus Film', '139', 4.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/jSziioSwPVrOy9Yow3XhWIBDjq1.jpg', 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground \"fight clubs\" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.'),
(208, 122, 'The Lord of the Rings: The Return of the King', 'Peter Jackson', 'Elijah Wood, Ian McKellen, Viggo Mortensen, Sean Astin, Andy Serkis, Dominic Monaghan', 'Peter Jackson, Fran Walsh, Philippa Boyens', 'Adventure, Fantasy, Action', 2003, 'New Line Cinema, WingNut Films, The Saul Zaentz Company', '201', 4.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', 'As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.​'),
(209, 121, 'The Lord of the Rings: The Two Towers', 'Peter Jackson', 'Elijah Wood, Ian McKellen, Viggo Mortensen, Sean Astin, Andy Serkis, John Rhys-Davies', 'Stephen Sinclair, Philippa Boyens, Peter Jackson', 'Adventure, Fantasy, Action', 2002, 'New Line Cinema, WingNut Films, The Saul Zaentz Company', '179', 4.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', 'Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers--Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron\'s fortress at Barad-dur, deep within the dark lands of Mordor. Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin. All along, nefarious wizard Saruman awaits the Fellowship members at the Orthanc Tower in Isengard.'),
(210, 273481, 'Sicario', 'Denis Villeneuve', 'Emily Blunt, Benicio del Toro, Josh Brolin, Victor Garber, Jon Bernthal, Daniel Kaluuya', 'Denis Villeneuve', 'Action, Crime, Thriller', 2015, 'Lionsgate, Black Label Media, Thunder Road', '122', 3.7, 'US', 'Español, English', 'https://image.tmdb.org/t/p/w500/lz8vNyXeidqqOdJW9ZjnDAMb5Vr.jpg', 'An idealistic FBI agent is enlisted by a government task force to aid in the escalating war against drugs at the border area between the U.S. and Mexico.'),
(211, 556678, 'Emma.', 'Autumn de Wilde', 'Anya Taylor-Joy, Johnny Flynn, Josh O\'Connor, Callum Turner, Mia Goth, Miranda Hart', 'Eleanor Catton', 'Comedy, Romance, Drama', 2020, 'Working Title Films, Blueprint Pictures', '125', 3.5, 'US, GB', 'English', 'https://image.tmdb.org/t/p/w500/uHpHzbHLSsVmAuuGuQSpyVDZmDc.jpg', 'In 1800s England, a well-meaning but selfish young woman meddles in the love lives of her friends.'),
(212, 556694, 'Three Thousand Years of Longing', 'George Miller', 'Tilda Swinton, Idris Elba, Erdil Yaşaroğlu, Sabrina Elba, Sarah Houbolt, Seyithan Özdemir', 'George Miller', 'Drama, Fantasy, Romance', 2022, 'FilmNation Entertainment, Elevate Production Finance, Sunac Pictures, Kennedy Miller Mitchell', '108', 3.4, 'AU, US', 'Türkçe, Deutsch, ελληνικά, English', 'https://image.tmdb.org/t/p/w500/nS7DNl4A7XnDncZX70UJ8ALAihF.jpg', 'A solitary scholar discovers an ancient bottle while on a trip to Istanbul and unleashes a djinn who offers her three wishes. Filled with reluctance, she is unable to come up with one, so the djinn tries to inspire her with his stories.'),
(214, 632617, 'C\'mon C\'mon', 'Mike Mills', 'Joaquin Phoenix, Gaby Hoffmann, Woody Norman, Scoot McNairy, Molly Webster, Jaboukie Young-White', 'Mike Mills', 'Drama', 2021, 'A24, Be Funny When You Can', '110', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/1oOyJsdcJnnE7cl9bZdUQvBjKNH.jpg', 'Johnny and his young nephew forge a tenuous but transformational relationship when they embark on a cross-country trip to see life away from Los Angeles.'),
(215, 790867, 'The Eternal Daughter', 'Joanna Hogg', 'Tilda Swinton, Joseph Mydell, Carly-Sophia Davies, Louis, Crispin Buxton, August Joshi', 'Joanna Hogg', 'Drama, Mystery', 2022, 'BBC Film, JWH Films, Element Pictures', '96', 3.0, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/kyv8tPXx3mKchYzVmA3VckKoJDi.jpg', 'An artist and her elderly mother confront long-buried secrets when they return to a former family home, now a hotel haunted by its mysterious past.'),
(216, 823766, 'The Wonder', 'Sebastián Lelio', 'Florence Pugh, Kíla Lord Cassidy, Tom Burke, Niamh Algar, Elaine Cassidy, Ruth Bradley', 'Sebastián Lelio', 'Drama, Mystery', 2022, 'Element Pictures, House Productions, Fís Éireann/Screen Ireland', '108', 3.3, 'IE, US, GB', 'English', 'https://image.tmdb.org/t/p/w500/wZvZgA7IkDX78UilzqBGh0QTQvC.jpg', 'Haunted by her past, a nurse travels from England to a remote Irish village in 1862 to investigate a young girl\'s supposedly miraculous fast.'),
(217, 505642, 'Black Panther: Wakanda Forever', 'Ryan Coogler', 'Letitia Wright, Tenoch Huerta Mejía, Lupita Nyong\'o, Danai Gurira, Winston Duke, Angela Bassett', 'Joe Robert Cole, Ryan Coogler', 'Action, Adventure, Science Fiction', 2022, 'Marvel Studios', '162', 3.5, 'US', 'English, Français, , Español, ', 'https://image.tmdb.org/t/p/w500/sv1xJUazXeYqALzczSZ3O6nkH75.jpg', 'Queen Ramonda, Shuri, M’Baku, Okoye and the Dora Milaje fight to protect their nation from intervening world powers in the wake of King T’Challa’s death.  As the Wakandans strive to embrace their next chapter, the heroes must band together with the help of War Dog Nakia and Everett Ross and forge a new path for the kingdom of Wakanda.'),
(218, 877269, 'Strange World', 'Don Hall', 'Jake Gyllenhaal, Dennis Quaid, Jaboukie Young-White, Gabrielle Union, Lucy Liu, Alan Tudyk', 'Qui Nguyen', 'Animation, Family, Adventure, Fantasy, Science Fiction', 2022, 'Walt Disney Animation Studios', '102', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/a9x70QUXs6uEwtin1SGNKoFXoia.jpg', 'A journey deep into an uncharted and treacherous land, where fantastical creatures await the legendary Clades—a family of explorers whose differences threaten to topple their latest, and by far most crucial, mission.'),
(219, 670, 'Oldboy', 'Park Chan-wook', 'Choi Min-sik, Yoo Ji-tae, Kang Hye-jung, Kim Byeong-ok, Ji Dae-han, Oh Dal-su', 'Hwang Jo-yoon, Lim Joon-hyung, Park Chan-wook', 'Thriller, Mystery', 2003, 'Show East, Egg Film, Cineclick Asia', '120', 4.1, 'KR', '한국어/조선말', 'https://image.tmdb.org/t/p/w500/pWDtjs568ZfOTMbURQBYuT4Qxka.jpg', 'With no clue how he came to be imprisoned, drugged and tortured for 15 years, a desperate man seeks revenge on his captors.'),
(220, 489925, 'Eighth Grade', 'Bo Burnham', 'Elsie Fisher, Josh Hamilton, Emily Robinson, Jake Ryan, Daniel Zolghadri, Fred Hechinger', 'Bo Burnham', 'Comedy, Drama', 2018, 'A24, Scott Rudin Productions, IAC Films', '94', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/xTa9cLhGHfQ7084UvoPQ2bBXKqd.jpg', 'Thirteen-year-old Kayla endures the tidal wave of contemporary suburban adolescence as she makes her way through the last week of middle school — the end of her thus far disastrous eighth grade year — before she begins high school.'),
(221, 383498, 'Deadpool 2', 'David Leitch', 'Ryan Reynolds, Josh Brolin, Morena Baccarin, Julian Dennison, Zazie Beetz, T.J. Miller', 'David Leitch', 'Action, Comedy, Adventure', 2018, 'Maximum Effort, Genre Films, 20th Century Fox, Marvel Entertainment', '120', 3.7, 'US', '广州话 / 廣州話, English, Pусский, Español', 'https://image.tmdb.org/t/p/w500/to0spRl1CMDvyUbOnbb4fTk3VAd.jpg', 'Wisecracking mercenary Deadpool battles the evil and powerful Cable and other bad guys to save a boy\'s life.'),
(222, 118340, 'Guardians of the Galaxy', 'James Gunn', 'Chris Pratt, Zoe Saldaña, Dave Bautista, Vin Diesel, Bradley Cooper, Lee Pace', 'James Gunn', 'Action, Science Fiction, Adventure', 2014, 'Marvel Studios', '121', 4.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg', 'Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.'),
(223, 299536, 'Avengers: Infinity War', 'Joe Russo', 'Robert Downey Jr., Chris Evans, Chris Hemsworth, Josh Brolin, Mark Ruffalo, Scarlett Johansson', 'Stephen McFeely, Christopher Markus', 'Adventure, Action, Science Fiction', 2018, 'Marvel Studios', '149', 4.1, 'US', 'English, ', 'https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment - the fate of Earth and existence itself has never been more uncertain.'),
(224, 58, 'Pirates of the Caribbean: Dead Man\'s Chest', 'Gore Verbinski', 'Johnny Depp, Orlando Bloom, Keira Knightley, Jack Davenport, Bill Nighy, Jonathan Pryce', 'Ted Elliott, Terry Rossio', 'Adventure, Fantasy, Action', 2006, 'Walt Disney Pictures, Jerry Bruckheimer Films, Second Mate Productions', '151', 3.7, 'US', 'English, Türkçe, ελληνικά, 普通话', 'https://image.tmdb.org/t/p/w500/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg', 'Captain Jack Sparrow’s got a blood debt to pay: he owes his soul to the legendary Davy Jones, ghastly Ruler of the Ocean Depths. To escape eternal servitude aboard the Flying Dutchman, ever-crafty Jack must track down the still-beating heart of Jones. But he won’t do it alone: Will Turner and Elizabeth Swann are drawn back into another one of his perilous quests—assuming they can evade execution for aiding a pirate.'),
(225, 194662, 'Birdman or (The Unexpected Virtue of Ignorance)', 'Alejandro G. Iñárritu', 'Michael Keaton, Emma Stone, Zach Galifianakis, Edward Norton, Andrea Riseborough, Naomi Watts', 'Alejandro G. Iñárritu', 'Drama, Comedy', 2014, 'TSG Entertainment, Worldview Entertainment, New Regency Pictures, M Productions, Le Grisbi Productions', '120', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/rHUg2AuIuLSIYMYFgavVwqt1jtc.jpg', 'A fading actor best known for his portrayal of a popular superhero attempts to mount a comeback by appearing in a Broadway play. As opening night approaches, his attempts to become more altruistic, rebuild his career, and reconnect with friends and family prove more difficult than expected.'),
(226, 61791, 'Rise of the Planet of the Apes', 'Rupert Wyatt', 'Andy Serkis, James Franco, Freida Pinto, John Lithgow, Brian Cox, Tom Felton', 'Rick Jaffa, Amanda Silver', 'Thriller, Action, Drama, Science Fiction', 2011, 'Dune Entertainment, Chernin Entertainment, Ingenious Media, Big Screen Productions, 20th Century Fox', '105', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/oqA45qMyyo1TtrnVEBKxqmTPhbN.jpg', 'A highly intelligent chimpanzee named Caesar has been living a peaceful suburban life ever since he was born. But when he gets taken to a cruel primate facility, Caesar decides to revolt against those who have harmed him.');
INSERT INTO `peliculas` (`idPelicula`, `idApi`, `nombrePelicula`, `directorPelicula`, `actorPelicula`, `guionistaPelicula`, `generoPelicula`, `anoPelicula`, `companiaPelicula`, `duracionPelicula`, `ratingAvgPelicula`, `paisPelicula`, `idiomaPelicula`, `posterPelicula`, `sinopsisPelicula`) VALUES
(227, 546554, 'Knives Out', 'Rian Johnson', 'Daniel Craig, Chris Evans, Ana de Armas, Jamie Lee Curtis, Michael Shannon, Don Johnson', 'Rian Johnson', 'Comedy, Crime, Mystery', 2019, 'MRC, T-Street', '131', 3.9, 'US', 'Español, English', 'https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg', 'When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan\'s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan\'s untimely death.'),
(228, 603, 'The Matrix', 'Lana Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving, Gloria Foster, Joe Pantoliano', 'Lana Wachowski, Lilly Wachowski', 'Action, Science Fiction', 1999, 'Village Roadshow Pictures, Groucho II Film Partnership, Silver Pictures, Warner Bros. Pictures', '136', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.'),
(229, 949423, 'Pearl', 'Ti West', 'Mia Goth, David Corenswet, Tandi Wright, Matthew Sunderland, Emma Jenkins-Purro, Alistair Sewell', 'Ti West', 'Horror', 2022, 'A24, Little Lamb Productions', '102', 3.6, 'US', 'English, Deutsch', 'https://image.tmdb.org/t/p/w500/z5uIG81pXyHKg7cUFIu84Wjn4NS.jpg', 'Trapped on her family’s isolated farm, Pearl must tend to her ailing father under the bitter and overbearing watch of her devout mother. Lusting for a glamorous life like she’s seen in the movies, Pearl’s ambitions, temptations, and repressions collide.'),
(230, 264644, 'Room', 'Lenny Abrahamson', 'Brie Larson, Jacob Tremblay, Joan Allen, Sean Bridgers, Tom McCamus, William H. Macy', 'Emma Donoghue', 'Drama, Thriller', 2015, 'Téléfilm Canada, Element Pictures, FilmNation Entertainment, No Trace Camping, Film4 Productions, Fís Éireann/Screen Ireland', '118', 4.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/2hHDMeYyZjbGWn0BeNH1cTMxuM7.jpg', 'Held captive for 7 years in an enclosed space, a woman and her young son finally gain their freedom, allowing the boy to experience the outside world for the first time.'),
(231, 44214, 'Black Swan', 'Darren Aronofsky', 'Natalie Portman, Mila Kunis, Vincent Cassel, Barbara Hershey, Winona Ryder, Benjamin Millepied', 'John J. McLaughlin, Mark Heyman, Andres Heinz', 'Drama, Thriller, Horror', 2010, 'Fox Searchlight Pictures, Cross Creek Pictures, Protozoa Pictures, Phoenix Pictures, Dune Entertainment', '108', 3.8, 'US', 'English, Français, Italiano', 'https://image.tmdb.org/t/p/w500/viWheBd44bouiLCHgNMvahLThqx.jpg', 'A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky\'s \"Swan Lake.\"'),
(232, 381283, 'mother!', 'Darren Aronofsky', 'Jennifer Lawrence, Javier Bardem, Ed Harris, Michelle Pfeiffer, Brian Gleeson, Domhnall Gleeson', 'Darren Aronofsky', 'Horror, Drama', 2017, 'Paramount Pictures, Protozoa Pictures', '121', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/fjny9chXPx69ln1LMJxbwi5yHMt.jpg', 'A couple\'s relationship is tested when uninvited guests arrive at their home, disrupting their tranquil existence.'),
(233, 530385, 'Midsommar', 'Ari Aster', 'Florence Pugh, Jack Reynor, William Jackson Harper, Will Poulter, Vilhelm Blomgren, Isabelle Grill', 'Ari Aster', 'Horror, Drama, Mystery', 2019, 'B-Reel Films, Square Peg', '147', 3.6, 'US', 'English, svenska', 'https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', 'Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.'),
(234, 1893, 'Star Wars: Episode I - The Phantom Menace', 'George Lucas', 'Liam Neeson, Ewan McGregor, Natalie Portman, Jake Lloyd, Ian McDiarmid, Pernilla August', 'George Lucas', 'Adventure, Action, Science Fiction', 1999, 'Lucasfilm Ltd.', '136', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6wkfovpn7Eq8dYNKaG5PY3q2oq6.jpg', 'Anakin Skywalker, a young slave strong with the Force, is discovered on Tatooine. Meanwhile, the evil Sith have returned, enacting their plot for revenge against the Jedi.'),
(235, 140607, 'Star Wars: The Force Awakens', 'J.J. Abrams', 'Daisy Ridley, John Boyega, Oscar Isaac, Adam Driver, Carrie Fisher, Harrison Ford', 'J.J. Abrams', 'Adventure, Action, Science Fiction', 2015, 'Lucasfilm Ltd., Bad Robot', '136', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/wqnLdwVXoBjKibFRR5U3y0aDUhs.jpg', 'Thirty years after defeating the Galactic Empire, Han Solo and his allies face a new threat from the evil Kylo Ren and his army of Stormtroopers.'),
(236, 508943, 'Luca', 'Enrico Casarosa', 'Jacob Tremblay, Jack Dylan Grazer, Emma Berman, Saverio Raimondo, Maya Rudolph, Marco Barricelli', 'Mike Jones, Jesse Andrews', 'Animation, Family, Fantasy, Drama, Comedy', 2021, 'Pixar', '95', 3.9, 'US', 'English, Italiano', 'https://image.tmdb.org/t/p/w500/9x4i9uKGXt8IiiIF5Ey0DIoY738.jpg', 'Luca and his best friend Alberto experience an unforgettable summer on the Italian Riviera. But all the fun is threatened by a deeply-held secret: they are sea monsters from another world just below the water’s surface.'),
(237, 497, 'The Green Mile', 'Frank Darabont', 'Tom Hanks, David Morse, Bonnie Hunt, Michael Clarke Duncan, James Cromwell, Michael Jeter', 'Frank Darabont', 'Fantasy, Drama, Crime', 1999, 'Castle Rock Entertainment, Darkwoods Productions', '189', 4.3, 'US', 'Français, English', 'https://image.tmdb.org/t/p/w500/8VG8fDNiy50H4FedGwdSVUPoaJe.jpg', 'A supernatural tale set on death row in a Southern prison, where gentle giant John Coffey possesses the mysterious power to heal people\'s ailments. When the cell block\'s head guard, Paul Edgecomb, recognizes Coffey\'s miraculous gift, he tries desperately to help stave off the condemned man\'s execution.'),
(238, 80, 'Before Sunset', 'Richard Linklater', 'Ethan Hawke, Julie Delpy, Vernon Dobtcheff, Louise Lemoine Torrès, Rodolphe Pauly, Mariane Plasteig', 'Ethan Hawke, Julie Delpy, Richard Linklater', 'Drama, Romance', 2004, 'Warner Independent Pictures, Castle Rock Entertainment, Detour Filmproduction', '80', 3.9, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/4sW5XH9ZfYXpvFzev00S1IGAEbg.jpg', 'Nine years later, Jesse travels across Europe giving readings from a book he wrote about the night he spent in Vienna with Celine. After his reading in Paris, Celine finds him, and they spend part of the day together before Jesse has to again leave for a flight. They are both in relationships now, and Jesse has a son, but as their strong feelings for each other start to return, both confess a longing for more.'),
(239, 132344, 'Before Midnight', 'Richard Linklater', 'Ethan Hawke, Julie Delpy, Seamus Davey-Fitzpatrick, Jennifer Prior, Charlotte Prior, Xenia Kalogeropoulou', 'Richard Linklater', 'Romance, Drama', 2013, 'Castle Rock Entertainment, Detour Filmproduction, Faliro House Productions, Venture Forth, IM Global', '109', 3.7, 'US', 'English, ελληνικά, Français', 'https://image.tmdb.org/t/p/w500/qbGKJmNUroDz75kh5Oafoall89e.jpg', 'It has been nine years since we last met Jesse and Celine, the French-American couple who once met on a train in Vienna. They now live in Paris with twin daughters but have spent a summer in Greece at the invitation of an author colleague of Jesse\'s. When the vacation is over and Jesse must send his teenage son off to the States, he begins to question his life decisions, and his relationship with Celine is at risk.'),
(240, 604, 'The Matrix Reloaded', 'Lilly Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving, Jada Pinkett Smith, Gloria Foster', 'Lana Wachowski, Lilly Wachowski', 'Adventure, Action, Thriller, Science Fiction', 2003, 'Village Roadshow Pictures, Silver Pictures, NPV Entertainment', '138', 3.5, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/aA5qHS0FbSXO8PxcxUIHbDrJyuh.jpg', 'The Resistance builds in numbers as humans are freed from the Matrix and brought to the city of Zion. Neo discovers his superpowers, including the ability to see the code inside the Matrix. With machine sentinels digging to Zion in 72 hours, Neo, Morpheus and Trinity must find the Keymaker to ultimately reach the Source.'),
(241, 316029, 'The Greatest Showman', 'Michael Gracey', 'Hugh Jackman, Zac Efron, Michelle Williams, Rebecca Ferguson, Zendaya, Keala Settle', 'Bill Condon, Jenny Bicks', 'Drama', 2017, 'Chernin Entertainment, 20th Century Fox, TSG Entertainment, Laurence Mark Productions', '105', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/b9CeobiihCx1uG1tpw8hXmpi7nm.jpg', 'The story of American showman P.T. Barnum, founder of the circus that became the famous traveling Ringling Bros. and Barnum & Bailey Circus.'),
(242, 772, 'Home Alone 2: Lost in New York', 'Chris Columbus', 'Macaulay Culkin, Joe Pesci, Daniel Stern, Catherine O\'Hara, John Heard, Brenda Fricker', 'John Hughes', 'Comedy, Family, Adventure', 1992, '20th Century Fox, Hughes Entertainment', '120', 3.4, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/uuitWHpJwxD1wruFl2nZHIb4UGN.jpg', 'Instead of flying to Florida with his folks, Kevin ends up alone in New York, where he gets a hotel room with his dad\'s credit card—despite problems from a clerk and meddling bellboy. But when Kevin runs into his old nemeses, the Wet Bandits, he\'s determined to foil their plans to rob a toy store on Christmas Eve.'),
(243, 278927, 'The Jungle Book', 'Jon Favreau', 'Neel Sethi, Bill Murray, Ben Kingsley, Idris Elba, Scarlett Johansson, Christopher Walken', 'Justin Marks', 'Adventure, Family, Fantasy', 2016, 'Walt Disney Pictures, Fairview Entertainment, Moving Picture Company', '106', 3.4, 'US, GB', 'English', 'https://image.tmdb.org/t/p/w500/2Epx7F9X7DrFptn4seqn4mzBVks.jpg', 'After a threat from the tiger Shere Khan, Mowgli, a man-cub fostered by wolves, is forced to flee the jungle, and he embarks on a journey of self-discovery with the help of the panther, Bagheera, and the free-spirited bear, Baloo.'),
(244, 11, 'Star Wars', 'George Lucas', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness, Anthony Daniels', 'George Lucas', 'Adventure, Action, Science Fiction', 1977, 'Lucasfilm Ltd.', '121', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', 'Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.'),
(245, 953, 'Madagascar', 'Eric Darnell', 'Ben Stiller, Chris Rock, David Schwimmer, Jada Pinkett Smith, Sacha Baron Cohen, Cedric the Entertainer', 'Eric Darnell, Tom McGrath', 'Adventure, Animation, Comedy, Family', 2005, 'Pacific Data Images, DreamWorks Animation', '86', 3.5, 'US', 'English, Français, Deutsch, Português, Español', 'https://image.tmdb.org/t/p/w500/zMpJY5CJKUufG9OTw0In4eAFqPX.jpg', 'Four animal friends get a taste of the wild life when they break out of captivity at the Central Park Zoo and wash ashore on the island of Madagascar.'),
(246, 661374, 'Glass Onion: A Knives Out Mystery', 'Rian Johnson', 'Daniel Craig, Edward Norton, Janelle Monáe, Kathryn Hahn, Leslie Odom Jr., Kate Hudson', 'Rian Johnson', 'Comedy, Crime, Mystery', 2022, 'T-Street', '140', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/vDGr1YdrlfbU9wxTOdpf3zChmv9.jpg', 'World-famous detective Benoit Blanc heads to Greece to peel back the layers of a mystery surrounding a tech billionaire and his eclectic crew of friends.'),
(247, 705996, 'Decision to Leave', 'Park Chan-wook', 'Tang Wei, Park Hae-il, Lee Jung-hyun, Go Kyung-pyo, Park Yong-woo, Kim Shin-young', 'Park Chan-wook', 'Thriller, Mystery, Romance', 2022, 'Moho Film, CJ ENM, CJ Entertainment', '139', 3.7, 'KR', '普通话, English, 한국어/조선말', 'https://image.tmdb.org/t/p/w500/zI8KZ4EdLUymWKX1YEkpZ0gtPUa.jpg', 'From a mountain peak in South Korea, a man plummets to his death. Did he jump, or was he pushed? When detective Hae-joon arrives on the scene, he begins to suspect the dead man’s wife Seo-rae. But as he digs deeper into the investigation, he finds himself trapped in a web of deception and desire.'),
(248, 12230, 'One Hundred and One Dalmatians', 'Wolfgang Reitherman', 'Rod Taylor, J. Pat O\'Malley, Betty Lou Gerson, Martha Wentworth, Ben Wright, Cate Bauer', 'Clyde Geronimi, Hamilton Luske', 'Adventure, Animation, Comedy, Family', 1961, 'Walt Disney Productions', '79', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/kSlYq6FrBUviGSEh8v4L9nrSnBT.jpg', 'When a litter of dalmatian puppies are abducted by the minions of Cruella De Vil, the parents must find them before she uses them for a diabolical fashion statement.'),
(249, 41154, 'Men in Black 3', 'Barry Sonnenfeld', 'Will Smith, Tommy Lee Jones, Josh Brolin, Jemaine Clement, Emma Thompson, Michael Stuhlbarg', 'Etan Cohen', 'Action, Comedy, Science Fiction', 2012, 'Columbia Pictures, Hemisphere Media Capital, Amblin Entertainment, Parkes+MacDonald Image Nation, Image Nation Abu Dhabi', '106', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/90DdoEStzeObs96fsYf4GG544iN.jpg', 'Agents J and K are back...in time. J has seen some inexplicable things in his 15 years with the Men in Black, but nothing, not even aliens, perplexes him as much as his wry, reticent partner. But when K\'s life and the fate of the planet are put at stake, Agent J will have to travel back in time to put things right. J discovers that there are secrets to the universe that K never told him - secrets that will reveal themselves as he teams up with the young Agent K to save his partner, the agency, and the future of humankind.'),
(250, 1593, 'Night at the Museum', 'Shawn Levy', 'Ben Stiller, Carla Gugino, Dick Van Dyke, Mickey Rooney, Bill Cobbs, Jake Cherry', 'Thomas Lennon, Robert Ben Garant', 'Fantasy, Family, Comedy', 2006, '1492 Pictures, 21 Laps Entertainment, 20th Century Fox, Ingenious Media, Sun Canada Productions', '108', 3.3, 'US', 'English, Italiano, עִבְרִית', 'https://image.tmdb.org/t/p/w500/pDsAAYf6Zn0yiAGJ6lYGs6hoZ4E.jpg', 'Chaos reigns at the natural history museum when night watchman Larry Daley accidentally stirs up an ancient curse, awakening Attila the Hun, an army of gladiators, a Tyrannosaurus rex and other exhibits.'),
(251, 685691, 'BARDO, False Chronicle of a Handful of Truths', 'Alejandro G. Iñárritu', 'Daniel Giménez Cacho, Griselda Siciliani, Íker Sánchez Solano, Ximena Lamadrid, Luz Jiménez, Luis Couturier', 'Alejandro G. Iñárritu', 'Comedy, Drama', 2022, 'M Productions, Redrum', '159', 3.4, 'MX', '', 'https://image.tmdb.org/t/p/w500/3e6RA0CzFDC0pz5TqiRlbHcsc2n.jpg', 'A renowned Mexican journalist and documentary filmmaker living in Los Angeles, after being named the recipient of a prestigious international award, is compelled to return to his native country, unaware that this simple trip will push him to an existential limit.'),
(252, 817758, 'TÁR', 'Todd Field', 'Cate Blanchett, Nina Hoss, Noémie Merlant, Sophie Kauer, Julian Glover, Mark Strong', 'Todd Field', 'Music, Drama', 2022, 'Focus Features, Standard Film Company, EMJAG Productions', '158', 3.5, 'US', 'Deutsch, Français, தமிழ், English, Português', 'https://image.tmdb.org/t/p/w500/dRVAlaU0vbG6hMf2K45NSiIyoUe.jpg', 'As celebrated conductor Lydia Tár starts rehearsals for a career-defining symphony, the consequences of her past choices begin to echo in the present.'),
