(533, 375262, 'The Favourite', 'Yorgos Lanthimos', 'Emma Stone, Olivia Colman, Rachel Weisz, Nicholas Hoult, Joe Alwyn, Mark Gatiss', 'Yorgos Lanthimos', 'History, Comedy, Drama', 2018, 'Waypoint Entertainment, Element Pictures, Scarlet Films, Film4 Productions, Fox Searchlight Pictures, Fís Éireann/Screen Ireland, TSG Entertainment', '120', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/cwBq0onfmeilU5xgqNNjJAMPfpw.jpg', 'England, early 18th century. The close relationship between Queen Anne and Sarah Churchill is threatened by the arrival of Sarah\'s cousin, Abigail Hill, resulting in a bitter rivalry between the two cousins to be the Queen\'s favourite.'),
(534, 122906, 'About Time', 'Richard Curtis', 'Domhnall Gleeson, Rachel McAdams, Bill Nighy, Tom Hollander, Margot Robbie, Lydia Wilson', 'Richard Curtis', 'Drama, Romance, Fantasy', 2013, 'Universal Pictures, Relativity Media, Working Title Films', '123', 4.0, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/ls6zswrOZVhCXQBh96DlbnLBajM.jpg', 'The night after another unsatisfactory New Year\'s party, Tim\'s father reveals to him that the men in their family have the ability to travel through time. They can\'t change history, but they can change what happens and has happened in their own lives. Thus begins the start of a lesson in learning to appreciate life itself as it is, as it comes, and most importantly, the people living alongside us.'),
(535, 614930, 'Teenage Mutant Ninja Turtles: Mutant Mayhem', 'Jeff Rowe', 'Micah Abbey, Shamon Brown Jr., Nicolas Cantu, Brady Noon, Ayo Edebiri, Maya Rudolph', 'Evan Goldberg, Benji Samit, Dan Hernandez', 'Animation, Comedy, Action, Science Fiction', 2023, 'Paramount Pictures, Nickelodeon Movies, Point Grey Pictures, Cinesite Animation, Mikros Animation', '100', 3.6, 'US', 'English, 普通话', 'https://image.tmdb.org/t/p/w500/gyh0eECE2IqrW8GWl3KoHBfc45j.jpg', 'After years of being sheltered from the human world, the Turtle brothers set out to win the hearts of New Yorkers and be accepted as normal teenagers through heroic acts. Their new friend April O\'Neil helps them take on a mysterious crime syndicate, but they soon get in over their heads when an army of mutants is unleashed upon them.'),
(536, 4935, 'Howl\'s Moving Castle', 'Hayao Miyazaki', 'Chieko Baisho, Takuya Kimura, Akihiro Miwa, Tatsuya Gashuin, Ryunosuke Kamiki, Mitsunori Isaki', 'Hayao Miyazaki', 'Fantasy, Animation, Adventure', 2004, 'Studio Ghibli, Tokuma Shoten, Nippon Television Network Corporation, dentsu, Walt Disney Japan, d-rights, TOHO', '119', 4.2, 'JP', '日本語', 'https://image.tmdb.org/t/p/w500/13kOl2v0nD2OLbVSHnHk8GUFEhO.jpg', 'Sophie, a young milliner, is turned into an elderly woman by a witch who enters her shop and curses her. She encounters a wizard named Howl and gets caught up in his resistance to fighting for the king.'),
(537, 399057, 'The Killing of a Sacred Deer', 'Yorgos Lanthimos', 'Colin Farrell, Nicole Kidman, Barry Keoghan, Raffey Cassidy, Sunny Suljic, Bill Camp', 'Yorgos Lanthimos', 'Drama, Thriller, Mystery', 2017, 'Element Pictures, TPC, Film4 Productions, New Sparta Films, Limp, HanWay Films, Fís Éireann/Screen Ireland', '121', 3.5, 'IE, US, GB', 'Français, English', 'https://image.tmdb.org/t/p/w500/e4DGlsc9g0h5AyoyvvAuIRnofN7.jpg', 'Dr. Steven Murphy is a renowned cardiovascular surgeon who presides over a spotless household with his wife and two children. Lurking at the margins of his idyllic suburban existence is Martin, a fatherless teen who insinuates himself into the doctor\'s life in gradually unsettling ways.'),
(538, 348, 'Alien', 'Ridley Scott', 'Tom Skerritt, Sigourney Weaver, Veronica Cartwright, Harry Dean Stanton, John Hurt, Ian Holm', 'Dan O\'Bannon', 'Horror, Science Fiction', 1979, 'Brandywine Productions, Twentieth Century-Fox Productions, Ronald Shusett Productions', '117', 4.1, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', 'During its return to the earth, commercial spaceship Nostromo intercepts a distress signal from a distant planet. When a three-member team of the crew discovers a chamber containing thousands of eggs on the planet, a creature inside one of the eggs attacks an explorer. The entire crew is unaware of the impending nightmare set to descend upon them when the alien parasite planted inside its unfortunate host is birthed.');
INSERT INTO `peliculas` (`idPelicula`, `idApi`, `nombrePelicula`, `directorPelicula`, `actorPelicula`, `guionistaPelicula`, `generoPelicula`, `anoPelicula`, `companiaPelicula`, `duracionPelicula`, `ratingAvgPelicula`, `paisPelicula`, `idiomaPelicula`, `posterPelicula`, `sinopsisPelicula`) VALUES
(539, 38810, 'Dogtooth', 'Yorgos Lanthimos', 'Christos Stergioglou, Michele Valley, Hristos Passalis, Angeliki Papoulia, Mary Tsoni, Anna Kalaitzidou', 'Yorgos Lanthimos, Efthimis Filippou', 'Drama', 2009, 'Greek Film Centre, Boo Productions, Horsefly Productions', '98', 3.5, 'GR', 'ελληνικά', 'https://image.tmdb.org/t/p/w500/cBrhzHcOxXclTItkPzsJUCTSFyl.jpg', 'Three teenagers are confined to an isolated country estate that could very well be on another planet. The trio spend their days listening to endless homemade tapes that teach them a whole new vocabulary. Any word that comes from beyond their family abode is instantly assigned a new meaning. Hence \'the sea\' refers to a large armchair and \'zombies\' are little yellow flowers. Having invented a brother whom they claim to have ostracized for his disobedience, the uber-controlling parents terrorize their offspring into submission.'),
(540, 419430, 'Get Out', 'Jordan Peele', 'Daniel Kaluuya, Allison Williams, Catherine Keener, Bradley Whitford, Caleb Landry Jones, Marcus Henderson', 'Jordan Peele', 'Mystery, Thriller, Horror', 2017, 'Monkeypaw Productions, Blumhouse Productions, QC Entertainment', '104', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/tFXcEccSQMf3lfhfXKSU9iRBpa3.jpg', 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family\'s overly accommodating behavior as nervous attempts to deal with their daughter\'s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.'),
(541, 814776, 'Bottoms', 'Emma Seligman', 'Rachel Sennott, Ayo Edebiri, Ruby Cruz, Havana Rose Liu, Kaia Gerber, Nicholas Galitzine', 'Emma Seligman', 'Comedy', 2023, 'Brownstone Productions, Orion Pictures', '91', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/jeyTQrNEpyE1LZIgVlswYh3sc34.jpg', 'Unpopular best friends PJ and Josie start a high school self-defense club to meet girls and lose their virginity. They soon find themselves in over their heads when the most popular students start beating each other up in the name of self-defense.'),
(542, 923939, 'The Wonderful Story of Henry Sugar', 'Wes Anderson', 'Ralph Fiennes, Benedict Cumberbatch, Dev Patel, Ben Kingsley, Richard Ayoade, Jarvis Cocker', 'Wes Anderson', 'Comedy, Fantasy, Adventure, Drama', 2023, 'American Empirical Pictures, Indian Paintbrush', '39', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/fDUywEHwHh6nsLnVXAdPN9m4ZUG.jpg', 'A rich man learns about a guru who can see without using his eyes. He sets out to master the skill in order to cheat at gambling.'),
(543, 1172674, 'The Rat Catcher', 'Wes Anderson', 'Richard Ayoade, Ralph Fiennes, Rupert Friend, Eliel Ford, Benoît Herlin, Till Sennhenn', 'Wes Anderson', 'Comedy', 2023, 'American Empirical Pictures, Indian Paintbrush', '17', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/29WJ7dOHt48AtXK1J1rONEEvIMN.jpg', 'In an English village, a reporter and a mechanic listen to a ratcatcher explain his clever plan to outwit his prey.'),
(545, 670292, 'The Creator', 'Gareth Edwards', 'John David Washington, Madeleine Yuna Voyles, Gemma Chan, Allison Janney, Ken Watanabe, Sturgill Simpson', 'Chris Weitz, Gareth Edwards', 'Science Fiction, Action, Adventure', 2023, 'New Regency Pictures, Entertainment One, Regency Enterprises, Bad Dreams', '134', 3.5, 'US', '日本語, English, ภาษาไทย, Tiếng Việt', 'https://image.tmdb.org/t/p/w500/3dSivDtOuyxLDxPH4v2tcNG1fP7.jpg', 'Amid a future war between the human race and the forces of artificial intelligence, a hardened ex-special forces agent grieving the disappearance of his wife, is recruited to hunt down and kill the Creator, the elusive architect of advanced AI who has developed a mysterious weapon with the power to end the war—and mankind itself.'),
(546, 640, 'Catch Me If You Can', 'Steven Spielberg', 'Leonardo DiCaprio, Tom Hanks, Christopher Walken, Martin Sheen, Nathalie Baye, Amy Adams', 'Jeff Nathanson', 'Drama, Crime', 2002, 'Kemp Company, Splendid Pictures, DreamWorks Pictures, Parkes+MacDonald Production', '141', 4.0, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/ctjEj2xM32OvBXCq8zAdK3ZrsAj.jpg', 'A true story about Frank Abagnale Jr. who, before his 19th birthday, successfully conned millions of dollars worth of checks as a Pan Am pilot, doctor, and legal prosecutor. An FBI agent makes it his mission to put him behind bars. But Frank not only eludes capture, he revels in the pursuit.'),
(547, 37799, 'The Social Network', 'David Fincher', 'Jesse Eisenberg, Andrew Garfield, Armie Hammer, Justin Timberlake, Rooney Mara, Max Minghella', 'Aaron Sorkin', 'Drama', 2010, 'Columbia Pictures, Relativity Media, Scott Rudin Productions, Michael De Luca Productions, Trigger Street Productions', '121', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/n0ybibhJtQ5icDqTp8eRytcIHJx.jpg', 'In 2003, Harvard undergrad and computer programmer Mark Zuckerberg begins work on a new concept that eventually turns into the global social network known as Facebook. Six years later, Mark is one of the youngest billionaires ever, but his unprecedented success leads to both personal and legal complications when he ends up on the receiving end of two lawsuits, one involving his former friend.'),
(548, 807, 'Se7en', 'David Fincher', 'Morgan Freeman, Brad Pitt, Gwyneth Paltrow, John Cassini, Peter Crombie, Reg E. Cathey', 'David Fincher', 'Crime, Mystery, Thriller', 1995, 'New Line Cinema, Juno Pix, Arnold Kopelson Productions', '127', 4.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', 'Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the \"seven deadly sins\" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer\'s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.'),
(549, 65754, 'The Girl with the Dragon Tattoo', 'David Fincher', 'Daniel Craig, Rooney Mara, Christopher Plummer, Stellan Skarsgård, Robin Wright, Yorick van Wageningen', 'Steven Zaillian', 'Thriller, Crime, Mystery', 2011, 'Columbia Pictures, Metro-Goldwyn-Mayer, Scott Rudin Productions, Yellow Bird', '158', 3.7, 'US', 'Français, English', 'https://image.tmdb.org/t/p/w500/8bokS83zGdhaXgN9tjidUKmAftW.jpg', 'Disgraced journalist Mikael Blomkvist investigates the disappearance of a weary patriarch\'s niece from 40 years ago. He is aided by the pierced, tattooed, punk computer hacker named Lisbeth Salander. As they work together in the investigation, Blomkvist and Salander uncover immense corruption beyond anything they have ever imagined.'),
(550, 7443, 'Chicken Run', 'Nick Park', 'Julia Sawalha, Mel Gibson, Imelda Staunton, Jane Horrocks, Lynn Ferguson, Miranda Richardson', 'Karey Kirkpatrick', 'Animation, Comedy, Family', 2000, 'Aardman, DreamWorks Animation, Pathé, DreamWorks Pictures', '84', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8XgmIsbpVamdhwcNVsYzohFZTtT.jpg', 'The creators of Wallace & Gromit bring you an exciting and original story about a group of chickens determined to fly the coop–even if they can’t fly! It’s hardly poultry in motion when Rocky attempts to teach Ginger and her feathered friends to fly…but, with teamwork, determination and a little bit o’ cluck, the fearless flock plots one last attempt in a spectacular bid for freedom.'),
(551, 220289, 'Coherence', 'James Ward Byrkit', 'Emily Baldoni, Maury Sterling, Nicholas Brendon, Lorene Scafaria, Elizabeth Gracen, Hugo Armstrong', 'James Ward Byrkit', 'Thriller, Science Fiction', 2014, 'Bellanova Films, Ugly Duckling Films', '89', 3.6, 'US, GB', 'English', 'https://image.tmdb.org/t/p/w500/ezUtb9m5DeLwL2gxi4gktzNCvQv.jpg', 'Four couples gather for dinner the night a mysterious and powerful comet passes overhead.'),
(552, 424, 'Schindler\'s List', 'Steven Spielberg', 'Liam Neeson, Ben Kingsley, Ralph Fiennes, Caroline Goodall, Jonathan Sagall, Embeth Davidtz', 'Steven Zaillian', 'Drama, History, War', 1993, 'Amblin Entertainment', '195', 4.3, 'US', 'Deutsch, Polski, עִבְרִית, English', 'https://image.tmdb.org/t/p/w500/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', 'The true story of how businessman Oskar Schindler saved over a thousand Jewish lives from the Nazis while they worked as slaves in his factory during World War II.'),
(553, 330, 'The Lost World: Jurassic Park', 'Steven Spielberg', 'Jeff Goldblum, Julianne Moore, Pete Postlethwaite, Arliss Howard, Richard Attenborough, Vince Vaughn', 'David Koepp', 'Adventure, Action, Science Fiction', 1997, 'Universal Pictures, Amblin Entertainment', '129', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/7st3JW0xpMAkwB3dYfv3iqAwD8Y.jpg', 'Four years after Jurassic Park\'s genetically bred dinosaurs ran amok, multimillionaire John Hammond shocks chaos theorist Ian Malcolm by revealing that he has been breeding more beasties at a secret location. Malcolm, his paleontologist ladylove and a wildlife videographer join an expedition to document the lethal lizards\' natural behavior in this action-packed thriller.'),
(554, 437586, 'mid90s', 'Jonah Hill', 'Sunny Suljic, Katherine Waterston, Lucas Hedges, Na-kel Smith, Olan Prenatt, Gio Galicia', 'Jonah Hill', 'Drama, Comedy', 2018, 'A24, Waypoint Entertainment', '86', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/9Tw0Y3DK5kGIU9X1yw3Q9gCkOlb.jpg', 'In 1990s Los Angeles, a 13-year-old spends his summer navigating between a troubled home life and a crew of new friends he meets at a skate shop.'),
(555, 340666, 'Nocturnal Animals', 'Tom Ford', 'Amy Adams, Jake Gyllenhaal, Michael Shannon, Aaron Taylor-Johnson, Isla Fisher, Ellie Bamber', 'Tom Ford', 'Drama, Thriller', 2016, 'Fade To Black, Artina Films, Focus Features, Perfect World Pictures, Tom Ford', '116', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/mdLDgQBD0va09npSQX5Zgo2evXM.jpg', 'Susan Morrow receives a book manuscript from her ex-husband – a man she left 20 years earlier – asking for her opinion of his writing. As she reads, she is drawn into the fictional life of Tony Hastings, a mathematics professor whose family vacation turns violent.'),
(556, 508883, 'The Boy and the Heron', 'Hayao Miyazaki', 'Soma Santoki, Masaki Suda, Ko Shibasaki, Aimyon, Yoshino Kimura, Takuya Kimura', 'Hayao Miyazaki', 'Animation, Fantasy, Drama', 2023, 'Studio Ghibli', '124', 3.7, 'JP', '日本語', 'https://image.tmdb.org/t/p/w500/f4oZTcfGrVTXKTWg157AwikXqmP.jpg', 'While the Second World War rages, the teenage Mahito, haunted by his mother\'s tragic death, is relocated from Tokyo to the serene rural home of his new stepmother Natsuko, a woman who bears a striking resemblance to the boy\'s mother.  As he tries to adjust, this strange new world grows even stranger following the appearance of a persistent gray heron, who perplexes and bedevils Mahito, dubbing him the \"long-awaited one.\"'),
(557, 466420, 'Killers of the Flower Moon', 'Martin Scorsese', 'Leonardo DiCaprio, Robert De Niro, Lily Gladstone, Jesse Plemons, Tantoo Cardinal, John Lithgow', 'Martin Scorsese, Eric Roth', 'Crime, History, Drama', 2023, 'Apple Studios, Imperative Entertainment, Sikelia Productions, Appian Way', '206', 3.7, 'US', 'English, Latin, Français', 'https://image.tmdb.org/t/p/w500/dB6Krk806zeqd0YNp2ngQ9zXteH.jpg', 'When oil is discovered in 1920s Oklahoma under Osage Nation land, the Osage people are murdered one by one—until the FBI steps in to unravel the mystery.'),
(558, 301804, 'Before I Wake', 'Mike Flanagan', 'Kate Bosworth, Jacob Tremblay, Thomas Jane, Annabeth Gish, Lance E. Nichols, Scottie Thompson', 'Mike Flanagan', 'Drama, Fantasy, Horror, Thriller', 2016, 'MICA Entertainment, Intrepid Pictures, Demarest Films', '97', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/sI9neTbF3ECdpf2MpC88EMGJH13.jpg', 'An orphaned child\'s dreams—and nightmares—manifest physically as he sleeps.'),
(559, 242582, 'Nightcrawler', 'Dan Gilroy', 'Jake Gyllenhaal, Rene Russo, Riz Ahmed, Bill Paxton, Kevin Rahm, Michael Hyatt', 'Dan Gilroy', 'Crime, Drama, Thriller', 2014, 'Sierra/Affinity, Bold Films', '118', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/j9HrX8f7GbZQm1BrBiR40uFQZSb.jpg', 'When Lou Bloom, desperate for work, muscles into the world of L.A. crime journalism, he blurs the line between observer and participant to become the star of his own story. Aiding him in his effort is Nina, a TV-news veteran.'),
(560, 1359, 'American Psycho', 'Mary Harron', 'Christian Bale, Justin Theroux, Josh Lucas, Bill Sage, Chloë Sevigny, Reese Witherspoon', 'Mary Harron, Guinevere Turner', 'Thriller, Drama, Crime', 2000, 'Lionsgate, Pressman Film, Muse Productions, Christian Halsey Solomon Productions', '102', 3.7, 'US', 'English, Español, 广州话 / 廣州話', 'https://image.tmdb.org/t/p/w500/9uGHEgsiUXjCNq8wdq4r49YL8A1.jpg', 'A wealthy New York investment banking executive hides his alternate psychopathic ego from his co-workers and friends as he escalates deeper into his illogical, gratuitous fantasies.'),
(561, 507089, 'Five Nights at Freddy\'s', 'Emma Tammi', 'Josh Hutcherson, Piper Rubio, Elizabeth Lail, Matthew Lillard, Mary Stuart Masterson, Kat Conner Sterling', 'Seth Cuddeback, Scott Cawthon, Emma Tammi', 'Horror, Thriller', 2023, 'Blumhouse Productions, Scott Cawthon Productions', '110', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/7BpNtNfxuocYEVREzVMO75hso1l.jpg', 'Recently fired and desperate for work, a troubled young man named Mike agrees to take a position as a night security guard at an abandoned theme restaurant: Freddy Fazbear\'s Pizzeria. But he soon discovers that nothing at Freddy\'s is what it seems.'),
(562, 141, 'Donnie Darko', 'Richard Kelly', 'Jake Gyllenhaal, Jena Malone, James Duval, Drew Barrymore, Beth Grant, Maggie Gyllenhaal', 'Richard Kelly', 'Fantasy, Drama, Mystery', 2001, 'Flower Films, Pandora Cinema, Newmarket Films', '114', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/j2AtZFsflxiluaNtajMTI0Avm8C.jpg', 'After narrowly escaping a bizarre accident, a troubled teenager is plagued by visions of a large bunny rabbit that manipulates him to commit a series of crimes.'),
(563, 68730, 'Silence', 'Martin Scorsese', 'Andrew Garfield, Adam Driver, Liam Neeson, Tadanobu Asano, Ciarán Hinds, Issey Ogata', 'Jay Cocks, Martin Scorsese', 'Drama, History', 2016, 'Waypoint Entertainment, Cappa Defina Productions, CatchPlay, Fábrica de Cine, SharpSword Films, Sikelia Productions, EFO Films', '161', 3.6, 'US', '日本語, English', 'https://image.tmdb.org/t/p/w500/x5T0cQDYws0xRBVG4Q3wpcrcmax.jpg', 'In the 17th century, two Portuguese Jesuit priests travel to Japan in an attempt to locate their mentor, who is rumored to have committed apostasy, and to propagate Catholicism.'),
(564, 800158, 'The Killer', 'David Fincher', 'Michael Fassbender, Tilda Swinton, Charles Parnell, Arliss Howard, Kerry O\'Malley, Sophie Charlotte', 'Andrew Kevin Walker', 'Crime, Thriller', 2023, 'Netflix', '118', 3.3, 'US', 'English, Français, Español', 'https://image.tmdb.org/t/p/w500/ipkcgvN7h3yZnbYowthloHLKsf4.jpg', 'After a fateful miss, an assassin battles his employers, and himself, on an international manhunt he insists isn\'t personal.'),
(565, 502356, 'The Super Mario Bros. Movie', 'Aaron Horvath', 'Chris Pratt, Anya Taylor-Joy, Charlie Day, Jack Black, Keegan-Michael Key, Seth Rogen', 'Aaron Horvath, Michael Jelenic', 'Family, Comedy, Adventure, Fantasy, Animation', 2023, 'Universal Pictures, Illumination, Nintendo', '93', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/qNBAXBIQlnOThrVvA6mA2B5ggV6.jpg', 'While working underground to fix a water main, Brooklyn plumbers—and brothers—Mario and Luigi are transported down a mysterious pipe and wander into a magical new world. But when the brothers are separated, Mario embarks on an epic quest to find Luigi.'),
(566, 609681, 'The Marvels', 'Nia DaCosta', 'Brie Larson, Teyonah Parris, Iman Vellani, Samuel L. Jackson, Zawe Ashton, Gary Lewis', 'Nia DaCosta', 'Science Fiction, Adventure, Action', 2023, 'Marvel Studios, Kevin Feige Productions', '105', 3.0, 'US', 'English, اردو', 'https://image.tmdb.org/t/p/w500/9GBhzXMFjgcZ3FdR9w3bUMMTps5.jpg', 'When her duties send her to an anomalous wormhole linked to a Kree revolutionary, Carol\'s powers become entangled with that of Jersey City super-fan Kamala Khan, aka Ms. Marvel, and Carol\'s estranged niece, now S.A.B.E.R. astronaut Captain Monica Rambeau. Together, this unlikely trio must team up and learn to work in concert to save the universe.'),
(567, 68722, 'The Master', 'Paul Thomas Anderson', 'Joaquin Phoenix, Philip Seymour Hoffman, Amy Adams, Rami Malek, Laura Dern, Jesse Plemons', 'Paul Thomas Anderson', 'Drama', 2012, 'Annapurna Pictures, Ghoulardi Film Company, JoAnne Sellar Productions', '137', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/rUSjbyvYWN9H4az8xt0tDtU7I6v.jpg', 'Freddie, a volatile, heavy-drinking veteran who suffers from post-traumatic stress disorder, finds some semblance of a family when he stumbles onto the ship of Lancaster Dodd, the charismatic leader of a new \"religion\" he forms after World War II.'),
(568, 370755, 'Paterson', 'Jim Jarmusch', 'Adam Driver, Golshifteh Farahani, Rizwan Manji, Barry Shabaka Henley, William Jackson Harper, Chasten Harmon', 'Jim Jarmusch', 'Drama, Comedy, Romance', 2016, 'K5 International, Le Pacte, Inkjet, Animal Kingdom', '118', 3.6, 'US', 'English, Italiano', 'https://image.tmdb.org/t/p/w500/AuJ1ZlfqwuAr9H5Qr1U9KILylse.jpg', 'A week in the life of Paterson, a poet bus driver, and his wife Laura, a very creative artist, who live in Paterson, New Jersey, hometown of many famous poets and artists.'),
(569, 963765, 'Strange Way of Life', 'Pedro Almodóvar', 'Ethan Hawke, Pedro Pascal, Jason Fernández, José Condessa, Daniel Rived, Sara Sálamo', 'Pedro Almodóvar', 'Drama, Western, Romance', 2023, 'El Deseo, Saint Laurent', '31', 3.1, 'ES', 'English, Español', 'https://image.tmdb.org/t/p/w500/uKOSFVplHUtvjtDEE5N4x8Hs9vL.jpg', 'After 25 years, a former hired gun visits his old colleague, now a small-town sheriff. Their past relationship is explored, as is how they reflect on it in the present.'),
(570, 838240, 'Robot Dreams', 'Pablo Berger', 'Ivan Labanda, Tito Trifol, Rafa Calvo, José García Tos, José Luis Mediavilla, Graciela Molina', 'Pablo Berger', 'Animation, Drama, Comedy, Science Fiction', 2023, 'Arcadia Motion Pictures, LokizFilms, Noodles Production, Les films du Worso', '102', 4.0, 'ES', 'No Language', 'https://image.tmdb.org/t/p/w500/ds402Qq09ybgBcXKiQNTZfzsP5o.jpg', 'A lonely dog\'s friendship with his robot companion takes a sad turn when an unexpected malfunction forces him to abandon Robot at the beach. Will Dog ever meet Robot again?'),
(571, 986280, 'Fallen Leaves', 'Aki Kaurismäki', 'Alma Pöysti, Jussi Vatanen, Janne Hyytiäinen, Nuppu Koivu, Mia Snellman, Mikko Mykkänen', 'Aki Kaurismäki', 'Romance, Comedy, Drama', 2023, 'Sputnik, Bufo, Pandora Film', '81', 3.6, 'FI', 'suomi, العربية', 'https://image.tmdb.org/t/p/w500/9ayYOpeqHhxfHHUoyt3kXzznECO.jpg', 'In modern-day Helsinki, two lonely souls in search of love meet by chance in a karaoke bar. However, their path to happiness is beset by obstacles – from lost phone numbers to mistaken addresses, alcoholism, and a charming stray dog.'),
(572, 493529, 'Dungeons & Dragons: Honor Among Thieves', 'Jonathan Goldstein', 'Chris Pine, Michelle Rodriguez, Justice Smith, Sophia Lillis, Hugh Grant, Regé-Jean Page', 'Michael Gilio, John Francis Daley, Jonathan Goldstein', 'Adventure, Fantasy, Comedy', 2023, 'Entertainment One, Paramount Pictures', '134', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/v7UF7ypAqjsFZFdjksjQ7IUpXdn.jpg', 'A charming thief and a band of unlikely adventurers undertake an epic heist to retrieve a lost relic, but things go dangerously awry when they run afoul of the wrong people.'),
(573, 146233, 'Prisoners', 'Denis Villeneuve', 'Hugh Jackman, Jake Gyllenhaal, Viola Davis, Maria Bello, Terrence Howard, Melissa Leo', 'Denis Villeneuve', 'Drama, Thriller, Crime', 2013, 'Alcon Entertainment, 8:38 Productions, Madhouse Entertainment', '153', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg', 'After his six-year-old daughter is abducted, a desperate father takes justice into his own hands when he loses faith in the detective leading the investigation, setting both men on a collision course as the search descends into obsession and moral compromise.'),
(574, 76492, 'Hotel Transylvania', 'Genndy Tartakovsky', 'Selena Gomez, Adam Sandler, Andy Samberg, Kevin James, Fran Drescher, Steve Buscemi', 'Peter Baynham, Robert Smigel', 'Animation, Comedy, Family, Fantasy', 2012, 'Columbia Pictures, Sony Pictures Animation', '91', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/eJGvzGrsfe2sqTUPv5IwLWXjVuR.jpg', 'Welcome to Hotel Transylvania, Dracula\'s lavish five-stake resort, where monsters and their families can live it up and no humans are allowed. One special weekend, Dracula has invited all his best friends to celebrate his beloved daughter Mavis\'s 118th birthday. For Dracula catering to all of these legendary monsters is no problem but the party really starts when one ordinary guy stumbles into the hotel and changes everything!'),
(575, 839369, 'May December', 'Todd Haynes', 'Natalie Portman, Julianne Moore, Charles Melton, Cory Michael Smith, Elizabeth Yu, Gabriel Barbosa', 'Samy Burch', 'Drama', 2023, 'Gloria Sanchez Productions, Killer Films, MountainA, Taylor & Dodge, Project Infinity', '117', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/zhV7B610l7hjlri4ywikJ18ONuq.jpg', 'Twenty years after their notorious tabloid romance gripped the nation, a married couple buckles under the pressure when an actress arrives to do research for a film about their past.'),
(576, 695721, 'The Hunger Games: The Ballad of Songbirds & Snakes', 'Francis Lawrence', 'Tom Blyth, Rachel Zegler, Peter Dinklage, Jason Schwartzman, Hunter Schafer, Josh Rivera', 'Michael Lesslie, Michael Arndt', 'Science Fiction, Action', 2023, 'Lionsgate, Color Force, about:blank, Studio Babelsberg', '157', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg', '64 years before he becomes the tyrannical president of Panem, Coriolanus Snow sees a chance for a change in fortunes when he mentors Lucy Gray Baird, the female tribute from District 12.'),
(577, 131631, 'The Hunger Games: Mockingjay - Part 1', 'Francis Lawrence', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Julianne Moore', 'Danny Strong, Peter Craig', 'Science Fiction, Adventure, Thriller', 2014, 'Lionsgate, Color Force', '123', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/4FAA18ZIja70d1Tu5hr5cj2q1sB.jpg', 'After surviving the Quarter Quell, Katniss finds herself in the hidden stronghold of District 13, where the rebellion against the Capitol is gaining momentum. Struggling with the weight of becoming the symbol of resistance, she must navigate fragile alliances while trying to protect those she loves. As propaganda battles rage and Panem moves closer to full-scale war, Katniss is forced to confront the true cost of revolution.'),
(578, 131634, 'The Hunger Games: Mockingjay - Part 2', 'Francis Lawrence', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Julianne Moore', 'Danny Strong, Peter Craig', 'Action, Adventure, Science Fiction', 2015, 'Lionsgate, Color Force, Studio Babelsberg', '137', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/lImKHDfExAulp16grYm8zD5eONE.jpg', 'As the war between the Capitol and the districts reaches its peak, Katniss Everdeen embarks on a perilous mission to liberate Panem and confront President Snow. Joined by a team of trusted allies, she navigates deadly traps, shifting loyalties, and the heavy cost of rebellion, determined to bring freedom to her people and end the Hunger Games once and for all.'),
(579, 569094, 'Spider-Man: Across the Spider-Verse', 'Kemp Powers', 'Shameik Moore, Hailee Steinfeld, Brian Tyree Henry, Luna Lauren Vélez, Jake Johnson, Oscar Isaac', 'Justin K. Thompson, Kemp Powers', 'Animation, Action, Adventure, Science Fiction', 2023, 'Columbia Pictures, Sony Pictures Animation, Lord Miller, Pascal Pictures, Arad Productions, Marvel Entertainment', '140', 4.2, 'US', 'English, हिन्दी, Italiano, Español', 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse\'s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.'),
(580, 840430, 'The Holdovers', 'Alexander Payne', 'Paul Giamatti, Dominic Sessa, Da\'Vine Joy Randolph, Carrie Preston, Brady Hepner, Ian Dolley', 'Alexander Payne', 'Drama, Comedy', 2023, 'Miramax, Gran Via Productions', '133', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', 'A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.'),
(581, 1895, 'Star Wars: Episode III - Revenge of the Sith', 'George Lucas', 'Hayden Christensen, Ewan McGregor, Natalie Portman, Ian McDiarmid, Samuel L. Jackson, Jimmy Smits', 'George Lucas', 'Adventure, Action, Science Fiction', 2005, 'Lucasfilm Ltd.', '140', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg', 'When the sinister Sith unveil a thousand-year-old plot to rule the galaxy, the Republic crumbles and from its ashes rises the evil Galactic Empire. Jedi hero Anakin Skywalker must choose a side.'),
(582, 915935, 'Anatomy of a Fall', 'Justine Triet', 'Sandra Hüller, Swann Arlaud, Milo Machado-Graner, Antoine Reinartz, Samuel Theis, Jehnny Beth', 'Justine Triet, Arthur Harari', 'Thriller, Mystery, Crime', 2023, 'Les Films de Pierre, Les Films Pelléas, France 2 Cinéma, Auvergne-Rhône-Alpes Cinéma', '151', 3.8, 'FR', 'English, Français', 'https://image.tmdb.org/t/p/w500/1ho0d4LNZw3Y0voeKmSvPSgJOJ2.jpg', 'A woman is suspected of her husband\'s murder, and their blind son faces a moral dilemma as the sole witness.'),
(583, 760245, 'Foe', 'Garth Davis', 'Paul Mescal, Saoirse Ronan, Aaron Pierre, Jordan Chodziesner, William Freeman, Jalen Ong', 'Garth Davis, Iain Reid', 'Science Fiction, Drama', 2023, 'I Am That, See-Saw Films, Anonymous Content', '111', 2.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/eTPBizhkX6B9NgzPzkhVIOvwXxZ.jpg', 'Henrietta and Junior farm a secluded piece of land that has been in Junior\'s family for generations, but their quiet life is thrown into turmoil when an uninvited stranger shows up at their door with a startling proposal. Will they risk their relationship & personal identity for a chance to survive in a new world?'),
(584, 1172675, 'The Swan', 'Wes Anderson', 'Rupert Friend, Ralph Fiennes, Asa Jennings, Eliel Ford, Truman Hanks, Benoît Herlin', 'Wes Anderson', 'Drama', 2023, 'American Empirical Pictures, Indian Paintbrush', '17', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/fRbx6DPdQBJrhZWyshjJABtAIyu.jpg', 'Two large, ignorant bullies ruthlessly pursue a small, brilliant boy in this young adult Roald Dahl short story.'),
(585, 771, 'Home Alone', 'Chris Columbus', 'Macaulay Culkin, Joe Pesci, Daniel Stern, John Heard, Roberts Blossom, Catherine O\'Hara', 'John Hughes', 'Comedy, Family', 1990, 'Hughes Entertainment, 20th Century Fox', '103', 3.7, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg', 'Eight-year-old Kevin McCallister makes the most of the situation after his family unwittingly leaves him behind when they go on Christmas vacation. When thieves try to break into his home, he puts up a fight like no other.'),
(586, 523607, 'Maestro', 'Bradley Cooper', 'Carey Mulligan, Bradley Cooper, Matt Bomer, Vincenzo Amato, Greg Hildreth, Michael Urie', 'Bradley Cooper', 'Drama, Romance, Music', 2023, 'Amblin Entertainment, Fred Berner Films, Sikelia Productions, Lea Pictures', '129', 3.1, 'US', 'English, Pусский, Español', 'https://image.tmdb.org/t/p/w500/kxj7rMco6RNYsVcNwuGAIlfWu64.jpg', 'A towering and fearless love story chronicling the lifelong relationship between Leonard Bernstein and Felicia Montealegre Cohn Bernstein. A love letter to life and art, Maestro at its core is an emotionally epic portrayal of family and love.'),
(587, 1020006, 'Priscilla', 'Sofia Coppola', 'Cailee Spaeny, Jacob Elordi, Ari Cohen, Dagmara Dominczyk, Tim Post, Lynne Griffin', 'Sofia Coppola', 'Drama, Romance', 2023, 'The Apartment Pictures, American Zoetrope', '113', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/uDCeELWWpsNq7ErM61Yuq70WAE9.jpg', 'When teenage Priscilla Beaulieu meets Elvis Presley at a party, the man who is already a meteoric rock-and-roll superstar becomes someone entirely unexpected in private moments: a thrilling crush, an ally in loneliness, a vulnerable best friend.'),
(588, 823482, 'Dream Scenario', 'Kristoffer Borgli', 'Nicolas Cage, Julianne Nicholson, Michael Cera, Tim Meadows, Dylan Gelula, Lily Bird', 'Kristoffer Borgli', 'Comedy, Fantasy', 2023, 'A24, Square Peg, Saturn Films', '102', 3.3, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/eMaAi8wTI5wON8pp33w3BDuGyZ8.jpg', 'Hapless family man Paul Matthews finds his life turned upside down when millions of strangers suddenly start seeing him in their dreams. But when his nighttime appearances take a nightmarish turn, Paul is forced to navigate his newfound stardom.'),
(590, 980026, 'The Promised Land', 'Nikolaj Arcel', 'Mads Mikkelsen, Amanda Collin, Simon Bennebjerg, Kristine Kujath Thorp, Gustav Lindh, Jacob Lohmann', 'Nikolaj Arcel', 'Action, Drama, History', 2023, 'Zentropa International Berlin, Zentropa International Sweden, Zentropa Entertainments', '127', 3.8, 'DK', 'Dansk, Deutsch, Norsk, svenska', 'https://image.tmdb.org/t/p/w500/okVwls2laPGOsLKKhXQCEiTBwpw.jpg', 'Denmark, 1755. Captain Ludvig Kahlen sets out to conquer a Danish heath reputed to be uncultivable, with an impossible goal: to establish a colony in the name of the king, in exchange for a royal title. A single-minded ambition that the ruthless lord of the region will relentlessly seek to put down. Kahlen\'s fate hangs in the balance: will his endevours bring him wealth and honour, or cost him his life...?'),
(591, 998022, 'The Teachers\' Lounge', 'İlker Çatak', 'Leonie Benesch, Leonard Stettnisch, Eva Löbau, Michael Klammer, Rafael Stachowiak, Sarah Bauerett', 'Johannes Duncker, İlker Çatak', 'Drama', 2023, 'if... Productions, ZDF, ARTE', '98', 3.6, 'DE', 'English, Deutsch, Polski, Türkçe', 'https://image.tmdb.org/t/p/w500/kWXA6PfQ0PpZpoCXoeBFRciRrUw.jpg', 'When one of her students is suspected of theft, teacher Carla Nowak decides to get to the bottom of the matter. Caught between her ideals and the school system, the consequences of her actions threaten to break her.'),
(592, 776503, 'CODA', 'Sian Heder', 'Emilia Jones, Marlee Matlin, Troy Kotsur, Eugenio Derbez, Ferdia Walsh-Peelo, Daniel Durant', 'Sian Heder', 'Drama, Music, Romance', 2021, 'Vendôme Pictures, Pathé, Picture Perfect Entertainment', '112', 3.9, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/BzVjmm8l23rPsijLiNLUzuQtyd.jpg', 'As a CODA (Child of Deaf Adults), Ruby is the only hearing person in her deaf family. When the family\'s fishing business is threatened, Ruby finds herself torn between pursuing her love of music and her fear of abandoning her parents.'),
(593, 664341, 'Eileen', 'William Oldroyd', 'Thomasin McKenzie, Anne Hathaway, Shea Whigham, Sam Nivola, Marin Ireland, Siobhan Fallon Hogan', 'Luke Goebel, Ottessa Moshfegh', 'Thriller, Crime', 2023, 'Likely Story, Film4 Productions, Omniscient Films, Fifth Season', '98', 2.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/x6kedRqcj8jH0cik9p1jzkDwZvM.jpg', 'During a bitter 1964 Massachusetts winter, young secretary Eileen becomes enchanted by Rebecca, the glamorous new counselor at the prison where she works. Their budding friendship takes a twisted turn when Rebecca reveals a dark secret — throwing Eileen onto a sinister path.'),
(594, 38745, 'Gulliver\'s Travels', 'Rob Letterman', 'Jack Black, Jason Segel, Emily Blunt, Amanda Peet, Billy Connolly, Chris O\'Dowd', 'Joe Stillman, Nicholas Stoller', 'Family, Comedy, Adventure, Fantasy', 2010, 'Dune Entertainment, Davis Entertainment, Dune Entertainment III, 20th Century Fox', '85', 2.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6NoEtuTwZ04luk5H2DpT5ivW7Mg.jpg', 'Travel writer Lemuel Gulliver takes an assignment in Bermuda, but ends up on the island of Liliput, where he towers over its tiny citizens.'),
(595, 906126, 'Society of the Snow', 'J. A. Bayona', 'Enzo Vogrincic, Agustín Pardella, Matías Recalt, Esteban Bigliardi, Diego Vegezzi, Fernando Contigiani García', 'Bernat Vilaplana, J. A. Bayona, Jaime Marques', 'Drama, History', 2023, 'El Arriero Films, Misión de Audaces Films, Netflix', '143', 4.0, 'ES', 'Español', 'https://image.tmdb.org/t/p/w500/2e853FDVSIso600RqAMunPxiZjq.jpg', 'On October 13, 1972, Uruguayan Air Force Flight 571, chartered to take a rugby team to Chile, crashes into a glacier in the heart of the Andes.'),
