(1010, 1159206, 'Father Mother Sister Brother', 'Jim Jarmusch', 'Tom Waits, Adam Driver, Mayim Bialik, Charlotte Rampling, Cate Blanchett, Vicky Krieps', 'Jim Jarmusch', 'Comedy, Drama', 2025, 'Badjetlag, Hail Mary Pictures, Saint Laurent Productions, MUBI, The Apartment Pictures, Les Films du Losange, Weltkino, Cinema Inutile, Fís Éireann/Screen Ireland, Vague Notion, CG Cinéma, Saint Laurent', '111', 3.2, 'US', 'Français, English', 'https://image.tmdb.org/t/p/w500/96O3Ol3f2veMxAxYqsML8rOumB9.jpg', 'Estranged siblings reunite after years apart, forced to confront unresolved tensions and reevaluate their strained relationships with their emotionally distant parents.'),
(1011, 1214931, 'Nuremberg', 'James Vanderbilt', 'Rami Malek, Russell Crowe, Michael Shannon, Leo Woodall, John Slattery, Richard E. Grant', 'James Vanderbilt', 'History, Drama', 2025, 'Bluestone Entertainment, Walden Media, Filmsquad, Mythology Entertainment, Titan Media', '149', 3.8, 'US', 'English, Deutsch', 'https://image.tmdb.org/t/p/w500/xthXNYltOOm80vW5Kxjzxx5gvQ6.jpg', 'In postwar Germany, an American psychiatrist must determine whether Nazi prisoners are fit to go on trial for war crimes, and finds himself in a complex battle of intellect and ethics with Hermann Göring, Hitler\'s right-hand man.'),
(1012, 1480382, 'The Voice of Hind Rajab', 'Kaouther Ben Hania', 'Hind Rajab, Motaz Malhees, Saja Kilani, Amer Hlehel, Clara Khoury, Nesbat Serhan', 'Kaouther Ben Hania', 'Drama, History', 2025, 'Mime Films, Tanit Films, Film4 Productions, MBC Studios, Amed Khan Foundation, Stiching Giustra International Foundation, Watermelon Pictures, Utopia Studios, PFF, World Within, MeMo Films, Sunnyland Film, RaeFilm Studios, JW Films, Willa, Plan B Entertainment, Valentine, The Rambourg Foundation, Common Pictures, 1888 Films, LinLay Productions', '89', 4.0, 'TN', 'English, العربية', 'https://image.tmdb.org/t/p/w500/q7M8kQB46T11vmDMD6E239jsqTz.jpg', 'January 29, 2024. Red Crescent volunteers receive an emergency call. A five-year old girl is trapped in a car under fire in Gaza, pleading for rescue. While trying to keep her on the line, they do everything they can to get an ambulance to her. Her name was Hind Rajab.'),
(1013, 804370, 'Arco', 'Ugo Bienvenu', 'Margot Ringard Oldra, Oscar Tresanini, Nathanaël Perrot, Alma Jodorowsky, Swann Arlaud, Vincent Macaigne', 'Ugo Bienvenu', 'Adventure, Animation, Family, Science Fiction', 2025, 'Remembers, MountainA, France 3 Cinéma, Fit Via Vi, Sons of Rigor Films', '89', 3.8, 'FR', 'Français', 'https://image.tmdb.org/t/p/w500/mWlvHFxTDhq9O5WSOHywa32QIez.jpg', 'Ten-year-old Arco lives in a far future. During his first flight in his rainbow suit, he loses control and falls into the past. Iris, a girl his age from 2075, comes to his rescue and tries by any means to help send him back to his own era.'),
(1014, 1317149, 'I Swear', 'Kirk Jones', 'Robert Aramayo, Maxine Peake, Peter Mullan, Shirley Henderson, Scott Ellis Watson, David Carlyle', 'Kirk Jones', 'Drama, History', 2025, 'One Story High, Tempo Productions', '121', 4.1, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/vUwyhNWBKkSwK8ELvEeBRwV724h.jpg', 'Diagnosed with Tourette Syndrome at 15, John Davidson navigates his way against the odds through troubled teenage years and into adulthood, finding inspiration in the kindness of others to discover his true purpose in life.'),
(1015, 1119449, 'Good Luck, Have Fun, Don\'t Die', 'Gore Verbinski', 'Sam Rockwell, Juno Temple, Haley Lu Richardson, Michael Peña, Zazie Beetz, Asim Chaudhry', 'Gore Verbinski', 'Science Fiction, Action, Comedy', 2026, 'Constantin Film, Blind Wink, 3 Arts Entertainment, Robert Kulzer Productions', '134', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/rWcfOdY7TU6lTdazWj0ebDZnAfO.jpg', 'A \'Man from the Future\' arrives at an LA diner where he must recruit the precise combination of disgruntled patrons to join him on a one-night quest to save the world from the terminal threat of a rogue artificial intelligence.'),
(1016, 1263012, 'Dead Man\'s Wire', 'Gus Van Sant', 'Bill Skarsgård, Dacre Montgomery, Cary Elwes, Myha\'la, Kelly Lynch, John Robinson', 'Gus Van Sant', 'Crime, Drama, Thriller', 2026, 'Elevated Films, Balcony 9 Productions, RNA Pictures, TPC, Sobini Films, Co Created Media, Copper Island, Last Mile Productions, Wrong Turn Productions, SIPUR, Construction Film, Streamline Global, Pressman Film, Space Pilot Media, WME Independent, Pinstripes, Film Manufacturers, LB Entertainment, Edith Productions, YO Productions, Filmhedge, Sillen Productions, Punch Once, Eterna, Notorious Productions Film Fund, VL Entertainment, Raised by Wolves Pictures', '106', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/dgSoeebklY0IGKWbp36r9FwRXlv.jpg', 'In 1977, former real estate developer Tony Kiritsis puts a dead man\'s switch on himself and the mortgage banker who did him wrong, demanding $5 million and a personal apology.'),
(1017, 682012, 'Little Amélie or the Character of Rain', 'Maïlys Vallade', 'Loïse Charpentier, Victoria Grobois, Yumi Fujimori, Cathy Cerda, Marc Arnaud, Laëtitia Coryn', 'Liane-cho Han, Aude Py, Eddine Noel', 'Animation, Drama, Family', 2025, 'Maybe Movies, 2 Minutes, France 3 Cinéma, Puffin Pictures, 22D Music, Ikki Films', '77', 3.9, 'FR', 'Français, 日本語', 'https://image.tmdb.org/t/p/w500/qoqDvTUVPoZJWw24AjGDt3J4tZN.jpg', 'The world is a perplexing, peaceful mystery to Amélie until a miraculous encounter with chocolate ignites her wild sense of curiosity. As she develops a deep attachment to her family\'s housekeeper, Nishio-san, Amélie discovers the wonders of nature as well as the emotional truths hidden beneath the surface of her family\'s idyllic life as foreigners in post-war Japan.'),
(1018, 1084242, 'Zootopia 2', 'Jared Bush', 'Ginnifer Goodwin, Jason Bateman, Ke Huy Quan, Fortune Feimster, Andy Samberg, David Strathairn', 'Jared Bush, Byron Howard', 'Animation, Adventure, Comedy, Mystery, Family', 2025, 'Walt Disney Animation Studios, Walt Disney Animation Studios', '108', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/oJ7g2CifqpStmoYQyaLQgEU32qO.jpg', 'After cracking the biggest case in Zootopia\'s history, rookie cops Judy Hopps and Nick Wilde find themselves on the twisting trail of a great mystery when Gary De\'Snake arrives and turns the animal metropolis upside down. To crack the case, Judy and Nick must go undercover to unexpected new parts of town, where their growing partnership is tested like never before.'),
(1019, 1443576, 'Sundays', 'Alauda Ruiz de Azúa', 'Blanca Soroa, Patricia López Arnaiz, Miguel Garcés, Juan Minujín, Mabel Rivera, Nagore Aranburu', 'Alauda Ruiz de Azúa', 'Drama', 2025, 'Encanta Films, Sayaka Producciones, Think Studio, Colosé Producciones, Le Pacte, Movistar Plus+, Buena Pinta Media', '112', 3.5, 'ES', 'Español', 'https://image.tmdb.org/t/p/w500/3682SbY3rsNKsQzFpPUKrWdGmmx.jpg', '17-year-old Ainara is a student at a Catholic secondary school, and is about to take her final year exams and choose her future university course. To everyone’s surprise, this brilliant young girl announces to her family that she wants to take part in an induction period at a convent in order to embrace the religious life. Nobody was expecting this. While her father seems to be won over by his daughter’s aspirations, for Maite, Ainara’s aunt, this unexpected vocation is the manifestation of a deeper problem.'),
(1020, 1284120, 'The Ugly Stepsister', 'Emilie Blichfeldt', 'Lea Myren, Ane Dahl Torp, Thea Sofie Loch Næss, Flo Fagerli, Isac Calmroth, Malte Gårdinger', 'Emilie Blichfeldt', 'Horror, Comedy, Drama', 2025, 'Mer Film, Lava Films, MOTOR, Scanbox Production, Zentropa International Sweden, Mediefondet Zefyr, Film i Väst', '109', 3.7, 'NO', 'Norsk, Polski, svenska', 'https://image.tmdb.org/t/p/w500/rayAREIKtSinuov10GvrZHyXfXH.jpg', 'In a fairy-tale kingdom where beauty is a brutal business, Elvira battles to compete with her incredibly beautiful stepsister, Agnes, and she will go to any length to catch the Prince’s eye.'),
(1021, 878608, 'Resurrection', 'Bi Gan', 'Jackson Yee, Shu Qi, Mark Chao, Li Gengxi, Huang Jue, Chen Yongzhong', 'Bi Gan, Zhai Xiaohui', 'Science Fiction, Drama', 2025, 'Dangmai Films 荡麦影业, Huace Media, Maoyan Entertainment, Daxi Culture Media, Poly Film Investment, Muxin Culture Communication, Yanhuadeng Media, Leopard Films, Tianyue Culture Media, Creative Pioneer International, CG Cinéma, Chengdu Film Group, China Monolith Pictures, Water Spirit Pictures, Thin Blue Line Pictures, Inna Art Space, Aranya Pictures, Yaojin Pictures, Sanhe Huibi Media, K. Artists, ARTE France Cinéma', '159', 3.6, 'CN', '普通话', 'https://image.tmdb.org/t/p/w500/4asJAxshXzQriox6tnIoEnWN1nu.jpg', 'In a future where humanity has surrendered its ability to dream in exchange for immortality, an outcast finds illusion, nightmarish visions, and beauty in an intoxicating world of his own making.'),
(1022, 1140498, 'Is This Thing On?', 'Bradley Cooper', 'Will Arnett, Laura Dern, Andra Day, Bradley Cooper, Christine Ebersole, Ciarán Hinds', 'Mark Chappell, Will Arnett, Bradley Cooper', 'Comedy, Drama, Romance', 2025, 'Searchlight Pictures, Archery Pictures, Lea Pictures, TSG Entertainment', '121', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/YD6QzcokTMe3EViM0hLbNCxf4y.jpg', 'As their marriage quietly unravels, Alex faces middle age and an impending divorce, seeking new purpose in the New York comedy scene while Tess confronts the sacrifices she made for their family—forcing them to navigate co-parenting, identity, and whether love can take a new form.'),
(1023, 1198994, 'Send Help', 'Sam Raimi', 'Rachel McAdams, Dylan O\'Brien, Edyll Ismail, Xavier Samuel, Dennis Haysbert, Chris Pang', 'Damian Shannon, Mark Swift', 'Horror, Thriller, Comedy', 2026, 'Raimi Productions, 20th Century Studios, TSG Entertainment', '113', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/zbJWVHOtj3ljBzWgL1P8pxP03Up.jpg', 'Two colleagues become stranded on a deserted island, the only survivors of a plane crash. On the island, they must overcome past grievances and work together to survive, but ultimately, it\'s a battle of wills and wits to make it out alive.'),
(1024, 490132, 'Green Book', 'Peter Farrelly', 'Viggo Mortensen, Mahershala Ali, Linda Cardellini, Sebastian Maniscalco, Dimiter D. Marinov, Mike Hatton', 'Peter Farrelly', 'Drama, Comedy, History', 2018, 'Participant, DreamWorks Pictures, Cinetic Media, Innisfree Pictures', '130', 4.1, 'US', 'English, Italiano, Pусский', 'https://image.tmdb.org/t/p/w500/7BsvSuDQuoqhWmU2fL7W2GOcZHU.jpg', 'Tony Lip, a bouncer in 1962, is hired to drive pianist Don Shirley on a tour through the Deep South in the days when African Americans, forced to find alternate accommodations and services due to segregation laws below the Mason-Dixon Line, relied on a guide called The Negro Motorist Green Book.'),
(1025, 314365, 'Spotlight', 'Tom McCarthy', 'Mark Ruffalo, Michael Keaton, Rachel McAdams, Liev Schreiber, John Slattery, Brian d\'Arcy James', 'Tom McCarthy', 'Drama, History', 2015, 'Participant, Anonymous Content, Rocklin / Faust, First Look Media, Open Road Films', '129', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/8DPGG400FgaFWaqcv11n8mRd2NG.jpg', 'The true story of how the Boston Globe uncovered the massive scandal of child molestation and cover-up within the local Catholic Archdiocese, shaking the entire Catholic Church to its core.'),
(1026, 687163, 'Project Hail Mary', 'Phil Lord', 'Ryan Gosling, Sandra Hüller, James Ortiz, Lionel Boyce, Milana Vayntrub, Ken Leung', 'Drew Goddard', 'Science Fiction, Adventure', 2026, 'Lord Miller, Amazon MGM Studios, Pascal Pictures, Open Invite Entertainment, Waypoint Entertainment', '157', 4.3, 'US', '普通话, English, 日本語, Pусский', 'https://image.tmdb.org/t/p/w500/yihdXomYb5kTeSivtFndMy5iDmf.jpg', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.'),
(1027, 654, 'On the Waterfront', 'Elia Kazan', 'Marlon Brando, Eva Marie Saint, Karl Malden, Lee J. Cobb, Rod Steiger, Pat Henning', 'Budd Schulberg', 'Crime, Drama, Romance', 1954, 'Columbia Pictures, Horizon Pictures', '108', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/v1RtJ1qR4v9nrnfoBVBl6hjTW9.jpg', 'A prizefighter-turned-longshoreman with a conscience goes up against labor leaders to expose corruption, extortion, and murder among the union ranks.'),
(1028, 9277, 'The Sting', 'George Roy Hill', 'Paul Newman, Robert Redford, Robert Shaw, Charles Durning, Ray Walston, Eileen Brennan', 'George Roy Hill', 'Comedy, Crime, Drama', 1973, 'Universal Pictures, The Zanuck/Brown Company, Bill/Phillips Productions', '129', 4.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/ckmYng37zey8INYf6d10cVgIG93.jpg', 'A novice con man teams up with an acknowledged master to avenge the murder of a mutual friend by pulling off the ultimate big con and swindling a fortune from a big-time mobster.'),
(1029, 524635, 'The Chronology of Water', 'Kristen Stewart', 'Imogen Poots, Thora Birch, Jim Belushi, Tom Sturridge, Earl Cave, Michael Epp', 'Kristen Stewart', 'Drama', 2025, 'Scott Free Productions, CG Cinéma, Forma Pro Films, Curious Gremlin, Fremantle, whiz movies, Lorem Ipsum, Scala Films, Nevermind, The Forge', '128', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/pU3GZI6C9lxzxUnBccIQLThDLVY.jpg', 'Plagued by an abusive childhood, a woman finds escape in competitive swimming, sexual experimentation, toxic relationships, and addiction before ultimately finding her voice through writing.');
INSERT INTO `peliculas` (`idPelicula`, `idApi`, `nombrePelicula`, `directorPelicula`, `actorPelicula`, `guionistaPelicula`, `generoPelicula`, `anoPelicula`, `companiaPelicula`, `duracionPelicula`, `ratingAvgPelicula`, `paisPelicula`, `idiomaPelicula`, `posterPelicula`, `sinopsisPelicula`) VALUES
(1030, 1401281, 'The Testament of Ann Lee', 'Mona Fastvold', 'Amanda Seyfried, Lewis Pullman, Thomasin McKenzie, Matthew Beard, Christopher Abbott, Viola Prettejohn', 'Mona Fastvold', 'History, Drama, Music', 2025, 'Mid March Media, Annapurna Pictures, FirstGen Content, Mizzel Media, Yintai Entertainment, Kaplan Morrison, Intake Films, Film i Väst, GötaFilm, Proton Cinema, ArtClass Films, Carte Blanche, The Launch Company', '137', 3.2, 'US', 'English', 'https://image.tmdb.org/t/p/w500/hBGg3IGRM7LM6ydMmDrl8mEx33Y.jpg', 'The extraordinary true legend of Ann Lee, founder of the devotional sect known as the Shakers, who preached gender and social equality and was revered by her followers as the female Christ.'),
(1031, 1159831, 'The Bride!', 'Maggie Gyllenhaal', 'Jessie Buckley, Christian Bale, Peter Sarsgaard, John Magaro, Jeannie Berlin, Annette Bening', 'Maggie Gyllenhaal', 'Science Fiction, Horror, Fantasy', 2026, 'First Love Films, Warner Bros. Pictures, In The Current Company, Domain Entertainment', '127', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/lV8YHwGkYZsm6EfIqnhaSz2avKt.jpg', 'A lonely Frankenstein travels to 1930s Chicago to ask groundbreaking scientist Dr. Euphronious to create a companion for him. The two revive a murdered young woman and The Bride is born. But what ensues is beyond what either of them imagined.'),
(1032, 12162, 'The Hurt Locker', 'Kathryn Bigelow', 'Jeremy Renner, Anthony Mackie, Brian Geraghty, David Morse, Guy Pearce, Evangeline Lilly', 'Kathryn Bigelow', 'Drama, Thriller, War', 2008, 'First Light, Kingsgate Films, Voltage Pictures, Summit Entertainment, Grosvenor Park Productions', '131', 3.6, 'US', 'English, العربية, Türkçe', 'https://image.tmdb.org/t/p/w500/io2dfBJhasvGbgkCX9cCGVOiA99.jpg', 'During the Iraq War, a Sergeant recently assigned to an army bomb squad is put at odds with his squad mates due to his maverick way of handling his work.'),
(1033, 1887, 'Marie Antoinette', 'Sofia Coppola', 'Kirsten Dunst, Jason Schwartzman, Steve Coogan, Judy Davis, Rip Torn, Asia Argento', 'Sofia Coppola', 'Drama, History', 2006, 'Pricel, Columbia Pictures, American Zoetrope, TFC', '123', 3.3, 'US', 'English, Français, Latin', 'https://image.tmdb.org/t/p/w500/cybXGmv8Rjd5Os8Xml6YxMBQ0Zt.jpg', 'A retelling of the story of France’s iconic but ill-fated queen, Marie Antoinette - from her betrothal and marriage to Louis XVI at fifteen to her reign as queen at nineteen and ultimately the fall of Versailles.'),
(1034, 74643, 'The Artist', 'Michel Hazanavicius', 'Jean Dujardin, Bérénice Bejo, John Goodman, James Cromwell, Penelope Ann Miller, Missi Pyle', 'Michel Hazanavicius', 'Drama, Comedy, Romance', 2011, 'uFilm, La Petite Reine, Studio 37, La Classe américaine, JD Prod, France 3 Cinéma, Jouror Productions', '100', 3.7, 'FR', 'No Language', 'https://image.tmdb.org/t/p/w500/xYMYV8lMIeQMymuNPBvq3hOnqXw.jpg', 'Hollywood, 1927: As silent movie star George Valentin wonders if the arrival of talking pictures will cause him to fade into oblivion, he sparks with Peppy Miller, a young dancer set for a big break.'),
(1035, 3084, 'Wuthering Heights', 'William Wyler', 'Merle Oberon, Laurence Olivier, David Niven, Flora Robson, Donald Crisp, Geraldine Fitzgerald', 'Ben Hecht, Charles MacArthur', 'Drama, Romance', 1939, 'Samuel Goldwyn Productions', '104', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/pwHdSzXwlUFAcYGcFutKcPcX2OW.jpg', 'Young orphan Heathcliff is adopted by the wealthy Earnshaw family and moves into their estate, Wuthering Heights. Soon, the new resident falls for his compassionate foster sister, Cathy. The two share a remarkable bond that seems unbreakable until Cathy, feeling the pressure of social convention, suppresses her feelings and marries Edgar Linton, a man of means who befits her stature. Heathcliff vows to win her back.'),
(1036, 3078, 'It Happened One Night', 'Frank Capra', 'Clark Gable, Claudette Colbert, Walter Connolly, Roscoe Karns, Jameson Thomas, Alan Hale', 'Robert Riskin', 'Comedy, Romance', 1934, 'Columbia Pictures', '105', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/2PNUGWAflH6UUumas0POMmokHlc.jpg', 'A runaway heiress makes a deal with the rogue reporter trailing her but the mismatched pair end up stuck with each other when their bus leaves them behind.'),
(1037, 322, 'Mystic River', 'Clint Eastwood', 'Sean Penn, Tim Robbins, Kevin Bacon, Laurence Fishburne, Marcia Gay Harden, Laura Linney', 'Brian Helgeland', 'Thriller, Drama, Mystery, Crime', 2003, 'Warner Bros. Pictures, Village Roadshow Pictures, NPV Entertainment, Malpaso Productions', '138', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/hCHVDbo6XJGj3r2i4hVjKhE0GKF.jpg', 'The lives of three men who were childhood friends are shattered when one of them suffers a family tragedy.'),
(1038, 30020, 'Taste of Cherry', 'Abbas Kiarostami', 'Homayoun Ershadi, Abdolrahman Bagheri, Safar Ali Moradi, Mir Hossein Noori, Elham Imani, Afshin Khorshid Bakhtiari', 'Abbas Kiarostami', 'Drama', 1997, 'Kanoon, Kiarostami Foundation, CiBy 2000', '99', 3.9, 'IR', 'فارسی', 'https://image.tmdb.org/t/p/w500/vgPwjgbSdbYWrS1ty8TIZtmi6Tn.jpg', 'A middle-aged Tehranian man, Mr. Badii is intent on killing himself and seeks someone to bury him after his demise. Driving around the city, the seemingly well-to-do Badii meets with numerous people, including a Muslim student, asking them to take on the job, but initially he has little luck. Eventually, Badii finds a man who is up for the task because he needs the money, but his new associate soon tries to talk him out of committing suicide.'),
(1039, 1480387, 'undertone', 'Ian Tuason', 'Nina Kiri, Adam DiMarco, Keana Bastidas, Jeff Yung, Michèle Duquet, Ryan Turner', 'Ian Tuason', 'Horror, Mystery', 2026, 'Black Fawn Films, Slaterverse Pictures, KINO Studios, Spooky Pictures, DimensionGate, Feel Everything Productions', '94', 3.0, 'CA, US', 'English', 'https://image.tmdb.org/t/p/w500/2PFgFMnrdCPXWiZl1PUvky7Mo9D.jpg', 'The host of a popular paranormal podcast becomes haunted by terrifying recordings mysteriously sent her way.'),
(1040, 1327819, 'Hoppers', 'Daniel Chong', 'Piper Curda, Bobby Moynihan, Jon Hamm, Kathy Najimy, Dave Franco, Eduardo Franco', 'Jesse Andrews', 'Adventure, Animation, Comedy, Family, Science Fiction', 2026, 'Pixar', '104', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/xjtWQ2CL1mpmMNwuU5HeS4Iuwuu.jpg', 'Scientists have discovered how to \'hop\' human consciousness into lifelike robotic animals, allowing people to communicate with animals as animals. Animal lover Mabel seizes an opportunity to use the technology, uncovering mysteries within the animal world beyond anything she could have imagined.'),
(1041, 1292695, 'They Will Kill You', 'Kirill Sokolov', 'Zazie Beetz, Myha\'la, Paterson Joseph, Tom Felton, Heather Graham, Patricia Arquette', 'Kirill Sokolov', 'Action, Comedy, Horror, Thriller', 2026, 'Nocturna, New Line Cinema, Domain Entertainment, Film Afrika', '95', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/6oI4oQKTWMVUlr8Ivqydp28Ruu6.jpg', 'A woman answers a help wanted ad to be a housekeeper in a mysterious New York City high-rise, unaware that she is entering a community that has seen a number of disappearances over the years and may be under the grip of a Satanic cult.'),
(1042, 350, 'The Devil Wears Prada', 'David Frankel', 'Meryl Streep, Anne Hathaway, Emily Blunt, Stanley Tucci, Simon Baker, Adrian Grenier', 'Aline Brosh McKenna', 'Drama, Comedy', 2006, 'Fox 2000 Pictures, Wendy Finerman Productions, Dune Entertainment, Major Studio Partners', '109', 3.7, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/8912AsVuS7Sj915apArUFbv6F9L.jpg', 'A young woman from the Midwest gets more than she bargained for when she moves to New York to become a writer and ends up as the assistant to the tyrannical, larger-than-life editor-in-chief of a major fashion magazine.'),
(1043, 11113, 'My Fair Lady', 'George Cukor', 'Audrey Hepburn, Rex Harrison, Stanley Holloway, Wilfrid Hyde-White, Gladys Cooper, Jeremy Brett', 'Alan Jay Lerner', 'Comedy, Romance, Music', 1964, 'Warner Bros. Pictures', '173', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/bTXVc29lGSNclf94VIZ49W4gGKl.jpg', 'A snobbish phonetics professor agrees to a wager that he can take a flower girl and make her presentable in high society.'),
(1044, 8966, 'Twilight', 'Catherine Hardwicke', 'Kristen Stewart, Robert Pattinson, Billy Burke, Peter Facinelli, Ashley Greene, Jackson Rathbone', 'Melissa Rosenberg', 'Fantasy, Drama, Romance', 2008, 'Summit Entertainment, Temple Hill Entertainment, Maverick Films, Imprint Entertainment, Goldcrest, Aura Films', '122', 3.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg', 'When Bella Swan moves to a small town in the Pacific Northwest, she falls in love with Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward\'s repeated cautions, Bella can\'t stay away from him, a fatal move that endangers her own life.'),
(1045, 1325734, 'The Drama', 'Kristoffer Borgli', 'Zendaya, Robert Pattinson, Alana Haim, Mamoudou Athie, Hailey Benton Gates, Sydney Lemmon', 'Kristoffer Borgli', 'Romance, Comedy, Drama', 2026, 'A24, Square Peg, Dilemma Films', '105', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/rnIOUhzwJDfgQakx8EjoNyItKgs.jpg', 'A happily engaged couple is put to the test when an unexpected turn sends their wedding week off the rails.'),
(1046, 1314481, 'The Devil Wears Prada 2', 'David Frankel', 'Anne Hathaway, Meryl Streep, Emily Blunt, Stanley Tucci, Kenneth Branagh, Justin Theroux', 'David Frankel', 'Comedy, Drama', 2026, '20th Century Studios, Wendy Finerman Productions', '119', 3.5, 'US', 'English, Italiano', 'https://image.tmdb.org/t/p/w500/xTI42pmsP5EDnvsNJPEDubwWBQO.jpg', 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway\'s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway\'s survival.'),
(1047, 1266127, 'Ready or Not: Here I Come', 'Matt Bettinelli-Olpin', 'Samara Weaving, Kathryn Newton, Sarah Michelle Gellar, Shawn Hatosy, Nestor Carbonell, David Cronenberg', 'Matt Bettinelli-Olpin, Tyler Gillett', 'Horror, Comedy', 2026, 'Searchlight Pictures, Mythology Entertainment, Radio Silence, Big Indie Pictures, Vinson Films', '108', 3.8, 'US', 'Español, English, 普通话', 'https://image.tmdb.org/t/p/w500/jRf89HVEtBZiSnOXXWDhZOfuTwW.jpg', 'Moments after surviving an all-out attack from the Le Domas family, Grace discovers she’s reached the next level of the nightmarish game — and this time with her estranged sister Faith at her side. Grace has one chance to survive, keep her sister alive, and claim the High Seat of the Council that controls the world. Four rival families are hunting her for the throne, and whoever wins rules it all.'),
(1048, 1171145, 'Crime 101', 'Bart Layton', 'Chris Hemsworth, Mark Ruffalo, Halle Berry, Barry Keoghan, Monica Barbaro, Nick Nolte', 'Bart Layton', 'Crime, Thriller', 2026, 'Working Title Films, The Story Factory, RAW, Amazon MGM Studios, Wild State', '141', 3.5, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/tVvpFIoteRHNnoZMhdnwIVwJpCA.jpg', 'When an elusive thief whose high-stakes heists unfold along the iconic 101 freeway in Los Angeles eyes the score of a lifetime, with hopes of this being his final job, his path collides with a disillusioned insurance broker who is facing her own crossroads. Determined to crack the case, a relentless detective closes in on the operation, raising the stakes even higher.'),
(1049, 60243, 'A Separation', 'Asghar Farhadi', 'Leila Hatami, Payman Maadi, Sareh Bayat, Sarina Farhadi, Shahab Hosseini, Kimia Hosseini', 'Asghar Farhadi', 'Drama', 2011, 'Asghar Farhadi Productions, Memento Production', '123', 4.0, 'IR', 'فارسی', 'https://image.tmdb.org/t/p/w500/xQadpnoLokxzN3hRpCPbBGpxsiz.jpg', 'A married couple are faced with a difficult decision - to improve the life of their child by moving to another country or to stay in Iran and look after a deteriorating parent who has Alzheimer\'s disease.'),
(1050, 334, 'Magnolia', 'Paul Thomas Anderson', 'Tom Cruise, Philip Baker Hall, Philip Seymour Hoffman, Julianne Moore, William H. Macy, John C. Reilly', 'Paul Thomas Anderson', 'Drama', 1999, 'New Line Cinema, Ghoulardi Film Company', '189', 3.9, 'US', 'English, Français, Deutsch', 'https://image.tmdb.org/t/p/w500/tpfC325Jk6S38VTe5dDWjWtoyxr.jpg', 'On one random day in the San Fernando Valley, a dying father, a young wife, a male caretaker, a famous lost son, a police officer in love, a boy genius, an ex-boy genius, a game show host and an estranged daughter will each become part of a dazzling multiplicity of plots, but one story.'),
(1051, 502033, 'Sound of Metal', 'Darius Marder', 'Riz Ahmed, Olivia Cooke, Paul Raci, Lauren Ridloff, Mathieu Amalric, Domenico Toledo', 'Darius Marder, Abraham Marder', 'Drama, Music', 2020, 'Flat 7, Ward Four, Caviar', '121', 3.9, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/3178oOJKKPDeQ2legWQvMPpllv.jpg', 'Metal drummer Ruben begins to lose his hearing. When a doctor tells him his condition will worsen, he thinks his career and life is over. His girlfriend Lou checks the former addict into a rehab for the deaf hoping it will prevent a relapse and help him adapt to his new life. After being welcomed and accepted just as he is, Ruben must choose between his new normal and the life he once knew.'),
(1052, 8052, 'Hard Eight', 'Paul Thomas Anderson', 'Philip Baker Hall, John C. Reilly, Gwyneth Paltrow, Samuel L. Jackson, F. William Parker, Philip Seymour Hoffman', 'Paul Thomas Anderson', 'Drama, Crime', 1997, 'Trinity Filmed Entertainment, Rysher Entertainment, Green Parrot', '102', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/1l5UaoP25Ak8PWCKIULQz70yF03.jpg', 'A stranger mentors a young Reno gambler who weds a hooker and befriends a vulgar casino regular.'),
(1053, 1304313, 'Lee Cronin\'s The Mummy', 'Lee Cronin', 'Jack Reynor, Laia Costa, May Calamawy, Natalie Grace, Shylo Molina, Billie Roy', 'Lee Cronin', 'Horror, Mystery', 2026, 'Atomic Monster, Blumhouse Productions, New Line Cinema, Domain Entertainment, Wicked/Good, Wild Atlantic Pictures', '133', 4.0, 'IE, US', 'العربية, English, Español', 'https://image.tmdb.org/t/p/w500/1q308iixueCU4pFtSYugNOevtNx.jpg', 'The young daughter of a journalist disappears into the desert without a trace—eight years later, the broken family is shocked when she is returned to them, as what should be a joyful reunion turns into a living nightmare.'),
(1054, 4995, 'Boogie Nights', 'Paul Thomas Anderson', 'Mark Wahlberg, Burt Reynolds, Julianne Moore, John C. Reilly, Heather Graham, Don Cheadle', 'Paul Thomas Anderson', 'Drama, Comedy', 1997, 'New Line Cinema, Lawrence Gordon Productions, Ghoulardi Film Company', '156', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/wnE24UPCPQsQnbBOu4zVE2qaDNm.jpg', 'In 1977, an idealistic porn producer and his promising protege try to catch up with the end of an era before their never-ending party collides with cold, hard reality.'),
(1055, 1226863, 'The Super Mario Galaxy Movie', 'Michael Jelenic', 'Chris Pratt, Charlie Day, Anya Taylor-Joy, Jack Black, Keegan-Michael Key, Donald Glover', 'Matthew Fogel', 'Family, Comedy, Adventure, Fantasy, Animation', 2026, 'Illumination, Universal Pictures, Nintendo', '98', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/eJGWx219ZcEMVQJhAgMiqo8tYY.jpg', 'Having thwarted Bowser\'s previous plot to marry Princess Peach, Mario and Luigi now face a fresh threat in Bowser Jr., who is determined to liberate his father from captivity and restore the family legacy. Alongside companions new and old, the brothers travel across the stars to stop the young heir\'s crusade.'),
(1056, 8051, 'Punch-Drunk Love', 'Paul Thomas Anderson', 'Adam Sandler, Emily Watson, Philip Seymour Hoffman, Luis Guzmán, Mary Lynn Rajskub, Robert Smigel', 'Paul Thomas Anderson', 'Romance, Drama, Comedy', 2002, 'Revolution Studios, New Line Cinema, JoAnne Sellar Productions, Ghoulardi Film Company', '96', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/htYp4yqFu4rzBEIa6j9jP8miDm3.jpg', 'A socially awkward and volatile small business owner meets the love of his life after being threatened by a gang of scammers.'),
(1057, 1307373, 'Wasteman', 'Cal McMau', 'David Jonsson, Tom Blyth, Alex Hassell, Neil Linpow, Paul Hilton, Corin Silva', 'Eoin Doran, Hunter Andrews', 'Crime, Drama, Thriller', 2026, 'Bankside Films, Hoopsa Films, Agile Films, It\'s All Made Up Productions', '91', 3.7, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/lKK9ImwpoTCwDZKgYpjIIJCnlf0.jpg', 'Taylor\'s hopes for a fresh start post-parole are jeopardised by cellmate Dee\'s arrival. As Dee takes Taylor under his wing, a vicious attack tests their bond, forcing Taylor to choose between protecting Dee and his own chances at freedom.'),
(1058, 171274, 'Inherent Vice', 'Paul Thomas Anderson', 'Joaquin Phoenix, Josh Brolin, Owen Wilson, Katherine Waterston, Reese Witherspoon, Benicio del Toro', 'Paul Thomas Anderson', 'Drama, Mystery, Comedy', 2014, 'Warner Bros. Pictures, IAC Films, JoAnne Sellar Productions, Ghoulardi Film Company, RatPac Entertainment', '149', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/pfVua7TzzttOh3RTOuBqT7xN0oY.jpg', 'In Los Angeles at the turn of the 1970s, drug-fueled detective Larry \"Doc\" Sportello investigates the disappearance of an ex-girlfriend.'),
(1059, 467938, 'Revenge', 'Coralie Fargeat', 'Matilda Lutz, Kevin Janssens, Vincent Colombe, Guillaume Bouchède, Jean-Louis Tribes, Barbara Gateau', 'Coralie Fargeat', 'Action, Horror, Thriller, Drama', 2017, 'M.E.S. Productions, Monkey Pack Films, Charades, Logical Pictures, Nexus Factory, uMedia', '108', 3.3, 'FR', 'English, Français', 'https://image.tmdb.org/t/p/w500/dWXjUGwpwGWWevcnpPuf5QGpKMw.jpg', 'Jen\'s romantic getaway with her wealthy married boyfriend is disrupted when his friends arrive for an impromptu hunting trip. Tension mounts at the house until the situation culminates in an unexpected way.'),
(1060, 320, 'Insomnia', 'Christopher Nolan', 'Al Pacino, Robin Williams, Hilary Swank, Maura Tierney, Martin Donovan, Nicky Katt', 'Hillary Seitz', 'Thriller, Crime, Drama', 2002, 'Alcon Entertainment, Witt/Thomas Productions, Section Eight', '118', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/riVXh3EimGO0y5dgQxEWPRy5Itg.jpg', 'Two Los Angeles homicide detectives are dispatched to a northern town where the sun doesn\'t set to investigate the methodical murder of a local teen.'),
(1061, 77, 'Memento', 'Christopher Nolan', 'Guy Pearce, Carrie-Anne Moss, Joe Pantoliano, Mark Boone Junior, Russ Fega, Jorja Fox', 'Christopher Nolan', 'Mystery, Thriller', 2000, 'Newmarket Films, Summit Entertainment, Team Todd, I Remember Productions', '113', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/nzlv62aC0octS5AklAiWpXLX9Z0.jpg', 'Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife\'s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he\'s going, or why.'),
(1062, 11660, 'Following', 'Christopher Nolan', 'Jeremy Theobald, Alex Haw, Lucy Russell, John Nolan, Dick Bradsell, Gillian El-Kadi', 'Christopher Nolan', 'Drama, Thriller', 1999, 'Next Wave Films, Syncopy', '69', 3.6, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/3bX6VVSMf0dvzk5pMT4ALG5A92d.jpg', 'Bill, an idle, unemployed aspiring writer, walks the crowded streets of London following randomly chosen strangers, a seemingly innocent entertainment that becomes dangerous when he crosses paths with a mysterious character.'),
(1063, 9552, 'The Exorcist', 'William Friedkin', 'Ellen Burstyn, Linda Blair, Jason Miller, Max von Sydow, Lee J. Cobb, William O\'Malley', 'William Peter Blatty', 'Horror', 1973, 'Hoya Productions, Warner Bros. Pictures', '122', 3.9, 'US', 'Deutsch, Français, Latin, العربية, ελληνικά, English', 'https://image.tmdb.org/t/p/w500/5x0CeVHJI8tcDx8tUUwYHQSNILq.jpg', 'When a mysterious entity possesses a young girl, her mother seeks the help of two Catholic priests to save her life.'),
(1065, 780, 'The Passion of Joan of Arc', 'Carl Theodor Dreyer', 'Maria Falconetti, Eugène Silvain, André Berley, Maurice Schutz, Antonin Artaud, Michel Simon', 'Carl Theodor Dreyer', 'Drama, History', 1928, 'Société générale des films', '81', 4.0, 'FR', 'No Language', 'https://image.tmdb.org/t/p/w500/tAgV9yxY6AC1bsPt3qJJQpD4s8.jpg', 'A classic of the silent age, this film tells the story of the doomed but ultimately canonized 15th-century teenage warrior. On trial for claiming she\'d spoken to God, Jeanne d\'Arc is subjected to inhumane treatment and scare tactics at the hands of church court officials. Initially bullied into changing her story, Jeanne eventually opts for what she sees as the truth. Her punishment, a famously brutal execution, earns her perpetual martyrdom.'),
(1066, 22302, 'Polytechnique', 'Denis Villeneuve', 'Maxim Gaudette, Sébastien Huberdeau, Karine Vanasse, Evelyne Brochu, Martin Watier, Johanne-Marie Tremblay', 'Denis Villeneuve', 'Crime, Drama, Thriller', 2009, 'Don Carmody Productions, Remstar Productions', '77', 3.6, 'CA', 'Français', 'https://image.tmdb.org/t/p/w500/bmIhSm9GN1BR0srtjLCEGsAxQqF.jpg', 'A dramatization of the  École Polytechnique massacre in Montreal, on December 9, 1989, where 14 female engineering students were murdered (and 13 were wounded) by a 25 year old psychotic misogynist armed with a semi-automatic weapon.'),
(1067, 324807, 'A Bigger Splash', 'Luca Guadagnino', 'Tilda Swinton, Matthias Schoenaerts, Ralph Fiennes, Dakota Johnson, Corrado Guzzanti, Alessandro Ferrara', 'David Kajganich', 'Drama, Thriller, Romance', 2015, 'Frenesy Film, StudioCanal, COTA Films', '125', 3.1, 'IT', 'English, Français, Italiano', 'https://image.tmdb.org/t/p/w500/b9ca2L41R43Lg1hpSzJHwtDTvYU.jpg', 'An American couple, Paul and Marianne, spend their vacation in Italy and experience trouble when Marianne invites a former lover and his teenage daughter to visit, which leads to jealousy and dangerous sexual scenarios.'),
(1068, 631, 'Sunrise: A Song of Two Humans', 'F. W. Murnau', 'George O\'Brien, Janet Gaynor, Margaret Livingston, Bodil Rosing, J. Farrell MacDonald, Ralph Sipperly', 'Carl Mayer', 'Drama, Romance', 1927, 'Fox Film Corporation', '94', 3.9, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/5V9jDm4u2QemGHbqjUyP5HmFmzf.jpg', 'A married farmer falls under the spell of a slatternly woman from the city, who tries to convince him to drown his wife.'),
(1069, 1430077, 'Hokum', 'Damian McCarthy', 'Adam Scott, Peter Coonan, David Wilmot, Florence Ordesh, Michael Patric, Will O\'Connell', 'Damian McCarthy', 'Horror', 2026, 'Spooky Pictures, Image Nation Abu Dhabi, Cweature Features, Team Thrives, Tailored Films, Fís Éireann/Screen Ireland', '108', 3.5, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/x6rHcQFiYcczLQPrmxXPAicm54E.jpg', 'When novelist Ohm Bauman retreats to a remote inn to scatter his parents\' ashes, he is consumed by tales of a witch haunting the honeymoon suite. Disturbing visions and a shocking disappearance forces him to confront dark corners of his past.'),
(1070, 643, 'Battleship Potemkin', 'Sergei Eisenstein', 'Aleksandr Antonov, Vladimir Barsky, Grigori Aleksandrov, Ivan Bobrov, Mikhail Gomorov, Aleksandr Levshin', 'Sergei Eisenstein', 'Drama, History, War', 1925, 'Mosfilm', '75', 3.8, 'SU', 'No Language', 'https://image.tmdb.org/t/p/w500/hZmsRLsCnE9Zshf1YJONUpCOhds.jpg', 'A dramatized account of a great Russian naval mutiny and a resultant public demonstration, showing support, which brought on a police massacre.'),
(1071, 234, 'The Cabinet of Dr. Caligari', 'Robert Wiene', 'Werner Krauss, Conrad Veidt, Friedrich Fehér, Lil Dagover, Hans Heinrich von Twardowski, Rudolf Lettinger', 'Hans Janowitz, Carl Mayer', 'Drama, Horror, Thriller, Crime', 1920, 'Decla Film Gesellschaft Holz & Co.', '77', 4.0, 'DE', 'No Language', 'https://image.tmdb.org/t/p/w500/myK9DeIsXWGKgUTZyGXg2IfFk0W.jpg', 'Francis, a young man, recalls in his memory the horrible experiences he and his fiancée Jane recently went through. Francis and his friend Alan visit The Cabinet of Dr. Caligari, an exhibit where the mysterious doctor shows the somnambulist Cesare, and awakens him for some moments from his death-like sleep.'),
(1072, 59436, 'Midnight in Paris', 'Woody Allen', 'Owen Wilson, Rachel McAdams, Kathy Bates, Kurt Fuller, Adrien Brody, Carla Bruni', 'Woody Allen', 'Fantasy, Comedy, Romance', 2011, 'Mediapro, Versátil Cinema, Pontchartrain Productions, Gravier Productions', '94', 3.8, 'US', 'English, Français, Deutsch, Español', 'https://image.tmdb.org/t/p/w500/4wBG5kbfagTQclETblPRRGihk0I.jpg', 'While on a trip to Paris with his fiancée\'s family, a nostalgic screenwriter finds himself mysteriously going back to the 1920s every day at midnight.'),
(1073, 992, 'Sherlock Jr.', 'Buster Keaton', 'Buster Keaton, Kathryn McGuire, Joe Keaton, Erwin Connelly, Ward Crane, Doris Deane', 'Clyde Bruckman', 'Action, Comedy, Mystery', 1924, 'Metro Pictures Corporation, Buster Keaton Productions', '45', 4.0, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/1G9r3rqtbFAQuyWKOZm4Y5J5s7Q.jpg', 'A film projectionist longs to be a detective, and puts his meager skills to work when he is framed by a rival for stealing his girlfriend\'s father\'s pocketwatch.'),
(1074, 10098, 'The Kid', 'Charlie Chaplin', 'Charlie Chaplin, Jackie Coogan, Carl Miller, Edna Purviance, Albert Austin, Beulah Bains', 'Charlie Chaplin', 'Comedy, Drama', 1921, 'Charles Chaplin Productions', '68', 4.1, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/A9NWYyn7eX0H9XIjaOvfWJ9mCGA.jpg', 'A tramp cares for a boy after he\'s abandoned as a newborn by his mother. Later the mother has a change of heart and aches to be reunited with her son.'),
(1075, 962, 'The Gold Rush', 'Charlie Chaplin', 'Charlie Chaplin, Mack Swain, Tom Murray, Henry Bergman, Malcolm Waite, Georgia Hale', 'Charlie Chaplin', 'Adventure, Comedy, Drama', 1925, 'Charles Chaplin Productions', '95', 4.0, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/eQRFo1qwRREYwj47Yoe1PisgOle.jpg', 'A gold prospector in Alaska struggles to survive the elements and win the heart of a dance hall girl.'),
(1076, 1598, 'Cape Fear', 'Martin Scorsese', 'Robert De Niro, Nick Nolte, Jessica Lange, Juliette Lewis, Joe Don Baker, Robert Mitchum', 'Wesley Strick', 'Drama, Crime, Thriller', 1991, 'Amblin Entertainment, Cappa Productions, Tribeca Productions, Universal Pictures', '128', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/meJZAAuVcjic2ipvbOPz5UlE4P9.jpg', 'Sam Bowden is a small-town corporate attorney. Max Cady is a tattooed, cigar-smoking, Bible-quoting, psychotic rapist. What do they have in common? 14 years ago, Sam was a public defender assigned to Max Cady\'s rape trial, and he made a serious error: he hid a document from his illiterate client that could have gotten him acquitted. Now, the cagey Cady has been released, and he intends to teach Sam Bowden and his family a thing or two about loss.'),
(1077, 1275779, 'Disclosure Day', 'Steven Spielberg', 'Emily Blunt, Josh O\'Connor, Colin Firth, Eve Hewson, Colman Domingo, Wyatt Russell', 'David Koepp', 'Science Fiction, Thriller', 2026, 'Universal Pictures, Amblin Entertainment', '146', 3.7, 'US', 'English, Pусский, 한국어/조선말', 'https://image.tmdb.org/t/p/w500/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', 'A cybersecurity expert becomes a whistleblower after uncovering secrets about aliens, putting him on the run from a corporation. Meanwhile, a meteorologist experiencing strange phenomena joins forces with him to prove there\'s life beyond our understanding.'),
(1078, 72976, 'Lincoln', 'Steven Spielberg', 'Daniel Day-Lewis, Sally Field, David Strathairn, Joseph Gordon-Levitt, James Spader, Hal Holbrook', 'Tony Kushner', 'History, Drama', 2012, 'DreamWorks Pictures, Reliance Entertainment, Participant, Amblin Entertainment, The Kennedy/Marshall Company, Dune Entertainment, 20th Century Fox', '150', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/7mUYEkv9W3ek61eetZCfMQYVoi.jpg', 'The revealing story of the 16th US President\'s tumultuous final months in office. In a nation divided by war and the strong winds of change, Lincoln pursues a course of action designed to end the war, unite the country and abolish slavery. With the moral courage and fierce determination to succeed, his choices during this critical moment will change the fate of generations to come.'),
(1079, 229, 'Bride of Frankenstein', 'James Whale', 'Boris Karloff, Colin Clive, Valerie Hobson, Ernest Thesiger, Elsa Lanchester, Gavin Gordon', 'Edmund Pearson, William Hurlbut', 'Horror, Science Fiction', 1935, 'Universal Pictures, James Whale Productions', '75', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/5241zUwe7rC17MNc2QpCBKKdp1N.jpg', 'Dr. Frankenstein and his monster both turn out to be alive after being attacked by an angry mob. The now-chastened scientist attempts to escape his past, but a former mentor forces him to assist with the creation of a new creature.'),
(1080, 832, 'M', 'Fritz Lang', 'Peter Lorre, Ellen Widmann, Inge Landgut, Otto Wernicke, Theodor Loos, Gustaf Gründgens', 'Thea von Harbou, Fritz Lang', 'Drama, Thriller, Crime', 1931, 'Nero-Film AG', '110', 4.0, 'DE', 'Deutsch', 'https://image.tmdb.org/t/p/w500/bTdZk3q2DWpBRnLiaaItKFWOVhI.jpg', 'In this classic German thriller, Hans Beckert, a serial killer who preys on children, becomes the focus of a massive Berlin police manhunt. Beckert\'s heinous crimes are so repellant and disruptive to city life that he is even targeted by others in the seedy underworld network. With both cops and criminals in pursuit, the murderer soon realizes that people are on his trail, sending him into a tense, panicked attempt to escape justice.'),
(1081, 1318413, 'Pressure', 'Anthony Maras', 'Andrew Scott, Brendan Fraser, Kerry Condon, Chris Messina, Damian Lewis, Tamsin Topolski', 'Anthony Maras', 'Thriller, History, War', 2026, 'Working Title Films, StudioCanal UK, StudioCanal', '101', 3.9, 'GB', 'English, Deutsch', 'https://image.tmdb.org/t/p/w500/gFjEggtrejCN79r6SXRjM269OtG.jpg', 'In the tense 72 hours before D-Day, and the fate of the free world hanging in the balance, General Dwight D. Eisenhower and Captain James Stagg face an impossible choice—launch the largest and most dangerous seaborne invasion in history or risk losing the war altogether.'),
(1082, 961, 'The General', 'Clyde Bruckman', 'Buster Keaton, Marion Mack, Glen Cavender, Jim Farley, Frederick Vroom, Frank Barnes', 'Buster Keaton, Clyde Bruckman', 'Comedy, War, Romance', 1926, 'Joseph M. Schenck Productions, Buster Keaton Productions', '79', 4.0, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/nIp4gIXogCjfB1QABNsWwa9gSca.jpg', 'During America’s Civil War, Union spies steal engineer Johnny Gray\'s beloved locomotive, \'The General\'—with Johnnie\'s lady love aboard an attached boxcar—and he single-handedly must do all in his power to both get The General back and to rescue Annabelle.'),
(1083, 71, 'Billy Elliot', 'Stephen Daldry', 'Jamie Bell, Gary Lewis, Julie Walters, Jean Heywood, Jamie Draven, Stuart Wells', 'Stephen Daldry', 'Drama, Comedy, Music', 2000, 'StudioCanal, BBC Film, Tiger Aspect, Arts Council of England, Working Title Films, WT² Productions, Universal Pictures', '111', 3.8, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/mYtqgWCJiXpDeZwjVcC3OQGD8IR.jpg', 'County Durham, England, 1984. The miners\' strike has started and the police have started coming up from Bethnal Green, starting a class war with the lower classes suffering. Caught in the middle of the conflict is 11-year old Billy Elliot, who, after leaving his boxing club for the day, stumbles upon a ballet class and finds out that he\'s naturally talented. He practices with his teacher Mrs. Wilkinson for an upcoming audition in Newcastle-upon Tyne for the royal Ballet school in London.'),
(1084, 25768, 'Steamboat Bill, Jr.', 'Charles Reisner', 'Buster Keaton, Tom McGuire, Ernest Torrence, Tom Lewis, Marion Byron, James T. Mack', 'Buster Keaton', 'Comedy, Romance', 1928, 'Buster Keaton Productions, Joseph M. Schenck Productions', '70', 3.8, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/zygJMsmXxeyDc1N67OCZc8xtq4I.jpg', 'The just-out-of-college, effete son of a no-nonsense steamboat captain comes to visit his father whom he\'s not seen since he was a child.'),
(1085, 1301421, 'The Sheep Detectives', 'Kyle Balda', 'Hugh Jackman, Nicholas Braun, Nicholas Galitzine, Molly Gordon, Julia Louis-Dreyfus, Bryan Cranston', 'Craig Mazin', 'Comedy, Family, Mystery', 2026, 'Working Title Films, Three Strange Angels, Amazon MGM Studios', '109', 4.0, 'GB, US', 'English', 'https://image.tmdb.org/t/p/w500/mGWOmj2jHFol3kOGNv1EhbSDDE1.jpg', 'George Hardy is a shepherd who reads detective novels to his beloved sheep every night, assuming they can\'t possibly understand. But when a mysterious incident disrupts life on the farm, the sheep realize they must become the detectives. As they follow the clues and investigate human suspects, they prove that even sheep can be brilliant crime-solvers.'),
(1086, 31411, 'The Cameraman', 'Edward Sedgwick', 'Buster Keaton, Marceline Day, Harold Goodwin, Sidney Bracey, Harry Gribbon, Ray Cooke', 'Edward Sedgwick', 'Comedy, Romance, Drama', 1928, 'Metro-Goldwyn-Mayer', '74', 3.9, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/oz7dVRzxN95IIpa7hsG5XS3nO2L.jpg', 'A photographer takes up newsreel shooting to impress a secretary.'),
(1087, 28978, 'The Circus', 'Charlie Chaplin', 'Charlie Chaplin, Al Ernest Garcia, Merna Kennedy, Harry Crocker, George Davis, Henry Bergman', 'Charlie Chaplin', 'Comedy, Romance, Drama', 1928, 'Charles Chaplin Productions', '72', 4.0, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/sihWAgBYa8yZFVAonGFGbLTVUj2.jpg', 'Charlie, a wandering tramp, becomes a circus handyman - soon the star of the show - and falls in love with the circus owner\'s stepdaughter.'),
(1088, 1339713, 'Obsession', 'Curry Barker', 'Michael Johnston, Inde Navarrette, Cooper Tomlinson, Megan Lawless, Andy Richter, Haley Fitzgerald', 'Curry Barker', 'Horror, Thriller', 2026, 'Tea Shop Productions, Under the Shell, Capstone Pictures, Blumhouse Productions', '109', 4.1, 'US', 'English', 'https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', 'After breaking the mysterious \"One Wish Willow\" to win his crush\'s heart, a hopeless romantic finds himself getting exactly what he asked for but soon discovers that some desires come at a dark, sinister price.'),
(1089, 70, 'Million Dollar Baby', 'Clint Eastwood', 'Clint Eastwood, Hilary Swank, Morgan Freeman, Jay Baruchel, Mike Colter, Lucia Rijker', 'Paul Haggis', 'Drama', 2004, 'Lakeshore Entertainment, Malpaso Productions, Epsilon Motion Pictures, Albert S. Ruddy Productions, Warner Bros. Pictures', '132', 4.0, 'US', 'English, Gaeilge', 'https://image.tmdb.org/t/p/w500/jcfEqKdWF1zeyvECPqp3mkWLct2.jpg', 'Despondent over a painful estrangement from his daughter, trainer Frankie Dunn isn\'t prepared for boxer Maggie Fitzgerald to enter his life. But Maggie\'s determined to go pro and to convince Dunn and his cohort to help her.'),
(1090, 48035, 'Ordet', 'Carl Theodor Dreyer', 'Henrik Malberg, Birgitte Federspiel, Emil Hass Christensen, Preben Lerdorff Rye, Cay Kristiansen, Ejner Federspiel', 'Carl Theodor Dreyer', 'Drama', 1955, 'Palladium', '125', 4.0, 'DK', 'Dansk', 'https://image.tmdb.org/t/p/w500/c9Oef9uQEuadZlnvv8hphRmTIgx.jpg', 'The three sons of devout Danish farmer Morten have widely disparate religious beliefs. Youngest son Anders shares his father\'s religion, but eldest son Mikkel has lost his faith, while middle child Johannes has become delusional and proclaims that he is Jesus Christ himself. When Mikkel\'s wife, Inger goes into a difficult childbirth, everyone\'s beliefs are put to the test.'),
(1091, 901, 'City Lights', 'Charlie Chaplin', 'Charlie Chaplin, Virginia Cherrill, Florence Lee, Harry Myers, Al Ernest Garcia, Hank Mann', 'Charlie Chaplin, Harry Crocker, Harry Carr', 'Comedy, Drama, Romance', 1931, 'Charles Chaplin Productions', '87', 4.1, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/ugmakEL5y294I5bXgiBqApuZpwc.jpg', 'A tramp falls in love with a beautiful blind flower girl. His on-and-off friendship with a wealthy man allows him to be the girl\'s benefactor and suitor.'),
(1092, 1280738, 'The Furious', 'Kenji Tanigaki', 'Xie Miao, Joe Taslim, Yang Enyou, Yayan Ruhian, JeeJa Yanin, Brian Le', 'Shum Kwan-Sin, Frank Hui, Mak Tin-Shu', 'Action, Crime, Thriller', 2026, 'Edko Films, XYZ Films, Zhejiang Hengdian Film Production', '114', 3.7, 'CN, HK', 'English, Bahasa indonesia, 普通话, , ภาษาไทย', 'https://image.tmdb.org/t/p/w500/zP19YO60jwEsfKd5Qf1UvA5uJu8.jpg', 'After a criminal network kidnaps Wang Wei\'s daughter and the corrupt police refuse to assist him, Wei sets out on his own to locate her. Navin, a tenacious journalist whose wife has mysteriously vanished, is his only ally. In this explosive martial arts showdown, the unlikely duo fights the kidnappers ruthlessly driven by a furious vengeance.'),
(1093, 81857, 'Alps', 'Yorgos Lanthimos', 'Angeliki Papoulia, Aris Servetalis, Johnny Vekris, Ariane Labed, Stavros Psyllakis, Efthimis Filippou', 'Yorgos Lanthimos, Efthimis Filippou', 'Drama', 2011, 'Haos Film, Queen Street Partners, Faliro House Productions, Feelgood Entertainment, Nova, Marni Films, Avion Films, Cactus Three, Maharaja Films', '94', 3.1, 'GR', 'ελληνικά, English', 'https://image.tmdb.org/t/p/w500/nF5A64lC0MuuEK6qNmOfQpY6mRv.jpg', 'A nurse, a paramedic, a gymnast and her coach offer a service for hire wherein they stand in for dead people by appointment, hired by relatives, friends or colleagues of the deceased, to assist with the grieving process.'),
(1094, 94329, 'The Raid', 'Gareth Evans', 'Iko Uwais, Joe Taslim, Donny Alamsyah, Yayan Ruhian, Pierre Gruno, Ray Sahetapy', 'Gareth Evans', 'Action, Thriller, Crime', 2012, 'Celluloid Dreams, PT. Merantau Films, XYZ Films, Stage 6 Films', '101', 3.7, 'ID', 'Bahasa indonesia', 'https://image.tmdb.org/t/p/w500/Abnm1Ws3JH0ReCfEhLMPwPcMcGO.jpg', 'Deep in the heart of Jakarta\'s slums lies an impenetrable safe house for the world\'s most dangerous killers and gangsters. Until now, the run-down apartment block has been considered untouchable to even the bravest of police. Cloaked under the cover of pre-dawn darkness and silence, an elite swat team is tasked with raiding the safe house in order to take down the notorious drug lord that runs it.  But when a chance encounter with a spotter blows their cover and news of their assault reaches the drug lord, the building\'s lights are cut and all the exits blocked. Stranded on the sixth floor with no way out, the unit must fight their way through the city\'s worst to survive their mission. Starring Indonesian martial arts sensation Iko Uwais.'),
(1095, 1083381, 'Backrooms', 'Kane Parsons', 'Chiwetel Ejiofor, Renate Reinsve, Finn Bennett, Lukita Maxwell, Mark Duplass, Avan Jogia', 'Kane Parsons', 'Horror, Mystery, Science Fiction', 2026, 'Atomic Monster, 21 Laps Entertainment, A24, Phobos, The North Road Company', '111', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', 'A strange doorway appears in the basement of a furniture showroom.'),
(1096, 1368337, 'The Odyssey', 'Christopher Nolan', 'Matt Damon, Tom Holland, Anne Hathaway, Robert Pattinson, Himesh Patel, Charlize Theron', 'Christopher Nolan', 'Adventure, Action, Fantasy', 2026, 'Universal Pictures, Syncopy', '173', 4.0, 'GB, US', 'English', 'https://image.tmdb.org/t/p/w500/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', 'Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.'),
(1097, 454639, 'Masters of the Universe', 'Travis Knight', 'Nicholas Galitzine, Camila Mendes, Idris Elba, Jared Leto, Alison Brie, Jóhannes Haukur Jóhannesson', 'Chris Butler, Aaron Nee, Adam Nee', 'Action, Fantasy, Science Fiction', 2026, 'Escape Artists, Mattel Studios, Amazon MGM Studios', '141', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/oRuyGUHdoaQxWP3SDfafGkStxTC.jpg', 'After being separated for 15 years, the Sword of Power leads Prince Adam back to Eternia, where he discovers his home shattered under the fiendish rule of Skeletor. To save his family and his world, Adam must join forces with his closest allies, Teela and Duncan/Man-At-Arms, and embrace his true destiny as He-Man — the most powerful man in the universe.'),
(1098, 3082, 'Modern Times', 'Charlie Chaplin', 'Charlie Chaplin, Paulette Goddard, Henry Bergman, Tiny Sandford, Chester Conklin, Hank Mann', 'Charlie Chaplin', 'Comedy, Drama, Romance', 1936, 'Charles Chaplin Productions', '87', 4.1, 'US', 'No Language', 'https://image.tmdb.org/t/p/w500/7uoiKOEjxBBW0AgDGQWrlfGQ90w.jpg', 'A bumbling tramp desires to build a home with a young woman, yet is thwarted time and time again by his lack of experience and habit of being in the wrong place at the wrong time...'),
(1099, 1228710, 'The Mandalorian and Grogu', 'Jon Favreau', 'Pedro Pascal, Jeremy Allen White, Sigourney Weaver, Brendan Wayne, Lateef Crowder, Steve Blum', 'Jon Favreau', 'Action, Adventure, Science Fiction', 2026, 'Lucasfilm Ltd., Fairview Entertainment', '132', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/7GV5rrUJf0BRUhoh2cyFoeNthlQ.jpg', 'The evil Empire has fallen, and Imperial warlords remain scattered throughout the galaxy. As the fledgling New Republic works to protect everything the Rebellion fought for, they have enlisted the help of legendary Mandalorian bounty hunter Din Djarin and his young apprentice Grogu.'),
(1100, 1081003, 'Supergirl', 'Craig Gillespie', 'Milly Alcock, Eve Ridley, Matthias Schoenaerts, Jason Momoa, David Krumholtz, Emily Beecham', 'Craig Gillespie', 'Action, Adventure, Science Fiction', 2026, 'DC Studios, Troll Court Entertainment, The Safran Company, Domain Entertainment', '108', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/1QCWdqzTfh2x9UylVpspIU6QTuM.jpg', 'When an unexpected and ruthless adversary strikes too close to home, Kara Zor-El, aka Supergirl, reluctantly joins forces with an unlikely companion on an epic, interstellar journey of vengeance and justice.'),
(1101, 969681, 'Spider-Man: Brand New Day', 'Destin Daniel Cretton', 'Tom Holland, Zendaya, Mark Ruffalo, Jon Bernthal, Jacob Batalon, Sadie Sink', 'Destin Daniel Cretton', 'Science Fiction, Action, Adventure', 2026, 'Marvel Studios, Columbia Pictures, Pascal Pictures, TSG Entertainment', '145', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/iPOn6DinuVyLY17YM9mKuPofV08.jpg', 'Fighting crime full-time as Spider-Man in a world that doesn\'t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.'),
(1102, 12092, 'Alice in Wonderland', 'Clyde Geronimi', 'Kathryn Beaumont, Ed Wynn, Richard Haydn, Sterling Holloway, Jerry Colonna, Verna Felton', 'Clyde Geronimi, Wilfred Jackson', 'Animation, Family, Fantasy, Adventure', 1951, 'Walt Disney Productions', '75', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/20cvfwfaFqNbe9Fc3VEHJuPRxmn.jpg', 'On a golden afternoon, wildly curious young Alice tumbles into the burrow and enters the merry, madcap world of Wonderland full of whimsical escapades.'),
(1103, 11544, 'Lilo &amp; Stitch', 'Dean DeBlois', 'Daveigh Chase, Chris Sanders, Tia Carrere, David Ogden Stiers, Kevin McDonald, Ving Rhames', 'Chris Sanders, Dean DeBlois', 'Animation, Family, Comedy, Science Fiction', 2002, 'Walt Disney Pictures', '85', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/cFuLvQJPoZpuruAtN3rVnMmLIH8.jpg', 'As Stitch, a runaway genetic experiment from a faraway planet, wreaks havoc on the Hawaiian Islands, he becomes the mischievous adopted alien &quot;puppy&quot; of an independent little girl named Lilo and learns about loyalty, friendship, and ʻohana, the Hawaiian tradition of family.'),
(1104, 420817, 'Aladdin', 'Guy Ritchie', 'Will Smith, Mena Massoud, Naomi Scott, Marwan Kenzari, Navid Negahban, Nasim Pedrad', 'John August, Guy Ritchie', 'Adventure, Fantasy, Romance, Family', 2019, 'Walt Disney Pictures, Rideback', '127', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/ykUEbfpkf8d0w49pHh0AD2KrT52.jpg', 'A kindhearted street urchin named Aladdin embarks on a magical adventure after finding a lamp that releases a wisecracking genie while a power-hungry Grand Vizier vies for the same lamp that has the power to make their deepest wishes come true.'),
(1105, 420818, 'The Lion King', 'Jon Favreau', 'Chiwetel Ejiofor, John Oliver, Donald Glover, James Earl Jones, John Kani, Alfre Woodard', 'Jeff Nathanson', 'Adventure, Drama, Family, Animation', 2019, 'Walt Disney Pictures, Fairview Entertainment', '118', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/dzBtMocZuJbjLOXvrl4zGYigDzh.jpg', 'Simba idolizes his father, King Mufasa, and takes to heart his own royal destiny. But not everyone in the kingdom celebrates the new cub&#039;s arrival. Scar, Mufasa&#039;s brother—and former heir to the throne—has plans of his own. The battle for Pride Rock is ravaged with betrayal, tragedy and drama, ultimately resulting in Simba&#039;s exile. With help from a curious pair of newfound friends, Simba will have to figure out how to grow up and take back what is rightfully his.'),
(1106, 321612, 'Beauty and the Beast', 'Bill Condon', 'Emma Watson, Dan Stevens, Luke Evans, Kevin Kline, Emma Thompson, Ewan McGregor', 'Stephen Chbosky, Evan Spiliotopoulos', 'Family, Fantasy, Romance', 2017, 'Walt Disney Pictures, Mandeville Films', '129', 3.5, 'US', 'Français, English', 'https://image.tmdb.org/t/p/w500/hKegSKIDep2ewJWPUQD7u0KqFIp.jpg', 'A live-action adaptation of Disney&#039;s version of the classic tale of a cursed prince and a beautiful young woman who helps him break the spell.'),
(1107, 11224, 'Cinderella', 'Clyde Geronimi', 'Ilene Woods, Eleanor Audley, Verna Felton, Claire Du Brey, Rhoda Williams, James MacDonald', 'Hamilton Luske, Clyde Geronimi', 'Family, Fantasy, Animation, Romance', 1950, 'Walt Disney Productions', '74', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/4nssBcQUBadCTBjrAkX46mVEKts.jpg', 'Cinderella has faith her dreams of a better life will come true. With help from her loyal mice friends and a wave of her Fairy Godmother&#039;s wand, Cinderella&#039;s rags are magically turned into a glorious gown and off she goes to the Royal Ball. But when the clock strikes midnight, the spell is broken, leaving a single glass slipper... the only key to the ultimate fairy-tale ending!'),
(1108, 9325, 'The Jungle Book', 'Wolfgang Reitherman', 'Bruce Reitherman, Phil Harris, Sebastian Cabot, George Sanders, Sterling Holloway, Louis Prima', 'Wolfgang Reitherman', 'Family, Animation, Adventure', 1967, 'Walt Disney Productions', '78', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/yN1kuupnPTLUprgfvC5WapgrxG4.jpg', 'The boy Mowgli makes his way to the man-village with Bagheera, the wise panther. Along the way he meets jazzy King Louie, the hypnotic snake Kaa and the lovable, happy-go-lucky bear Baloo, who teaches Mowgli &quot;The Bare Necessities&quot; of life and the true meaning of friendship.'),
(1109, 9587, 'Little Women', 'Gillian Armstrong', 'Winona Ryder, Trini Alvarado, Samantha Mathis, Kirsten Dunst, Claire Danes, Christian Bale', 'Robin Swicord', 'Drama, Romance', 1994, 'Di Novi Pictures, Columbia Pictures', '115', 3.6, 'US', 'English, Deutsch, Français', 'https://image.tmdb.org/t/p/w500/1ZzH1XMcKAe5NdrKL5MfcqZHHsZ.jpg', 'Four sisters come of age in America in the aftermath of the Civil War.'),
(1110, 3035, 'Frankenstein', 'James Whale', 'Colin Clive, Mae Clarke, John Boles, Boris Karloff, Edward Van Sloan, Frederick Kerr', 'Francis Edward Faragoh, Garrett Fort', 'Drama, Horror, Science Fiction', 1931, 'Universal Pictures', '70', 3.7, 'US', 'English, Latin', 'https://image.tmdb.org/t/p/w500/mu6wHwH0IwCCaEYtpqujuPJYat1.jpg', 'Henry Frankenstein pieces together body parts in the hope of bringing a human-like creature to life. The mad scientist’s dreams are shattered by his monstrous creation awakening with rage to a world that hates and fears him.'),
(1111, 653, 'Nosferatu', 'F. W. Murnau', 'Max Schreck, Gustav von Wangenheim, Greta Schröder, Georg H. Schnell, Ruth Landshoff, Gustav Botz', 'Henrik Galeen', 'Horror, Fantasy', 1922, 'Prana-Film', '94', 3.8, 'DE', 'No Language', 'https://image.tmdb.org/t/p/w500/zv7J85D8CC9qYagAEhPM63CIG6j.jpg', 'The mysterious Count Orlok summons a happily married real estate agent to his castle, located up in the Transylvanian mountains, to finalise a terrifying deal.');
INSERT INTO `peliculas` (`idPelicula`, `idApi`, `nombrePelicula`, `directorPelicula`, `actorPelicula`, `guionistaPelicula`, `generoPelicula`, `anoPelicula`, `companiaPelicula`, `duracionPelicula`, `ratingAvgPelicula`, `paisPelicula`, `idiomaPelicula`, `posterPelicula`, `sinopsisPelicula`) VALUES
(1112, 997294, 'Close Your Eyes', 'Víctor Erice', 'Manolo Solo, Jose Coronado, Ana Torrent, Petra Martínez, María León, Mario Pardo', 'Michel Gaztambide, Víctor Erice', 'Drama, Mystery', 2023, 'Tandem Films, Pampa Films, Pecado Films, Nautilus Films, TVE, Movistar Plus+, Canal Sur, EiTB, TeleMadrid', '169', 3.5, 'AR, ES', 'Español', 'https://image.tmdb.org/t/p/w500/czUKm6JUutIg55EcRJ7CRAAzFMU.jpg', 'Years after his mysterious disappearance, Julio Arenas, a famous Spanish actor, is back in the news thanks to a television program.'),
(1113, 926899, 'The House', 'Marc James Roels', 'Mia Goth, Matthew Goode, Claudie Blakley, Eleanor De Swaef-Roels, Mark Heap, Stephanie Cole', 'Marc James Roels, Niki Lindroth von Bahr', 'Animation, Drama, Comedy, Horror, Fantasy', 2022, 'Nexus Studios', '97', 3.5, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/xhE1EYcD6U7m5R8AT7yf29CCxia.jpg', 'Across different eras, a poor family, an anxious developer and a fed-up landlady become tied to the same mysterious house in this animated dark comedy.'),
(1114, 34106, 'You Can&#039;t Take It with You', 'Frank Capra', 'Jean Arthur, Lionel Barrymore, James Stewart, Edward Arnold, Mischa Auer, Ann Miller', 'Robert Riskin', 'Comedy, Romance', 1938, 'Columbia Pictures', '126', 3.7, 'US', 'English, Pусский', 'https://image.tmdb.org/t/p/w500/9JltqbDyWstYW6gnvqDO6L5bOrx.jpg', 'Alice, the only relatively normal member of the eccentric Sycamore family, falls in love with Tony Kirby, but his wealthy banker father and snobbish mother strongly disapprove of the match. When the Kirbys are invited to dinner to become better acquainted with their future in-laws, things don&#039;t turn out the way Alice had hoped.'),
(1115, 975511, 'The Return', 'Uberto Pasolini', 'Ralph Fiennes, Juliette Binoche, Charlie Plummer, Marwan Kenzari, Claudio Santamaria, Ángela Molina', 'Uberto Pasolini', 'History, Drama, Adventure', 2024, 'Picomedia, RAI Cinema, Redwave Films, Heretic, Kabo Films, Marvelous Productions, Ithaca Films, Greek Film Centre, ERT, UK Global Screen Fund, MiC, CNC', '116', 3.3, 'FR, GR, IT, GB', 'English', 'https://image.tmdb.org/t/p/w500/xSj6EbdwHs3MFT2tRj9L3I7TE5j.jpg', 'After twenty years away, Odysseus washes up on the shores of Ithaca, haggard and unrecognizable. The king has finally returned home, but much has changed in his kingdom since he left to fight in the Trojan war.'),
(1116, 1172676, 'Poison', 'Wes Anderson', 'Benedict Cumberbatch, Dev Patel, Ben Kingsley, Ralph Fiennes, Eliel Ford, Benoît Herlin', 'Wes Anderson', 'Comedy, Drama, Thriller', 2023, 'American Empirical Pictures, Indian Paintbrush', '17', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/IQG49DUJw5DsgcNbW0NfagiDOs.jpg', 'When a poisonous snake slithers onto an Englishman&#039;s stomach in India, his associate and a doctor race to save him.'),
(1117, 338969, 'The Toxic Avenger Unrated', 'Macon Blair', 'Peter Dinklage, Jacob Tremblay, Taylour Paige, Julia Davis, Jonny Coyne, Elijah Wood', 'Macon Blair', 'Action, Comedy, Science Fiction', 2025, 'Legendary Pictures, Troma Entertainment', '102', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/cCWojb6N9UcTzNVtS4bOM3vQ30x.jpg', 'When a downtrodden janitor, Winston Gooze, is exposed to a catastrophic toxic accident, he’s transformed into a new kind of hero: The Toxic Avenger. Now, Toxie must rise from outcast to savior, taking on ruthless corporate overlords and corrupt forces who threaten his son, his friends, and his community.'),
(1118, 588001, 'Despite Everything', 'Gabriela Tagliavini', 'Blanca Suárez, Macarena García, Amaia Salamanca, Belén Cuesta, Maxi Iglesias, Juan Diego', 'Helena Rhee, Eugene B. Rhee', 'Comedy', 2019, 'Cinephile, Bambú Producciones', '75', 3.0, 'ES', 'Français, English, Español', 'https://image.tmdb.org/t/p/w500/jeclnbGov6lbHu8o1ugcOBCUBlU.jpg', 'Sara, Lucía, Sofía and Claudia are sisters, 4 modern women with very different personalities, who come together at their mother&#039;s funeral, after which they discover the man they&#039;ve all called &quot;dad&quot; throughout their lives is not really their father. They embark on a quest to discover who their real fathers are, discovering more about themselves, their mother, and their lives.'),
(1119, 958196, 'Inside', 'Vasilis Katsoupis', 'Willem Dafoe, Gene Bervoets, Eliza Stuyck, Andrew Blumenthal, Vincent Eaton, Daniel White', 'Vasilis Katsoupis', 'Thriller, Drama', 2023, 'A Private View, Heretic, Schiwago Film, MMC Movies, BNP Paribas Fortis, ERT', '106', 2.8, 'GR', 'English, Português, Deutsch', 'https://image.tmdb.org/t/p/w500/dXsiWJWwGwYwOQ6DfYFt5pPBMwT.jpg', 'An art thief trapped in a New York penthouse after his heist doesn&#039;t go as planned. Locked inside with nothing but priceless works of art, he must use all his cunning and invention to survive.'),
(1120, 23437, 'A Nightmare on Elm Street', 'Samuel Bayer', 'Rooney Mara, Kyle Gallner, Jackie Earle Haley, Katie Cassidy, Thomas Dekker, Kellan Lutz', 'Wesley Strick, Eric Heisserer', 'Horror, Mystery, Thriller', 2010, 'Platinum Dunes, New Line Cinema', '95', 2.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/nsmW28GcNabCUZfP5YtUEe8Li0f.jpg', 'Teenagers Nancy, Quentin, Kris, Jesse and Dean are all neighborhood friends who begin having the same dream of a horribly disfigured man who wears a tattered sweater and a glove made of knives. The man terrorizes them in their dreams, and the only escape is to wake up. But when, one by one, they start dying violently, the friends realize that what happens in the dream world is real, and the only way to stay alive is to stay awake.'),
(1121, 896151, 'Blitz', 'Steve McQueen', 'Elliott Heffernan, Saoirse Ronan, Benjamin Clementine, Paul Weller, Stephen Graham, Harris Dickinson', 'Steve McQueen', 'War, Drama, History', 2024, 'Working Title Films, New Regency Pictures, Apple Studios, Lammas Park', '120', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/e9tyjbF2rugENtBolTtEhHOXgzD.jpg', 'In World War II London, nine-year-old George is evacuated to the countryside by his mother, Rita, to escape the bombings. Defiant and determined to return to his family, George embarks on an epic, perilous journey back home as Rita searches for him.'),
(1122, 616446, 'Brothers', 'Max Barbakow', 'Josh Brolin, Peter Dinklage, Glenn Close, Brendan Fraser, Taylour Paige, M. Emmet Walsh', 'Macon Blair', 'Action, Comedy, Crime', 2024, 'Mad Chance, Brolin Productions, Legendary Pictures, Estuary Films', '89', 3.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/Akweo95FGyDpucYVT81h0SbX8Ky.jpg', 'A reformed criminal&#039;s attempt at going straight is derailed when he reunites with his sanity-testing twin brother on a road trip for the score of a lifetime. Dodging bullets, the law, and an overbearing mother along the way, they must heal their severed family bond before they end up killing each other.'),
(1123, 574376, 'Eye for an Eye', 'Paco Plaza', 'Luis Tosar, María Vázquez, Ismael Martínez, Pablo Guisa Koestinger, Daniel Currás, María Luisa Mayol', 'Paco Plaza', 'Drama, Thriller, Crime', 2019, 'Atresmedia, Vaca Films, Quien a hierro mata, Sony Pictures International Productions, Film Constellation, Ministerio de Educación, Cultura y Deporte, Xunta de Galicia, Canal+, MEDIA Programme of the European Union, Playtime', '107', 3.3, 'BE, ES, FR, GB', 'Español, Galego', 'https://image.tmdb.org/t/p/w500/3WEJAWFusNeZIJDNYxeIPytuZ1g.jpg', 'Mario, an exemplary man, lives in a village on the Galician coast. In the old people’s home, where he works as a nurse, everyone appreciates him. When the best known narco in the area, Antonio Padín, recently released from prison, enters the residence, Mario tries to make Antonio feel at home.  Now, Padín&#039;s two sons, Kike and Toño, are in charge of the family business. The failure of an operation will put Kike in jail and cause them to owe a large debt to a Colombian supplier. Toño will turn to the nurse to try to convince his father to assume the debt. But Mario has his own plans.'),
(1124, 1422096, 'Good Boy', 'Ben Leonberg', 'Shane Jensen, Arielle Friedman, Larry Fessenden, Stuart Rudin, Anya Krawcheck, Hunter Goetz', 'Ben Leonberg', 'Horror', 2025, 'What’s Wrong with Your Dog?', '73', 3.3, 'US', 'English', 'https://image.tmdb.org/t/p/w500/daInKxjoRNLFWIus64fHAy91V0k.jpg', 'A loyal dog moves to a rural family home with his owner Todd, only to discover supernatural forces lurking in the shadows. As dark entities threaten his human companion, the brave pup must fight to protect the one he loves most.'),
(1125, 12477, 'Grave of the Fireflies', 'Isao Takahata', 'Tsutomu Tatsumi, Ayano Shiraishi, Yoshiko Shinohara, Akemi Yamaguchi, Masayo Sakai, Kozo Hashida', 'Isao Takahata', 'Animation, Drama, War', 1988, 'Studio Ghibli', '89', 4.2, 'JP', '日本語', 'https://image.tmdb.org/t/p/w500/k9tv1rXZbOhH7eiCk378x61kNQ1.jpg', 'In the final months of World War II, 14-year-old Seita and his sister Setsuko are orphaned when their mother is killed during an air raid in Kobe, Japan. After a falling out with their aunt, they move into an abandoned bomb shelter. With no surviving relatives and their emergency rations depleted, Seita and Setsuko struggle to survive.'),
(1126, 41110, 'I Am Love', 'Luca Guadagnino', 'Tilda Swinton, Flavio Parenti, Edoardo Gabbriellini, Alba Rohrwacher, Pippo Delbono, Maria Paiato', 'Walter Fasano, Ivan Cotroneo, Barbara Alberti', 'Drama, Romance', 2010, 'First Sun, Mikado Film, RAI Cinema, Dolce Vita Productions, Pixeldna', '120', 3.4, 'IT, GB', 'English, Italiano, Pусский', 'https://image.tmdb.org/t/p/w500/ss57QaZX5OE3YxoTZeKW5Y6U83S.jpg', 'Emma has left Russia to live with her husband in Italy. Now a member of a powerful industrial family, she is the respected mother of three, but feels unfulfilled. One day, Antonio, a talented chef and her son&#039;s friend, makes her senses kindle.'),
(1127, 1000837, 'I&#039;m Still Here', 'Walter Salles', 'Fernanda Torres, Fernanda Montenegro, Selton Mello, Valentina Herszage, Maria Manoella, Bárbara Luz', 'Murilo Hauser, Heitor Lorega', 'Drama, History', 2024, 'VideoFilmes, MACT Productions, RT Features, ARTE France Cinéma, Conspiração Filmes, Globoplay', '138', 3.9, 'BR', 'Português', 'https://image.tmdb.org/t/p/w500/gZnsMbhCvhzAQlKaVpeFRHYjGyb.jpg', 'A woman married to a former politician during the 1971 military dictatorship in Brazil is forced to reinvent herself and chart a new course for her family after a violent and arbitrary act.'),
(1128, 788929, 'Lamb', 'Valdimar Jóhannsson', 'Noomi Rapace, Hilmir Snær Guðnason, Björn Hlynur Haraldsson, Ingvar E. Sigurðsson, Ester Bibi, Sigurður Elvar Viðarson', 'Valdimar Jóhannsson', 'Drama, Fantasy, Horror', 2021, 'Go to Sheep, Film i Väst, Chimney Sweden, Chimney Poland', '106', 3.2, 'IS', 'Íslenska', 'https://image.tmdb.org/t/p/w500/gP9yviboTGWGolqUZKIB1UkF1C2.jpg', 'An Icelandic couple live with their herd of sheep on a beautiful but remote farm. When they discover a mysterious newborn on their land, they decide to keep it and raise it as their own. This unexpected development and the prospects of a new family brings them much joy before ultimately destroying them.'),
(1129, 835504, 'Lullaby', 'Alauda Ruiz de Azúa', 'Laia Costa, Susi Sánchez, Ramón Barea, Mikel Bustamante, José Ramón Soroiz, Asier Valdestilla', 'Alauda Ruiz de Azúa', 'Drama', 2022, 'Encanta Films, Sayaka Producciones, Buena Pinta Media', '104', 3.6, 'ES', 'euskera, English, Español', 'https://image.tmdb.org/t/p/w500/4Zt8sVMHNq83C80OsABQIcW3fK5.jpg', 'Amaia has just become a mother, and the challenge is even more significant than she imagined. So when her partner has to leave for several weeks because of his job, she decides to spend time with her parents in a lovely coastal village in the Basque Country and hopefully share the responsibility of looking after her baby. However, she forgot that even when one becomes a parent, one never stops being a daughter.'),
(1130, 277834, 'Moana', 'Ron Clements', 'Auliʻi Cravalho, Dwayne Johnson, Rachel House, Temuera Morrison, Jemaine Clement, Nicole Scherzinger', 'Jared Bush', 'Adventure, Comedy, Family, Animation', 2016, 'Walt Disney Animation Studios', '107', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/m5MDZOIFEFlxGiLuAzWzFSsWcye.jpg', 'In Ancient Polynesia, when a terrible curse incurred by Maui reaches an impetuous Chieftain&#039;s daughter&#039;s island, she answers the Ocean&#039;s call to seek out the demigod to set things right.'),
(1131, 257, 'Oliver Twist', 'Roman Polanski', 'Barney Clark, Ben Kingsley, Jamie Foreman, Harry Eden, Edward Hardwicke, Leanne Rowe', 'Ronald Harwood', 'Crime, Drama, Family', 2005, 'ETIC Films, R.P. Productions, Runteam III Ltd.', '130', 3.4, 'GB', 'English', 'https://image.tmdb.org/t/p/w500/zhPdYZ3x2uanhM1SyBj4CuL6hSa.jpg', 'An orphan endures a harsh life in a workhouse before fleeing to London, where he falls in with a gang of juvenile pickpockets led by the criminal Fagin, and eventually finds a better life, exposing the cruelties of poverty and child labor in Victorian England.'),
(1132, 10693, 'Peter Pan', 'Clyde Geronimi', 'Bobby Driscoll, Kathryn Beaumont, Hans Conried, Bill Thompson, Heather Angel, Paul Collins', 'Clyde Geronimi, Wilfred Jackson', 'Animation, Family, Adventure, Fantasy', 1953, 'Walt Disney Productions', '77', 3.6, 'US', 'English', 'https://image.tmdb.org/t/p/w500/fJJOs1iyrhKfZceANxoPxPwNGF1.jpg', 'Leaving the safety of their nursery behind, Wendy, Michael and John follow Peter Pan to a magical world where childhood lasts forever. But while in Neverland, the kids must face Captain Hook and foil his attempts to get rid of Peter for good.'),
(1133, 871, 'Planet of the Apes', 'Franklin J. Schaffner', 'Charlton Heston, Roddy McDowall, Kim Hunter, Maurice Evans, James Whitmore, James Daly', 'Michael Wilson, Rod Serling', 'Science Fiction, Adventure, Drama, Action', 1968, 'APJAC Productions, 20th Century Fox', '112', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/2r9iKnlSYEk4daQadsXfcjHfIjQ.jpg', 'Astronaut Taylor crash lands on a distant planet ruled by apes who use a primitive race of humans for experimentation and sport. Soon Taylor finds himself among the hunted, his life in the hands of a benevolent chimpanzee scientist.'),
(1134, 6620, 'Sabrina', 'Billy Wilder', 'Humphrey Bogart, Audrey Hepburn, William Holden, Walter Hampden, John Williams, Martha Hyer', 'Billy Wilder, Ernest Lehman, Samuel A. Taylor', 'Comedy, Romance, Drama', 1954, 'Paramount Pictures', '114', 3.8, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/e1Po9NDrH7IJZhv89467gJH5FS0.jpg', 'After two years in Paris, chauffeur&#039;s daughter Sabrina returns home elegantly transformed and immediately catches the attention of David, the playboy son of her father&#039;s rich employers. David woos and wins Sabrina, who has always been in love with him, however their romance is threatened by David&#039;s serious older brother Linus, who runs the family business and is relying on David to marry an heiress in order for a crucial merger to take place.'),
(1135, 1124566, 'Sentimental Value', 'Joachim Trier', 'Renate Reinsve, Stellan Skarsgård, Inga Ibsdotter Lilleaas, Elle Fanning, Anders Danielsen Lie, Jesper Christensen', 'Joachim Trier', 'Drama, Comedy', 2025, 'Mer Film, Eye Eye Pictures, Lumen, Zentropa Entertainments, Komplizen Film, BBC Film, Film i Väst, Oslo Filmfond, Mediefondet Zefyr, Alaz Film, Don\'t Look Now, MK Productions, ARTE France Cinéma, Storyline Studios, Léger Production, ZDF/Arte', '133', 3.7, 'FR, NO', 'English, Deutsch, Norsk, svenska', 'https://image.tmdb.org/t/p/w500/pz9NCWxxOk3o0W3v1Zkhawrwb4i.jpg', 'Sisters Nora and Agnes reunite with their estranged father, the charismatic Gustav, a once-renowned director who offers stage actress Nora a role in what he hopes will be his comeback film. When Nora turns it down, she soon discovers he has given her part to an eager young Hollywood star.'),
(1136, 1155828, 'Sing Sing', 'Greg Kwedar', 'Colman Domingo, Clarence Maclin, Sean San Jose, Paul Raci, David \"Dap\" Giraudy, Patrick \"Preme\" Griffin', 'Greg Kwedar, Clint Bentley', 'Drama', 2024, 'Black Bear Pictures, Edith Productions, Marfa Peach Company', '107', 3.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/s0TPyI8QlMiktEiq3JVhea0zFhM.jpg', 'Divine G, imprisoned at Sing Sing for a crime he didn&#039;t commit, finds purpose by acting in a theatre group alongside other incarcerated men in this story of resilience, humanity, and the transformative power of art.'),
(1137, 995, 'Stagecoach', 'John Ford', 'Claire Trevor, John Wayne, George Bancroft, Andy Devine, Thomas Mitchell, John Carradine', 'Dudley Nichols', 'Western', 1939, 'Walter Wanger Productions', '96', 3.8, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/zgMnfnwWZ3nkx4t0bUDEKtW24O8.jpg', 'A group of people traveling on a stagecoach find their journey complicated by the threat of Geronimo, and learn something about each other in the process.'),
(1138, 11906, 'Suspiria', 'Dario Argento', 'Jessica Harper, Stefania Casini, Flavio Bucci, Miguel Bosé, Barbara Magnolfi, Susanna Javicoli', 'Daria Nicolodi, Dario Argento', 'Horror', 1977, 'Seda Spettacoli', '99', 3.7, 'IT', 'English, Italiano, Latin, Deutsch, Français', 'https://image.tmdb.org/t/p/w500/sEcvc9h1X3hYZdFgtiiKMm6RB3f.jpg', 'An American newcomer to a prestigious German ballet academy comes to realize that the school is a front for something sinister amid a series of grisly murders.'),
(1139, 848685, 'The Beasts', 'Rodrigo Sorogoyen', 'Marina Foïs, Denis Ménochet, Luis Zahera, Diego Anido, Marie Colomb, Machi Salgado', 'Rodrigo Sorogoyen, Isabel Peña', 'Thriller, Drama', 2022, 'Le Pacte, Arcadia Motion Pictures, Caballo Films, Cronos Entertainment AIE, TVE', '138', 3.8, 'FR', 'Galego, Español, Français', 'https://image.tmdb.org/t/p/w500/ytWMRYLlusyzMFFjyuFRY1liteR.jpg', 'Antoine and Olga, a French couple, have been living in a small village in Galicia for a long time. They practice eco-responsible agriculture and restore abandoned houses to facilitate repopulation. Everything should be idyllic except for their opposition to a wind turbine project that creates a serious conflict with their neighbors. The tension will rise to the point of irreparability.'),
(1140, 575604, 'The Call', 'Lee Chung-hyun', 'Park Shin-hye, Jeon Jong-seo, Kim Sung-ryung, Lee El, Park Ho-san, Oh Jung-se', 'Lee Chung-hyun', 'Thriller, Mystery, Science Fiction', 2020, 'Yong Film, Next Entertainment World', '112', 3.7, 'KR', '한국어/조선말', 'https://image.tmdb.org/t/p/w500/oz8hvZHg7tIdGwh0ErPRhobJKPR.jpg', 'Connected by phone in the same home but 20 years apart, a caller puts a woman’s past — and life — on the line to change her own fate.'),
(1141, 1002711, 'The Girls Are Alright', 'Itsaso Arana', 'Bárbara Lennie, Irene Escolar, Itziar Manero, Helena Ezquerro, Itsaso Arana, Julia León', 'Itsaso Arana', 'Drama', 2023, 'Los Ilusos Films, Elastica Films', '85', 3.1, 'ES', 'Español', 'https://image.tmdb.org/t/p/w500/oGsZmr4pDlza4Msw0iHpH0qZnNa.jpg', 'In the middle of summer, five women rehearse a play in an old mill, isolated from the world.'),
(1142, 103663, 'The Hunt', 'Thomas Vinterberg', 'Mads Mikkelsen, Thomas Bo Larsen, Annika, Lasse Fogelstrøm, Susse Wold, Anne Louise Hassing', 'Thomas Vinterberg, Tobias Lindholm', 'Drama', 2012, 'Zentropa International Sweden, Zentropa Entertainments, Film i Väst', '116', 4.0, 'DK', 'Dansk, Polski, English', 'https://image.tmdb.org/t/p/w500/jkixsXzRh28q3PCqFoWcf7unghT.jpg', 'A teacher lives a lonely life, all the while struggling over his son’s custody. His life slowly gets better as he finds love and receives good news from his son, but his new luck is about to be brutally shattered by an innocent little lie.'),
(1143, 564, 'The Mummy', 'Stephen Sommers', 'Brendan Fraser, Rachel Weisz, John Hannah, Arnold Vosloo, Patricia Velásquez, Oded Fehr', 'Stephen Sommers', 'Adventure, Action, Fantasy', 1999, 'Alphaville Films', '124', 3.5, 'US', 'English, العربية', 'https://image.tmdb.org/t/p/w500/yhIsVvcUm7QxzLfT6HW2wLf5ajY.jpg', 'Dashing legionnaire Rick O&#039;Connell stumbles upon the hidden ruins of Hamunaptra while in the midst of a battle to claim the area in 1920s Egypt. It has been over three thousand years since former High Priest Imhotep suffered a fate worse than death as a punishment for a forbidden love—along with a curse that guarantees eternal doom upon the world if he is ever awoken.'),
(1144, 115655, 'The World is Ours', 'Alfonso Sánchez', 'Alfonso Sánchez, Alberto López, Antonio Dechent, María Cabrera, Estrella Corrientes, Sergio Domínguez', 'Alfonso Sánchez', 'Comedy', 2012, 'Mundo Ficción', '86', 3.1, 'ES', 'Español', 'https://image.tmdb.org/t/p/w500/owKEGvWvR3aq2oNOtAOvo1gvm9.jpg', 'El Culebra and El Cabesa, a pair of criminals, decide to take a bank at gunpoint, dressed as penitents. The plan is simple: Get in, get the money, take off all the loot quickly and catch the first flight to Brazil. But things get complicated when a man on his fifties, victim of the economic crisis goes into the bank loaded with explosives, threatening suicide. What would be the easiest shot in history, becomes a nightmare carnival.'),
(1145, 1316092, '&quot;Wuthering Heights&quot;', 'Emerald Fennell', 'Margot Robbie, Jacob Elordi, Hong Chau, Alison Oliver, Shazad Latif, Martin Clunes', 'Emerald Fennell', 'Romance, Drama', 2026, 'MRC, LuckyChap Entertainment, Lie Still, Warner Bros. Pictures, Domain Entertainment', '137', 3.3, 'GB, US', 'English', 'https://image.tmdb.org/t/p/w500/3YBce6dTh1D5oCMITXk2S5QhPt.jpg', 'Tragedy strikes when Heathcliff falls in love with Catherine Earnshaw, a woman from a wealthy family in 18th-century England.'),
(1146, 950028, 'The Invite', 'Olivia Wilde', 'Seth Rogen, Olivia Wilde, Penélope Cruz, Edward Norton, Skip Howland, Mel Powell', 'Rashida Jones, Will McCormack', 'Comedy, Drama, Romance', 2026, 'Annapurna Pictures, FilmNation Entertainment, Permut Presentations', '107', 3.8, 'US', 'English, Español, Français', 'https://image.tmdb.org/t/p/w500/b7Dr8Chzse8VagexAporUu2RtLx.jpg', 'Joe and Angela’s marriage is on thin ice. When they invite their enigmatic upstairs neighbors for a dinner party, the night spirals into unexpected places. Have they reignited the spark or lit the match that burns it all down?'),
(1148, 58129, 'The Phantom Carriage', 'Victor Sjöström', 'Victor Sjöström, Hilda Borgström, Tore Svennberg, Astrid Holm, Concordia Selander, Lisa Lundholm', 'Victor Sjöström', 'Drama, Fantasy, Horror', 1921, 'SF Studios', '108', 3.9, 'SE', 'No Language', 'https://image.tmdb.org/t/p/w500/pNqUCe3vF0yi2VTjyZSLqTwahlj.jpg', 'An alcoholic, abusive ne&#039;er-do-well is shown the error of his ways through a legend that dooms the last person to die on New Year&#039;s Eve before the clock strikes twelve to take the reins of Death&#039;s chariot and work tirelessly collecting fresh souls for the next year.'),
(1156, 19, 'Metropolis', 'Fritz Lang', 'Gustav Fröhlich, Brigitte Helm, Alfred Abel, Rudolf Klein-Rogge, Theodor Loos, Fritz Rasp', 'Fritz Lang, Thea von Harbou', 'Drama, Science Fiction', 1927, 'UFA', '148', 4.0, 'DE', 'No Language', 'https://image.tmdb.org/t/p/w500/kr9wXRN23zLuWJIelahas1mtnYj.jpg', 'In a futuristic city sharply divided between the rich and the poor, the son of the city\'s mastermind meets a prophet who predicts the coming of a savior to mediate their differences.'),
(1157, 43020, 'The Colossus of Rhodes', 'Sergio Leone', 'Rory Calhoun, Lea Massari, Georges Marchal, Conrado San Martín, Ángel Aranda, Mabel Karr', 'Luciano Chitarrini, Ennio De Concini, Luciano Martino', 'Adventure, Drama, History', 1961, 'Produzioni Atlas Consorziate, Procusa, Comptoir Français de Productions Cinématographiques (CFPC), CTI (Cinema Television International), Cineproduzioni Associate', '127', 3.0, 'IT', 'Italiano', 'https://image.tmdb.org/t/p/w500/xb5PBtqe5rHJkuXwwJGxXwjUcZA.jpg', 'While on holiday in Rhodes, Athenian war hero Darios becomes involved in two different plots to overthrow the tyrannical king, one from Rhodian patriots and the other from sinister Phoenician agents.'),
(1158, 1084244, 'Toy Story 5', 'Andrew Stanton', 'Joan Cusack, Tom Hanks, Tim Allen, Conan O\'Brien, Scarlett Spears, Greta Lee', 'Andrew Stanton, Kenna Harris', 'Animation, Family, Comedy, Adventure', 2026, 'Pixar', '102', 3.7, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', 'When Bonnie receives a Lilypad tablet as a gift and becomes obsessed, Buzz, Woody, Jessie and the rest of the gang\'s jobs become exponentially harder when they have to go head to head with the all-new threat to playtime.'),
(1159, 642, 'Butch Cassidy and the Sundance Kid', 'George Roy Hill', 'Paul Newman, Robert Redford, Katharine Ross, Strother Martin, Henry Jones, Jeff Corey', 'George Roy Hill', 'Western', 1969, 'Campanile Productions, 20th Century Fox, George Roy Hill-Paul Monash Production, Newman-Foreman Company', '111', 3.8, 'US', 'English, Español', 'https://image.tmdb.org/t/p/w500/gFmmykF1Ym3OGzENo50nZQaD1dx.jpg', 'As the west rapidly becomes civilized, a pair of outlaws in 1890s Wyoming find themselves pursued by a posse and decide to flee to South America in hopes of evading the law.'),
(1162, 776, 'The Rules of the Game', 'Jean Renoir', 'Jean Renoir, Marcel Dalio, Nora Gregor, Julien Carette, Roland Toutain, Paulette Dubost', 'Jean Renoir', 'Drama, Comedy, Romance', 1939, 'La Nouvelle Edition Francaise, Franco London Films', '110', 3.7, 'FR', 'Français', 'https://image.tmdb.org/t/p/w500/8JOzt7uFZyshcuzCBmYU6CDJL4D.jpg', 'The Marquis de la Chesnaye and his wife host a weekend gala where a variety of complicated romantic and social entanglements between guests and servants lead to tragedy, all against the backdrop of a looming war.'),
(1167, 1102883, 'Mother Mary', 'David Lowery', 'Anne Hathaway, Michaela Coel, Hunter Schafer, FKA twigs, Sian Clifford, Kaia Gerber', 'David Lowery', 'Music, Drama, Thriller', 2026, 'A24, Augenschein Filmproduktion, Topic Studios, Sailor Bear, IPR.VC, Homebird Productions, Access Entertainment', '112', 2.7, 'US', 'English', 'https://image.tmdb.org/t/p/w500/uVcsN3yoHh7ZcJ6ecj1FJfv7dLa.jpg', 'Long-buried wounds rise to the surface when iconic pop star Mother Mary reunites with her estranged best friend and former costume designer Sam Anselm on the eve of her comeback performance.'),
(1168, 887, 'The Best Years of Our Lives', 'William Wyler', 'Dana Andrews, Fredric March, Harold Russell, Teresa Wright, Myrna Loy, Cathy O\'Donnell', 'Robert E. Sherwood', 'Drama, Romance, War', 1946, 'Samuel Goldwyn Productions', '171', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/gd5EoAU4MM57sW3vlWxJ0NMM8cV.jpg', 'It\'s the hope that sustains the spirit of every GI: the dream of the day when he will finally return home. For three WWII veterans, the day has arrived. But for each man, the dream is about to become a nightmare.'),
(1169, 19542, 'The Red Shoes', 'Michael Powell, Emeric Pressburger', 'Anton Walbrook, Marius Goring, Moira Shearer, Robert Helpmann, Léonide Massine, Albert Bassermann', 'Michael Powell, Emeric Pressburger', 'Drama, Romance', 1948, 'The Archers', '133', 4.0, 'GB', 'Pусский, English, Français', 'https://image.tmdb.org/t/p/w500/vPvpBWFWDvEXuQBkoYgA6A89GVp.jpg', 'A fledgling ballerina falls in love with a brilliant composer, but the jealous head of the ballet company plots to drive them apart.'),
(1170, 914, 'The Great Dictator', 'Charlie Chaplin', 'Charlie Chaplin, Paulette Goddard, Jack Oakie, Reginald Gardiner, Henry Daniell, Billy Gilbert', 'Charlie Chaplin', 'Comedy, War', 1940, 'Charles Chaplin Productions', '125', 4.1, 'US', 'English, Esperanto', 'https://image.tmdb.org/t/p/w500/nhMXB8GTdswYMCL9nepDZymJCOr.jpg', 'Dictator Adenoid Hynkel tries to expand his empire while a poor Jewish barber tries to avoid persecution from Hynkel\'s regime.'),
(1171, 8068, 'Desperado', 'Robert Rodriguez', 'Antonio Banderas, Salma Hayek Pinault, Joaquim de Almeida, Steve Buscemi, Cheech Marin, Carlos Gómez', 'Robert Rodriguez', 'Thriller, Action, Crime', 1995, 'Columbia Pictures, Los Hooligans Productions', '104', 3.5, 'US', 'English', 'https://image.tmdb.org/t/p/w500/e3gwpBeXpvGZsxUya9zNym5QXrw.jpg', 'El Mariachi plunges headfirst into the dark border underworld when he follows a trail of blood to the last of the infamous Mexican drug lords, Bucho, for an action-packed, bullet-riddled showdown. With the help of his friend and a beautiful bookstore owner, El Mariachi tracks Bucho, takes on his army of desperados, and leaves his own trail of blood.'),
(1172, 20139, 'The Children\'s Hour', 'William Wyler', 'Audrey Hepburn, Shirley MacLaine, James Garner, Miriam Hopkins, Fay Bainter, Karen Balkin', 'John Michael Hayes', 'Drama', 1961, 'The Mirisch Company, United Artists', '108', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/goyEWixvULM2IRN4KsKibyrJE4J.jpg', 'An unruly student at a private all-girls boarding school scandalously accuses the two women who run it of having a romantic relationship.'),
(1173, 30588, 'Monsieur Verdoux', 'Charlie Chaplin', 'Charlie Chaplin, Mady Correll, Allison Roddan, Robert Lewis, Audrey Betz, Martha Raye', 'Charlie Chaplin', 'Comedy, Crime, Drama', 1947, 'Charles Chaplin Productions, United Artists', '124', 3.9, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/mUPXIinTQsBdLlDaWiSl7GwQXVs.jpg', 'The film is about an unemployed banker, Henri Verdoux, and his sociopathic methods of attaining income. While being both loyal and competent in his work, Verdoux has been laid-off. To make money for his wife and child, he marries wealthy widows and then murders them. His crime spree eventually works against him when two particular widows break his normal routine.'),
(1174, 3001, 'How to Steal a Million', 'William Wyler', 'Audrey Hepburn, Peter O\'Toole, Eli Wallach, Hugh Griffith, Charles Boyer, Fernand Gravey', 'Harry Kurnitz', 'Comedy, Crime, Romance', 1966, 'World Wide Productions, 20th Century Fox', '123', 3.8, 'US', 'English', 'https://image.tmdb.org/t/p/w500/xaf3pwmITJvfz9Ab8DiGM8OOtBC.jpg', 'A woman must steal a statue from a Paris museum to help conceal her father\'s art forgeries.'),
(1175, 28971, 'Limelight', 'Charlie Chaplin', 'Charlie Chaplin, Claire Bloom, Nigel Bruce, Buster Keaton, Sydney Chaplin, Norman Lloyd', 'Charlie Chaplin', 'Romance, Drama, Music, Comedy', 1952, 'Celebrated Productions, United Artists', '137', 4.0, 'US', 'English', 'https://image.tmdb.org/t/p/w500/wNWQS4cPTVtyOPzMZ9HSjmOLZ97.jpg', 'A fading music hall comedian tries to help a despondent ballet dancer learn to walk and to again feel confident about life.'),
(1176, 1074074, 'The Beloved', 'Rodrigo Sorogoyen', 'Javier Bardem, Victoria Luengo, Melina Matthews, Malena Villa, Mourad Ouani, Pepa Gracia', 'Rodrigo Sorogoyen', 'Drama', 2026, 'Movistar Plus, Caballo Films, Le Pacte', '135', 3.5, 'ES', 'Español', 'https://image.tmdb.org/t/p/w500/whk02IOeEHz8KCYZGm3fF92zg0v.jpg', 'The acclaimed film director Esteban Martínez is a legend both for his films and for his past marked by violence and excess. For his new project, he offers his daughter Emilia a role under the pretext of helping her with her stalled acting career. Living together on set will foster a closeness they haven’t shared for years, but it will also reopen old wounds that never healed.'),
(1177, 1464883, 'The President\'s Cake', 'Hasan Hadi', 'Baneen Ahmed Nayyef, Sajad Mohamad Qasem, Waheed Thabet Khreibat, Rahim AlHaj, Muthanna Malaghi, Ahmad Qasem Saywan', 'Hasan Hadi', 'Drama', 2026, 'Maiden Voyage Pictures, Missing Piece Films, Spark Features, Working Barn Productions', '106', 3.7, 'US', 'العربية', 'https://image.tmdb.org/t/p/w500/uSrozVUxIUaer6FIUHHFtOdbqj8.jpg', 'While people across 1990’s Iraq struggle to survive, 9-year-old Lamia has been selected to prepare a cake to celebrate the President’s birthday. In a landscape of fear and scarcity, where basic ingredients are nearly impossible to find, Lamia sets out on a determined journey throughout the big city in search of eggs, flour, and sugar. Accompanied by her grandmother, her loyal friend Saeed, and her pet rooster Hindi, she navigates vendors and police officers along the way.'),
(1178, 3083, 'Mr. Smith Goes to Washington', 'Frank Capra', 'James Stewart, Jean Arthur, Claude Rains, Edward Arnold, Guy Kibbee, Thomas Mitchell', 'Sidney Buchman', 'Comedy, Drama', 1939, 'Columbia Pictures', '130', 3.9, 'US', 'English', 'https://image.tmdb.org/t/p/w500/nDjg1fbNyq15excNDl3acd2IqAk.jpg', 'After the death of a United States Senator, the idealistic Jefferson Smith is appointed as his replacement in Washington. The naive and earnest new senator soon finds himself battling political corruption.'),
(1179, 705, 'All About Eve', 'Joseph L. Mankiewicz', 'Bette Davis, Anne Baxter, George Sanders, Celeste Holm, Gary Merrill, Hugh Marlowe', 'Joseph L. Mankiewicz', 'Drama', 1950, '20th Century Fox', '139', 4.0, 'US', 'English, Français', 'https://image.tmdb.org/t/p/w500/blBzZaatPWVuWpXEnPscMA4Xp6m.jpg', 'From the moment she glimpses her idol at the stage door, Eve Harrington is determined to take the reins of power away from the great actress Margo Channing. Eve maneuvers her way into Margo\'s Broadway role, becomes a sensation and even causes turmoil in the lives of Margo\'s director boyfriend, her playwright and his wife. Only the cynical drama critic sees through Eve, admiring her audacity and perfect pattern of deceit.'),
(1180, 1101383, 'The End of Oak Street', 'David Robert Mitchell', 'Anne Hathaway, Ewan McGregor, Maisy Stella, Christian Convery, Jordan Alexa Davis, P.J. Byrne', 'David Robert Mitchell', 'Science Fiction, Mystery, Thriller', 2026, 'Warner Bros. Pictures, Domain Entertainment, Bad Robot, Jackson Pictures', '100', 3.4, 'US', 'English', 'https://image.tmdb.org/t/p/w500/fYXqpgPmHMphSF2W30GbTeJVIa5.jpg', 'After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.');
INSERT INTO `series` (`idSerie`, `idApi`, `nombreSerie`, `creadorSerie`, `directorSerie`, `actorSerie`, `companiaSerie`, `guionistaSerie`, `generoSerie`, `anoSerie`, `temporadasSerie`, `episodiosSerie`, `ratingAvgSerie`, `paisSerie`, `idiomaSerie`, `posterSerie`, `sinopsisSerie`) VALUES
(49, 1396, 'Breaking Bad', 'Vince Gilligan', 'Michelle MacLaren, Adam Bernstein', 'Bryan Cranston, Aaron Paul, Anna Gunn, RJ Mitte, Dean Norris, Betsy Brandt', 'Sony Pictures Television, High Bridge Productions, Gran Via Productions', 'Peter Gould, George Mastras, Moira Walley-Beckett', 'Drama, Crime', 2008, 5, 62, 4.5, 'United States of America', 'English, Deutsch, Español', 'https://image.tmdb.org/t/p/w500/anFx9aTOOYqgS3v7x3R84Kz67ly.jpg', 'Walter White, a New Mexico chemistry teacher, is diagnosed with Stage III cancer and given a prognosis of only two years left to live. He becomes filled with a sense of fearlessness and an unrelenting desire to secure his family\'s financial future at any cost as he enters the dangerous world of drugs and crime.'),
(50, 70523, 'Dark', 'Baran bo Odar, Jantje Friese', 'Baran bo Odar', 'Louis Hofmann, Lisa Vicari, Andreas Pietschmann, Maja Schöne, Stephan Kampwirth, Paul Lux', 'Wiedemann & Berg Television', 'Jantje Friese, Marc O. Seng, Martin Behnke', 'Crime, Drama, Sci-Fi & Fantasy, Mystery', 2017, 3, 26, 4.2, 'Germany', 'Deutsch', 'https://image.tmdb.org/t/p/w500/apbrbWs8M9lyOpJYU5WXrpFbk1Z.jpg', 'A missing child sets four families on a frantic hunt for answers as they unearth a mind-bending mystery that spans three generations.'),
(51, 1399, 'Game of Thrones', 'David Benioff, D. B. Weiss', 'David Nutter, Alan Taylor', 'Peter Dinklage, Kit Harington, Nikolaj Coster-Waldau, Lena Headey, Emilia Clarke, Maisie Williams', 'Revolution Sun Studios, Television 360, Generator Entertainment, Bighead Littlehead, Grok! Television, HBO', 'George R.R. Martin, David Benioff, D. B. Weiss', 'Sci-Fi & Fantasy, Drama, Action & Adventure', 2011, 73, 73, 4.3, 'United Kingdom, United States of America', 'English', 'https://image.tmdb.org/t/p/w500/37sTgAG9QardbdzCq51FoUw1Ijb.jpg', 'Seven noble families fight for control of the mythical land of Westeros. Friction between the houses leads to full-scale war. All while a very ancient evil awakens in the farthest north. Amidst the war, a neglected military order of misfits, the Night\'s Watch, is all that stands between the realms of men and icy horrors beyond.'),
(53, 95396, 'Severance', 'Dan Erickson', 'Ben Stiller, Aoife McArdle', 'Adam Scott, Britt Lower, Tramell Tillman, Zach Cherry, Jen Tullock, Dichen Lachman', 'Endeavor Content, Red Hour, Fifth Season, Animals & People, Westward', 'Anna Ouyang Moench, Helen Leigh, Dan Erickson', 'Drama, Mystery, Sci-Fi & Fantasy', 2022, 3, 19, 4.2, 'United States of America', 'English', 'https://image.tmdb.org/t/p/w500/pPHpeI2X1qEd1CS1SeyrdhZ4qnT.jpg', 'Mark leads a team of office workers whose memories have been surgically divided between their work and personal lives. When a mysterious colleague appears outside of work, it begins a journey to discover the truth about their jobs.'),
(55, 247767, 'The Studio', 'Peter Huyck, Alex Gregory, Seth Rogen, Frida Perez, Evan Goldberg', 'Evan Goldberg, Seth Rogen', 'Seth Rogen, Catherine O\'Hara, Ike Barinholtz, Chase Sui Wonders, Kathryn Hahn, Keyla Monterroso Mejia', 'Point Grey Pictures, Lionsgate Television, Coytesville Productions, Contractually Obligated Two Second Half Screen Vanity Card Productions', 'Alex Gregory, Peter Huyck, Evan Goldberg', 'Comedy, Drama', 2025, 2, 10, 3.9, 'United States of America', 'English', 'https://image.tmdb.org/t/p/w500/2c6ofLTa5CRfeQjVA1bWiYBdxQN.jpg', 'Desperate for celebrity approval, the newly appointed head of a movie studio and his executive team at Continental Studios must juggle corporate demands with creative ambitions as they try to keep movies alive and relevant.');
INSERT INTO `seriestemporadas` (`idTemporada`, `idApi`, `idSerie`, `nombreTemporada`, `numeroTemporada`, `directorTemporada`, `guionistaTemporada`, `actorTemporada`, `episodiosTemporada`, `anoTemporada`, `ratingAvgTemporada`, `posterTemporada`, `sinopsisTemporada`) VALUES
(51, 3628, 51, 'Game of Thrones - Season 4', 4, 'Alex Graves, Alik Sakharov', 'George R.R. Martin, David Benioff, D. B. Weiss', 'Peter Dinklage, Kit Harington, Nikolaj Coster-Waldau, Lena Headey, Emilia Clarke, Liam Cunningham', 10, 2014, 4.3, 'https://image.tmdb.org/t/p/w500/jXIMScXE4J4EVHUba1JgxZnWbo4.jpg', 'The War of the Five Kings is drawing to a close, but new intrigues and plots are in motion, and the surviving factions must contend with enemies not only outside their ranks, but within.'),
(52, 124476, 50, 'Dark - Season 2', 2, 'Baran bo Odar', 'Jantje Friese, Ronny Schalk, Martin Behnke', 'Louis Hofmann, Lisa Vicari, Andreas Pietschmann, Maja Schöne, Stephan Kampwirth, Paul Lux', 8, 2019, 4.3, 'https://image.tmdb.org/t/p/w500/c8Aq3By7Z5JBIiue9WeDP0N3Zlu.jpg', 'Six months after the disappearances of Mikkel, Jonas and Ulrich, Winden\'s web of mysteries deepens -- and the fate of the world hangs in the balance.');
